/* ÇEVİRİ ar · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ar","olay",{
"OLAYLAR:1299-01:0":{"b": ["تأسيس الإمارة العثمانية", "9f0b7c0a"], "d": ["يُعدّ شروع عثمان غازي، من قبيلة قايي، في التحرك مستقلًّا في ناحية سوغوت ودومانيج البداية التقليدية لتأسيس الدولة العثمانية، بينما يرى بعض المؤرخين أن انتصار بافيوس عام 1302 هو نقطة التحول الحقيقية. وقد جمعت الإمارة القوة بسرعة بفضل غارات الغزو انطلاقًا من موقعها في الثغر البيزنطي. وفي هذه البيئة التي كان إرث السلاجقة يتفكك فيها، جمع عثمان غازي حوله الأخيّة والغزاة والتركمان الرحّل؛ ويُعدّ الرباط الذي أقامه مع الشيخ أده بالي أساس المشروعية المعنوية للإمارة. الأماكن الأخرى التي انضمت في التاريخ نفسه: إينه غول، يارحصار.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["فتح بورصة", "98c727fa"], "d": ["استسلمت بورصة، التي ظلّت سنوات طويلة تحت الحصار، لأورخان غازي الذي أدار المرحلة الأخيرة من الحصار؛ واتُّخذت المدينة أول عاصمة كبرى للإمارة. ويُروى أن نبأ الفتح بُلّغ إلى عثمان غازي وهو على فراش الموت، وأنه دُفن في بورصة بحسب وصيته. وسرعان ما زُوّدت المدينة بالمساجد والعمائر والمدارس، فصارت نموذجًا للعمران العثماني المبكر.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["فتح إزنيق", "a846a811"], "d": ["استسلمت إزنيق (نيقية)، وهي من أهم مراكز البيزنطيين في الأناضول، لأورخان غازي بعد أن فقدت أمل المقاومة إثر انتصار بيلكانون عام 1329. وأُنشئت فيها أول مدرسة عثمانية، وبدأ علماء مثل داود القيصري التدريس فيها؛ وصارت المدينة مركز العلم في العصر المبكر. وحُوّلت كنيسة آيا صوفيا إلى مسجد، فكانت مثالًا مبكرًا على تقليد الفتح.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["فتح إزميت", "06a35035"], "d": ["بسقوط إزميت (نيقوميديا) دخل آخر حصن مهم للبيزنطيين في الجانب الآسيوي تحت الإدارة العثمانية؛ وصارت شبه جزيرة كوجه إيلي كلها، حتى الساحل المقابل لإسطنبول، أرضًا عثمانية. وهكذا سيطرت الإمارة على كامل سواحل مرمرة الجنوبية والشرقية، وهيّأت البنية التحتية للعبور إلى الروملي.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["قلعة جمبي — العبور إلى الروملي", "c2f0a07d"], "d": ["كان سليمان باشا، ابن أورخان غازي، قد اتخذ قلعة جمبي، التي أُعطيت في الحرب الأهلية البيزنطية، قاعدة له عام 1352؛ وبعد الزلزال الكبير الذي دمّر غاليبولي في مارس 1354 حُصّنت القلاع التي أُخليت بسرعة، فتحولت شبه الجزيرة إلى رأس جسر عثماني دائم. وهذه الخطوة، التي دعمها إسكان السكان التركمان المنقولين من الأناضول، هي بداية الوجود العثماني في القارة الأوروبية الذي سيمتد أكثر من 550 عامًا.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["فتح أدرنة", "2f54ebb0"], "d": ["حدّد الاستيلاء على أدرنة (أدريانوبل)، المدينة المفتاحية في تراقيا، القاعدة الرئيسة للفتوحات في البلقان واتجاهها؛ وتاريخ الفتح مختلف فيه في المصادر بين 1361 و1369. وبعد فترة قصيرة جُعلت المدينة عاصمة، معلنةً انتقال مركز ثقل الدولة إلى الروملي؛ وظلت دار الملك نحو 90 عامًا حتى فتح إسطنبول.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["اعتلاء مراد الأول العرش", "f8d48a26"], "d": ["نقل مراد الأول (خداوندكار)، الذي تولى العرش بوفاة أورخان غازي، الدولة في سلطنته التي دامت 27 عامًا من إمارة ثغرية إلى هيكل إمبراطورية. فوُضع أساس الجيش الإنكشاري بنظام البنجيك، وعُمّم نظام التيمار، وأُنشئت بكلربكية الروملي، وقوي نظام الوزارة. وصارت الفتوحات في البلقان في عهده سياسة دولة منتظمة.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["معركة كوسوفو الأولى — استشهاد مراد الأول", "10b8ddc9"], "d": ["هُزم التحالف البلقاني بقيادة الأمير لازار هزيمة حاسمة في سهل كوسوفو؛ ودخلت صربيا تحت السيادة العثمانية العليا. وطعن النبيلُ الصربي ميلوش أوبيليتش السلطانَ مراد الأول بخنجر وهو يتجول في ساحة المعركة فاستشهد — وهو السلطان العثماني الوحيد الذي مات في ساحة القتال. وأُجلس يلدريم بايزيد مكانه في المعسكر؛ وخُنق أخوه يعقوب جلبي، وكان ذلك من أولى الأمثلة المعروفة لتطبيق قتل الإخوة.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["انتصار نيكوبوليس", "75716e96"], "d": ["هُزم الجيش الصليبي الكبير، الذي اجتمع بدعوة من الملك المجري سيغيسموند وشاركت فيه فرسان فرنسيون وبورغونديون، هزيمة ساحقة أمام نيكوبوليس على ضفاف الدانوب على يد يلدريم بايزيد. وثبّت الانتصار السيادة العثمانية على بلغاريا؛ ولم تُنظَّم في أوروبا حملة صليبية كبرى طوال جيل كامل.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["معركة أنقرة — بداية فترة الفتنة", "b4a99d96"], "d": ["في الهزيمة الثقيلة التي لحقت بالعثمانيين أمام جيش تيمور في سهل تشوبوق وقع يلدريم بايزيد في الأسر، وتوفي في الأسر بعد بضعة أشهر. وأعاد تيمور إحياء الإمارات الأناضولية؛ وتفتتت الأراضي العثمانية بين أبناء بايزيد، وبدأ صراع على العرش دام 11 عامًا (فترة الفتنة). وقد ترسخت أهمية البنية المركزية في الذاكرة العثمانية في هذه الفترة، وهي أشد أزمة عاشتها الدولة منذ تأسيسها. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: داتشا، مرمريس، فتحية (ماكري)، سوكه، كوتاهية، أفيون، إسبارطة، مانيسا، آيدين، دنيزلي، موغلا، أنطاليا، قونية، قرمان، قيصري، قسطموني، بارتن، صفرانبولو، سامسون، سيواس، ملطية، بيشهر، سيفريحصار، قيرشهير، تشوروم، تشانقري، ينيشهير (بورصة)، إينه غول، قلعة أيدوس، جيويه، كوبروحصار (ينيشهير)، مرمرجق، آق حصار (باموقوفا)، مكجة، كستل، أولوباد، هارمانقايا، آق يازي، جزيرة إمرالي، قنديرة، مودانيا، يالوفا، قره مورسل، أرموتلو، جمليك (كيوس)، سوغوت، بيلجك، إسكيشهير، بورصة، إزنيق، إزميت، باليكسير، جناق قلعة، برغمة، أماسية، طوقات، جورلو، لولة برغاز، مالقرة، كشان، إبسالا، كيليد بحر، جرمن، إسكي زاغرا (ستارا زاغورا)، تتارباظارجق، إحتيمان، كوستندل، بتريتش، نيفروكوب (غوتسه ديلتشيف)، دراما، غاليبولي، جمبي، أدرنة، ديديموتيخون، قرق كليسة، تكيرداغ، فيليبه، صوفيا، نيش، فيدين، ترنوفو، وارنا، شومنو، سيليستر، نيكوبوليس، روسجق، سلانيك، سيريس، قوالة، أسكوب، مناستر، أوهريد، ينيشهير (لاريسا)، تيرهالا، إزدين (لاميا)، بليفن، غومولجينة، بيغا، دومانيج، قولاجة حصار، قره جة حصار، يارحصار، ديمبوس، كيتي (كته)، لفكه (عثمانلي)، لبلبجي حصار، قره جبوش، قره تكين، أبسو (هيبسو)، أدرانوس (أورهانلي)، بيلكانون (إسكي حصار)، غبزه، هريكه، سمندرة، كرماستي (مصطفى كمال باشا)، ميخاليتش (قره جابي)، كوستنجة، غولياز (أبولونيا).", "d34e55d5"]},
"OLAYLAR:1413-07:0":{"b": ["جلبي محمد يعيد توحيد الدولة", "03413dfd"], "d": ["وحّد محمد الأول أراضي الدولة تحت إدارة واحدة بعد أن هزم موسى جلبي في تشامورلو في الحساب الأخير بين الإخوة؛ ولذلك يُعدّ «المؤسس الثاني للدولة». فأُصلحت البنية الحكومية التي تآكلت في أثناء الفتنة، وتوازنت العلاقات مع الإمارات الأناضولية، واتُّبعت في الروملي سياسة سلم حذرة.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["ثورة الشيخ بدر الدين", "e0a072ca"], "d": ["اندلعت الحركة الدينية الاجتماعية التي نشأت حول الشيخ بدر الدين، الفقيه والمتصوف الكبير الذي تولى قضاء العسكر في فترة الفتنة، في وقت واحد مع ثورتي بوركلوجه مصطفى في قره بورون وطورلاق كمال في مانيسا. وقُمعت الثورات بالدماء؛ وأُلقي القبض على بدر الدين في دلي أورمان وأُعدم في سيريس. وقد ترك الحدث أثرًا عميقًا في الأدب وكتابة التاريخ بوصفه أقدم انتفاضة اجتماعية مهدوية كبرى في التاريخ العثماني.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["انتصار وارنا", "f739eedc"], "d": ["أُبيد في وارنا على يد مراد الثاني، الذي عاد إلى رأس الجيش وهو متنازل عن العرش، الجيشُ الصليبي المجري البولندي الذي نقض معاهدة سيجد وتقدم جنوبًا؛ وقُتل الملك الشاب لاديسلاس الثالث في ساحة المعركة. وأزال الانتصار آخر فرصة كبرى للتدخل الخارجي الرامي إلى تصفية الوجود العثماني في البلقان، وأمّن الطريق إلى فتح إسطنبول.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["معركة كوسوفو الثانية", "ebe0b662"], "d": ["هُزم جيش يانوش هونيادي، الذي أراد الثأر لوارنا، هزيمة حاسمة على يد مراد الثاني في معركة شاقة دامت ثلاثة أيام. وهي آخر معركة ميدانية كبرى خاضها الصليبيون ضد العثمانيين في البلقان؛ وبهذا الانتصار استقرت السيادة العثمانية جنوب الدانوب استقرارًا لا رجعة فيه.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["فتح القسطنطينية", "583d5e3e"], "d": ["بعد حصار دام أربعة وخمسين يومًا (6 أبريل – 29 مايو 1453) دخل الجيش العثماني المدينة صباح 29 مايو بعد أن تجاوز الأسوار؛ وقُتل الإمبراطور الأخير قسطنطين الحادي عشر في القتال، وطُويت صفحة الإمبراطورية الرومانية الشرقية التي دامت 1100 عام. ونال السلطان الشاب لقب «الفاتح»، وجعل المدينة عاصمة وحوّل آيا صوفيا إلى مسجد؛ وسرعان ما دبّت الحياة في المدينة بالإسكان والعمران. ويُعدّ صبّ المدافع العملاقة ونقل السفن برًّا ونظام الحصار أمام الأسوار ذروة الهندسة العسكرية في العصر. ويُعدّ الفتح في الكتابة التاريخية الأوروبية من التواريخ الرمزية لنهاية العصور الوسطى.", "3664c5fe"]},
"OLAYLAR:1461-08-15:0":{"b": ["فتح طرابزون", "15f52403"], "d": ["استسلمت إمبراطورية طرابزون الرومية في ختام حملة البحر الأسود الشاقة التي قادها الفاتح بالجيش والأسطول في آن واحد؛ وبتصفية آخر بقايا العالم البيزنطي في الأناضول دخل الساحل الجنوبي للبحر الأسود برمّته تحت السيادة العثمانية. وقد عزّز إنهاء أسرة كومنينوس دعوى الفاتح بأنه «سلطان البحرين والبرّين». الأماكن الأخرى التي انضمت في التاريخ نفسه: غيرسون، ريزه.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["الفتح النهائي لسيلفكه — كسر آخر مقاومة للقرمانيين", "d988bee4"], "d": ["كانت قلعة سيلفكه قد استسلمت مرة لقدك أحمد باشا عام 1472، لكن قاسم بك القرماني استعادها في السنة نفسها بمساعدة الأسطول الصليبي في البحر المتوسط. وبعد انتصار أوتلوق بيلي كلّف الفاتح ابنه وقدك أحمد باشا بالاستيلاء على المنطقة نهائيًّا؛ فأُشعلت مخازن البارود بمساعدة المدفعية العثمانية القديمة وسقطت القلعة سريعًا. وهكذا كُسرت آخر مقاومة للقرمانيين في جبال طاشلي وإيچ إيل؛ وسيكتمل القضاء على الإمارة عام 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["معركة أوتلوق بيلي", "42c7194e"], "d": ["هُزم أوزون حسن، حاكم آق قويونلو الذي صار قوة كبرى في الشرق وتحالف مع البندقية، هزيمة ثقيلة في أوتلوق بيلي أمام جيش الفاتح المجهز بالأسلحة النارية. وأكد الانتصار التفوق العثماني في الأناضول؛ وكان كذلك دليلًا مبكرًا على تفوق الجيش المركزي الذي يستخدم المدافع والبنادق على الجيش التقليدي.", "9c59ac50"]},
"OLAYLAR:1475-06-06:0":{"b": ["دخول القرم في الحماية العثمانية", "44e3f7c8"], "d": ["فتح الأسطول بقيادة قدك أحمد باشا مدن الساحل الجنوبي للقرم، وفي مقدمتها كفة التي كانت بيد الجنوية؛ وجُعلت هذه السواحل سناجق عثمانية مباشرة. أما خانية القرم فصارت مع منكلي كراي دولة تابعة ذات امتياز تعترف بالسيادة العثمانية العليا، وظلت ثلاثة قرون حجر الزاوية في السياسة الشمالية؛ وصار البحر الأسود فعليًّا بحيرة عثمانية داخلية. الأماكن الأخرى التي انضمت في التاريخ نفسه: باغجه سراي، كرتش، آزاق.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["وفاة الفاتح — قضية الأمير جم", "190ecf01"], "d": ["تولى بايزيد الثاني العرش إثر وفاة الفاتح المفاجئة في طريق الحملة؛ وأقام أخوه الأمير جم، مدّعيًا السلطنة، الخطبة باسمه وضرب النقود في بورصة. ولما هُزم لجأ أولًا إلى المماليك ثم إلى فرسان رودس؛ وصار جم، في يد الفرسان والبابوية، ورقة مساومة في الدبلوماسية الأوروبية، وتوفي في نابولي عام 1495. وقد أجبرت هذه القضية السياسة الخارجية العثمانية على التزام الحذر خمس عشرة سنة.", "7e488d7b"]},
"OLAYLAR:1514-08:0":{"b": ["انتصار جالديران", "fea64ebb"], "d": ["أراد السلطان ياووز سليم أن يحسم من جذوره الخطر الذي أحدثته الدعاية الصفوية في الأناضول، فهزم جيش الشاه إسماعيل هزيمة ثقيلة في سهل جالديران بتفوق المدافع والبنادق. ودُخلت تبريز؛ وضُمّت الأناضول الشرقية والجنوبية الشرقية وخط الموصل – ديار بكر إلى الإدارة العثمانية. وبفضل جهد إدريس البدليسي ارتبطت الإمارات الكردية بالعثمانيين، فأُرسي إطار الحدود الشرقية الذي سيدوم قرونًا.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["انتصار مرج دابق", "07d254d3"], "d": ["شُتّت الجيش المملوكي في مرج دابق شمال حلب في غضون ساعات قليلة؛ وقُتل السلطان المسن قانصوه الغوري في أثناء المعركة. وبهذا الانتصار الذي فتح أبواب حلب ودمشق على مصراعيها انتقلت سوريا ولبنان وفلسطين إلى الإدارة العثمانية؛ وانفتح الطريق إلى حملة مصر التي ستنهي الدولة المملوكية.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["الريدانية — فتح مصر والخلافة", "caf378d6"], "d": ["اجتاز الجيش العثماني صحراء سيناء بسرعة، وخرق خط دفاع طومان باي في الريدانية، ودخل القاهرة؛ وقُبض على طومان باي الذي واصل المقاومة وأُعدم، وطُويت صفحة الدولة المملوكية. ودخلت مصر والحجاز والمدن المقدسة تحت الإدارة العثمانية؛ ونُقل الخليفة العباسي والأمانات المقدسة إلى إسطنبول. وبانتقال الخلافة إلى الأسرة العثمانية تولى السلاطين دعوى زعامة العالم الإسلامي؛ كما وفّرت السيطرة على طريق التوابل إيرادات كبيرة للإمبراطورية. الأماكن الأخرى التي انضمت في التاريخ نفسه: عكا، معان، صيدا، الكرك.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["اعتلاء سليمان القانوني العرش", "f6512269"], "d": ["تُعدّ سلطنة سليمان الأول، الذي تولى العرش بوفاة ياووز بوصفه الابن الذكر الوحيد، وقد دامت 46 عامًا، ذروة الإمبراطورية سياسيًّا وعسكريًّا وقانونيًّا وثقافيًّا. وقد أكسبته القوانين نامه التي نظّمت القانون العرفي لقب «القانوني»؛ وعُرف في الغرب باسم «العظيم» (Magnificent). وآثار المعمار سنان، والعصر الذهبي للأدب الديواني، وتفوق الأسطول في البحر المتوسط هي رموز هذه الحقبة.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["فتح بلغراد", "59ef5cec"], "d": ["سقطت بلغراد، التي لم يستطع الفاتح أخذها عام 1456 وكانت تُعدّ «مفتاح أوروبا الوسطى»، بحصار عند ملتقى الدانوب والسافا في حملة القانوني الأولى. وانهار خط الدفاع الجنوبي للمجر؛ وبهذا الفتح انفتح باب حملة أوروبا الوسطى التي امتدت إلى موهاج بعد خمس سنوات وإلى ضم بودين بعد عشرين سنة.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["فتح رودس", "807bbb1e"], "d": ["استسلمت رودس، قاعدة فرسان القديس يوحنا الذين كانوا يهددون طرق شرق البحر المتوسط وطريق الحج، بالاتفاق بعد حصار دموي دام أشهرًا؛ وسُمح للفرسان بمغادرة الجزيرة بحرية (واستقروا لاحقًا في مالطة). وتأمّنت سواحل الأناضول، ودخل خط البحر بين إسطنبول ومصر تحت السيطرة العثمانية دون انقطاع.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["معركة موهاج", "f3418b0d"], "d": ["أُبيد الجيش المجري في سهل موهاج في نحو ساعتين بنيران المدافع وتفوق المناورة؛ وقُتل الملك لايوش الثاني في المستنقع وهو يفرّ. وأنهت موهاج، وهي من أسرع المعارك الميدانية الكبرى حسمًا في التاريخ العثماني، المملكة المجرية المستقلة فعليًّا، وفتحت عصر التنافس العثماني الهابسبورغي في أوروبا الوسطى.", "48967894"]},
"OLAYLAR:1529-09:0":{"b": ["حصار فيينا الأول", "dc49ea4f"], "d": ["حاصر الجيش العثماني فيينا في حملة نُظّمت ضد استيلاء الهابسبورغ على العرش المجري؛ ورُفع الحصار بعد ثلاثة أسابيع بسبب ترك المدافع الثقيلة في الطريق وحلول الشتاء مبكرًا وصعوبة التموين. ورغم أن المدينة لم تؤخذ، بقي النفوذ العثماني على المجر؛ وأشارت أسوار فيينا إلى حد الوصول اللوجستي للإمبراطورية في أوروبا الوسطى.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["فتح بغداد — حملة العراقين", "897092c3"], "d": ["في الحملة التي نُظّمت على «العراقين» (العراق العربي والعراق العجمي) دُخلت تبريز أولًا ثم بغداد دون قتال؛ وقد أكسب الاستيلاء على عاصمة العباسيين القديمة السلطان العثماني مكانة كبيرة في العالم الإسلامي. وأُحيي ضريح الإمام الأعظم أبي حنيفة؛ وبانضمام بغداد والبصرة بلغت الأراضي العثمانية الخليج العربي. الأماكن الأخرى التي انضمت في التاريخ نفسه: كركوك، كربلاء.", "f3f80434"]},
"OLAYLAR:1538-09:0":{"b": ["انتصار بريفيزة البحري", "30dc0f97"], "d": ["شُتّت الأسطول الصليبي الذي تشكّل بقيادة البابا، رغم تفوقه العددي، أمام بريفيزة بفضل تكتيك بربروس الذي أحسن استخدام الريح والساحل؛ وترك أندريا دوريا ساحة المعركة. وأرسى الانتصار تفوقًا بحريًّا عثمانيًّا لا منازع فيه في البحر المتوسط دام نحو 33 عامًا؛ وهو التاريخ الرمزي ليوم البحرية في التقليد البحري التركي. الأماكن الأخرى التي انضمت في التاريخ نفسه: عدن، بندر.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["ضم بودين — المجر ولاية عثمانية", "db53b244"], "d": ["خرج القانوني في حملة إثر حصار الهابسبورغ لبودين، وبعد أن أنقذ المدينة ضمّ وسط المجر إلى الإدارة العثمانية المباشرة وأنشأ بكلربكية بودين، بينما جُعلت ترانسلفانيا إمارة ذاتية الحكم تابعة للعثمانيين. واستمر هذا الترتيب الذي قُسمت به المجر إلى ثلاثة أقسام نحو 150 عامًا، وشكّل الهيكل الإداري الدائم للعثمانيين في أوروبا الوسطى.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["معاهدة أماسية", "a5afe0d1"], "d": ["هي أول معاهدة سلام رسمية أنهت الحروب العثمانية الصفوية التي دامت سنوات طويلة. فبقيت بغداد والعراق عند العثمانيين، وتم الاعتراف المتبادل لأول مرة بحدود الأناضول الشرقية؛ والتزم الصفويون بوقف الدعاية الشيعية في الأراضي العثمانية، والتزم العثمانيون بأمن مرور الحجاج الإيرانيين. وصارت المعاهدة أول مثال على الإطار القانوني للعلاقات بين الدولتين.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["سيكتوار — وفاة القانوني", "e2917ed2"], "d": ["توفي القانوني، وكان في الثانية والسبعين من عمره، في خيمته قبل سقوط قلعة سيكتوار التي حاصرها في حملته الثالثة عشرة بساعات قليلة؛ وأخفى صوقوللو محمد باشا الوفاة أسابيع كي لا ينفرط عقد الجيش. وأُخذت القلعة، لكن الدولة فقدت أطول سلاطينها حكمًا وأعظمهم مجدًا؛ وتولى العرش ابنه سليم الثاني، وبدأ ثقل كبار الوزراء في إدارة الدولة يزداد.", "62c468a1"]},
"OLAYLAR:1571-08:0":{"b": ["فتح قبرص", "e364a2b3"], "d": ["أُنزلت القوات عام 1570 في قبرص الخاضعة للبندقية؛ وسقطت نيقوسيا سريعًا، أما ماغوزا فلم تستسلم إلا في أغسطس 1571 بعد حصار دام أحد عشر شهرًا. ونُظّمت الجزيرة، وهي حيوية لأمن طرق التجارة والحج في شرق البحر المتوسط، بكلربكية، وأُسكن فيها سكان من الأناضول؛ وكان الفتح كذلك سببًا للتحالف الصليبي الكبير الذي بلغ إينه بختي.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["هزيمة إينه بختي (ليبانتو)", "6a1d44a9"], "d": ["أدرك الأسطول الصليبي، الذي اتحد إثر فتح قبرص، الأسطول العثماني في خليج إينه بختي فأباد معظمه؛ واستشهد قبودان باشا مؤذن زاده علي باشا، ولم ينجُ إلا أسطول أولوج علي. وبعد الكارثة عيّن الصدر الأعظم صوقوللو محمد باشا أولوج علي باشا قبودان باشا وكلّفه بجمع الأسطول المبعثر، وبدأ بناء أسطول جديد في جميع الترسانات من إسطنبول إلى آلانيا؛ غير أن التفوق المطلق في البحر المتوسط اهتزّ نفسيًّا.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["معركة كرستس (هاچوفا)", "da308ec5"], "d": ["في أكبر معركة ميدانية في الحرب الطويلة (1593–1606)، استعاد الجيش الذي كان محمد الثالث بنفسه على رأسه تماسكه بتوجيه من خوجة سعد الدين أفندي في اللحظة التي أوشك فيها على التفكك، فهزم الجيش الهابسبورغي. وتُعدّ آخر معركة ميدانية كلاسيكية كبرى انتصر فيها العثمانيون؛ غير أن عدم تغييرها مجرى الحرب عُدّ علامة على التآكل في النظام العسكري.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["معاهدة زيتفاتوروك", "39c01142"], "d": ["بموجب المعاهدة التي أنهت الحرب المنهكة التي دامت ثلاث عشرة سنة، عُدّ حاكم الهابسبورغ لأول مرة بصفة «الإمبراطور الروماني» نظيرًا للسلطان، وأُلغيت الجزية السنوية. وكان فقدان الأراضي ضئيلًا جدًّا؛ لكن هذا التغير في اللغة الدبلوماسية يُقرأ رمزًا لانتهاء دعوى العثمانيين التفوق المطلق على أوروبا.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["معاهدة قصر شيرين", "c1acf3af"], "d": ["أنهت المعاهدة، التي وُقّعت بعد استعادة مراد الرابع بغداد (1638)، الحروب العثمانية الصفوية التي دامت أكثر من مئة عام. فبقيت بغداد والعراق نهائيًّا عند العثمانيين، وتُركت يريفان للصفويين؛ وصار الخط المرسوم، مع تعديلات طفيفة، أساس الحدود التركية الإيرانية الحالية، وهو يُعدّ من أطول حدود العالم عمرًا. وتركت المعاهدة بدره وجصان ومندلي ودرتنك ودرنه للعثمانيين؛ وكان من المقرر هدم قلعة زنجير الحدودية، وأن تبقى القرى الواقعة غربها للعثمانيين والواقعة شرقها لإيران. وبقي محيط قلعة زالم قرب شهرزور وقلعة قزل جه قلعة عند العثمانيين، وبقيت أورامان ومهربان عند إيران؛ وكان من المقرر أن يُهدم الطرفان قلاع قطور وماكو ومغازبرد.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["اكتمال فتح كريت", "e0d85604"], "d": ["انتهى حصار كانديا، المشهد الأخير من حرب كريت التي بدأت عام 1645، بحملة فاضل أحمد باشا الحازمة التي دامت ثلاث سنوات؛ وسلّم القائد البندقي موروزيني المدينة بمعاهدة. وسُجّل الصراع الذي دام نحو ربع قرن بوصفه أطول حصار في التاريخ العثماني؛ ودخلت آخر قلاع اللاتين الكبرى في شرق البحر المتوسط تحت الإدارة العثمانية. وبقيت ثلاث قلاع صخرية صغيرة على الساحل الشمالي للجزيرة — سودا وسبينالونغا وغرامبوسا — بيد البندقية؛ ولأنها مقامة على جزر صغيرة منفصلة لا يمكن إظهارها على الخريطة منفصلة عن بقية كريت.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["معاهدة بوجاش — أوسع الحدود", "b17b6e5a"], "d": ["ضُمّت بودوليا إلى العثمانيين بمعاهدة بوجاش التي وُقّعت بعد فتح كامانيتسا في حملة بولندا، ووُضع جزء من أوكرانيا تحت الحماية. وبلغت الإمبراطورية بذلك أوسع حدودها في أوروبا؛ وتُعدّ هذه النقطة ذروة عصر التوسع وحلقته الأخيرة في آن واحد.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["هزيمة حصار فيينا الثاني", "7d889252"], "d": ["آل حصار فيينا الذي قام به مرزيفونلو قره مصطفى باشا ودام شهرين إلى هزيمة بضربة مفاجئة أنزلها ملك بولندا يان سوبيسكي من تلال كالنبرغ؛ وانسحب الجيش تاركًا أثقاله، وأُعدم مرزيفونلو في بلغراد. ودامت الحرب ست عشرة سنة مع الحلف المقدس الذي تشكّل إثر الانتصار؛ وتُذكر هذه الهزيمة بوصفها لحظة بداية التراجع الكبير في التاريخ العثماني.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["فتح قلعة غرامبوسا — إحدى القلاع الصخرية التي بقيت بيد البندقية في كريت", "3ddf9eeb"], "d": ["رغم أن فتح كريت عُدّ مكتملًا إلى حد كبير بتسليم كانديا عام 1669، ظلت غرامبوسا، القلعة الصخرية الجزيرية في الطرف الشمالي الغربي للجزيرة، بيد البندقية ثلاثًا وعشرين سنة أخرى. وبالاستيلاء عليها عام 1692 طُهّرت إحدى البقايا البندقية الثلاث في كريت؛ أما سودا وسبينالونغا فكان عليهما انتظار حملة المورة عام 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["معاهدة كارلوفيتس — أول خسارة كبرى للأراضي", "8f7e2546"], "d": ["بموجب كارلوفيتس التي أنهت حروب الحلف المقدس التي دامت ست عشرة سنة، تُركت المجر وترانسلفانيا للنمسا، وبودوليا لبولندا، والمورة وسواحل دالماسيا للبندقية. وللمرة الأولى في التاريخ العثماني كانت أراضٍ بهذا الحجم تخرج من اليد على طاولة المفاوضات وبصورة دائمة؛ وتُعدّ المعاهدة وثيقة بداية عصر جديد انتقلت فيه الإمبراطورية إلى موقف الدفاع أمام أوروبا، كما أنها نقطة تحول في تاريخ الدبلوماسية العثمانية.", "54bb2eee"]},
"OLAYLAR:1711-07-19:0":{"b": ["انتصار بروت", "2583572f"], "d": ["في الحرب التي نشبت بسبب مسألة ملك السويد الذي لجأ إلى العثمانيين بعد هزيمة بولتافا، حوصر جيش القيصر بطرس الأول على ضفاف بروت واضطر إلى الاستسلام. وبالمعاهدة الموقعة استُعيدت آزاق؛ أما عدم إبادة الجيش وإطلاق سراح القيصر فقد دخل التاريخ قرارًا لا يزال موضع جدل منذ ذلك اليوم.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["فتح قلعتي سودا وسبينالونغا — محو آخر أثر بندقي في كريت", "7261f7ba"], "d": ["بعد ثلاث وعشرين سنة من سقوط غرامبوسا عام 1692، فُتحت قلعتا سودا وسبينالونغا، آخر معقلين للبندقية في كريت، بفرع جانبي من حملة المورة. وهكذا اكتمل فتح كريت الذي بدأ عام 1645، بعد ست وأربعين سنة، حتى آخر شبر من الجزيرة.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["ثورة باترونا خليل", "100941a4"], "d": ["تحوّل الغضب من الفشل على الجبهة الإيرانية والضرائب وترف محيط القصر إلى انتفاضة كبرى بقيادة باترونا خليل، حلّاق الحمّام. فقُتل الصدر الأعظم إبراهيم باشا، وخُلع أحمد الثالث عن العرش، وانتهى عصر اللالة؛ وأظهر تحكم الثوار في المدينة أشهرًا هشاشة السلطة المركزية بصورة لافتة.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["معاهدة بلغراد — استرداد بلغراد وسمندرة وشمال صربيا", "ba7f8e46"], "d": ["في ختام الحرب (1736–1739) التي خيضت على جبهتين ضد النمسا وروسيا، استُردت بلغراد وشمال صربيا؛ وقبلت روسيا نزع سلاح آزاق وعدم الاحتفاظ بأسطول في البحر الأسود. وقد منحت المعاهدة، التي تُعدّ آخر نجاح كبير للدبلوماسية العثمانية وجيشها في القرن الثامن عشر، الإمبراطورية فترة سلم دامت ربع قرن.", "5b399dd2"]},
"OLAYLAR:1770-07-06:0":{"b": ["غارة تشسمه", "840b30bd"], "d": ["أحرق الأسطول الروسي، الذي خرج إلى البحر المتوسط بدعم من الإنجليز، الأسطول العثماني المحتمي بميناء تشسمه بالسفن الحارقة حتى كاد يفنيه تمامًا. وظهرت روسيا لأول مرة قوة بحرية كبرى في البحر المتوسط؛ وكانت الكارثة إحدى الضربات التي حسمت مصير الحرب المؤدية إلى كوتشوك قاينارجه عام 1774، وكشفت الحاجة إلى إصلاح جذري للأسطول.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["معاهدة كوتشوك قاينارجه", "2776dcdb"], "d": ["بمعاهدة كوتشوك قاينارجه، التي أنهت حرب 1768–1774 وتُعدّ من أثقل المعاهدات في التاريخ العثماني، مُنحت خانية القرم «الاستقلال» — وأُنشئت عمليًّا منطقة نفوذ روسية. واستقرت روسيا على ساحل البحر الأسود، وكسبت لسفنها التجارية حق المرور في المضائق وسفارة دائمة في إسطنبول؛ وفتح بند الحماية الغامض على الرعايا الأرثوذكس باب مبررات التدخل في القرن التالي. وللمرة الأولى كانت أرض سكانها مسلمون تخرج من السيادة العثمانية.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["ضم القرم إلى روسيا", "bdf6faa8"], "d": ["ضُمّت القرم «المستقلة» التي أوجدتها كوتشوك قاينارجه إلى روسيا بمنشور يكاترينا الثانية، بذريعة الاضطرابات في عهد آخر الخانات شاهين كراي. وانتهت الشراكة العثمانية القرمية التي دامت ثلاثة قرون؛ وأزال فقدان السهوب الشمالية عمق الدفاع عن إسطنبول، وبدأ أول موجة كبرى من هجرة عشرات الآلاف من تتار القرم إلى الأراضي العثمانية.", "8d4fcb03"]},
"OLAYLAR:1789-04:0":{"b": ["سليم الثالث والنظام الجديد", "d53aec21"], "d": ["أدرك سليم الثالث، الذي اعتلى العرش في أثناء الحرب، أن الهزائم بنيوية، فأطلق برنامج إصلاح شاملًا باسم «النظام الجديد» (نظام جديد): جيش جديد مدرَّب على الطريقة الأوروبية، وخزينة مستقلة تموّله (إيراد جديد)، وتقوية مهندسخانات، وأولى السفارات الدائمة في العواصم الأوروبية. ويُعدّ البرنامج بداية تقليد الإصلاح التركي الحديث؛ غير أنه سينهار عام 1807 بمقاومة الأوجاقات والأعيان.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["تصفية فرسان مالطة — محطة الأسطول الفرنسي في الطريق", "d62f901d"], "d": ["مرّ الأسطول الفرنسي المتجه إلى مصر بمالطة في طريقه؛ فسلّم فرسان القديس يوحنا (مالطة) الجزيرة دون مقاومة تُذكر. وبذلك انتهى آخر معاقل فرسان الطريقة التي طُردت من رودس عام 1522 واستقرت هنا. وستنتقل مالطة بعد سنتين إلى يد إنجلترا، أما نابليون فتوجّه من الجزيرة مباشرة إلى الإسكندرية.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["احتلال نابليون لمصر", "93fede5f"], "d": ["نزل جيش الجنرال بونابرت في الإسكندرية واحتل مصر؛ وكانت هذه الحملة، التي استهدفت طريق إنجلترا إلى الهند، أول هجوم مباشر لقوة أوروبية على أراضي العثمانيين المركزية. وقد كسرت غارة نلسون في أبي قير ودفاع جزار أحمد باشا عن عكا المسيرة الفرنسية؛ وانتهى الاحتلال عام 1801، لكن في الفراغ الذي خلّفه بدأ صعود محمد علي باشا الكافالي وعصر «المسألة الشرقية».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["سند الاتفاق", "cce49ef5"], "d": ["وثيقة وُقّعت بين القصر وأسر الأعيان الأقوياء في الولايات بقيادة أعيان روسجق علمدار مصطفى باشا الذي أجلس محمودًا الثاني على العرش؛ وفيها تعهّد الأعيان بالولاء للسلطان وتقديم الدعم العسكري، واعترفت الدولة في المقابل بوجودهم وحقوقهم. ولأنها أول مثال في التاريخ العثماني على تقييد سلطة السلطان بوثيقة، يعدّها بعض المؤرخين بداية بعيدة للتقليد الدستوري؛ وقد أصبحت عمليًّا بلا أثر في غضون بضعة أشهر.", "2d97fdfe"]},
"OLAYLAR:1821-03-25:0":{"b": ["اندلاع الثورة اليونانية", "a7293715"], "d": ["اندلعت الانتفاضة التي أعدّتها منظمة الفيليكي إتيريا أولًا في الأفلاق، ثم في المورة بثقلها الرئيس؛ وتأخرت الدولة المنشغلة بمسألة تبدلن علي باشا في التدخل الأول. وتحولت الثورة سريعًا إلى قضية دولية بفضل التعاطف اليوناني الشديد في الرأي العام الأوروبي (الفيلهلينية)؛ وهكذا أُشعلت فتيلة أول حركة استقلال ناجحة في الأراضي العثمانية في عصر القومية. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: أثينا، بالياباترا (باتراس)، إستيفة (طيبة)، ليفاديا.", "316e2ac7"]},
"OLAYLAR:1826-06-15:0":{"b": ["الواقعة الخيرية — إلغاء الجيش الإنكشاري", "08c9372a"], "d": ["أُبيد الإنكشاريون الذين ثاروا (قلبوا القدور) على تدريبات جيش «الأشكنجية» الذي أُنشئ حديثًا في ثكناتهم في أت ميداني بنيران مدافع القوات الموالية التي أعدّها محمود الثاني مسبقًا؛ وأُلغي الأوجاق بجميع فروعه مع التكايا البكتاشية التابعة له. وبتصفية هذه المؤسسة التي دامت أربعة قرون، فتحت هذه العملية، التي دخلت التاريخ باسمها الذي يعني «الحدث الميمون»، الطريق أمام جيش «العساكر المنصورة المحمدية» وأمام جميع إصلاحات المركزية اللاحقة.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["غارة نافارين", "ee579e7f"], "d": ["أُحرق الأسطول العثماني المصري، الذي كان يقمع الثورة اليونانية، في نافارين على يد الأسطول المشترك البريطاني الفرنسي الروسي الذي دخل الميناء دون إعلان حرب؛ وفُقد نحو ستين سفينة وآلاف البحارة. وضمنت الغارة، التي طُويت في الدبلوماسية الأوروبية بوصفها «حادثًا مؤسفًا»، الاستقلال اليوناني عمليًّا، وفتحت الطريق إلى الحرب العثمانية الروسية 1828–1829.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["فرمان التنظيمات", "5042ce7b"], "d": ["بالخط الهمايوني الذي قُرئ في كولخانه وُضعت أرواح جميع الرعايا وأموالهم وأعراضهم، دون تمييز في الدين، تحت ضمان الدولة؛ وأُعلنت مبادئ العدالة في الضريبة والنظام في الخدمة العسكرية وعدم إنزال العقوبة دون محاكمة. ويُعدّ الفرمان، الذي هو من عمل مصطفى رشيد باشا، أول وثيقة كبرى ذات طابع دستوري في التحديث العثماني، وقد أعطى «عهد التنظيمات» (1839–1876) اسمه لعصر الإصلاح؛ وجرت في هذا الإطار إعادة هيكلة جذرية في الإدارة والقانون والتعليم والمالية.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["اندلاع حرب القرم", "3b9ca3c8"], "d": ["تحولت الأزمة التي بدأت بمسألة الأماكن المقدسة ودعوى روسيا حماية الرعايا الأرثوذكس إلى صراع مفتوح بإعلان العثمانيين الحرب؛ وبعد غارة سينوب دخلت إنجلترا وفرنسا (ثم بيدمونت) الحرب إلى جانب العثمانيين. وانتهت الحرب بمعاهدة باريس عام 1856 بعد أن نزلت جيوش الحلفاء في القرم واستولت على سيفاستوبول؛ غير أن الدين الخارجي الأول (1854) الذي أُخذ في سنوات الحرب أدخل الإمبراطورية في دوامة تبعية مالية دامت نصف قرن.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["فرمان الإصلاح", "78ff234d"], "d": ["وسّع الفرمان الذي أُعلن قبل مفاوضات السلام في باريس مبادئ التنظيمات، ومنح الرعايا غير المسلمين حقوق مساواة واسعة تشمل الوظائف الحكومية والخدمة العسكرية وفتح المدارس؛ وأُعيد تنظيم هياكل الطوائف. وبمعاهدة باريس التي وُقّعت بعده قُبلت الدولة العثمانية رسميًّا في أسرة القانون الدولي الأوروبي ووُضعت سلامة أراضيها تحت الضمان المشترك للدول الكبرى — وكان هذا الضمان في التطبيق بابًا جديدًا للتدخلات.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["القانون الأساسي — المشروطية الأولى", "0fe052c1"], "d": ["في يوم افتتاح المؤتمر الدولي الذي اجتمع في إسطنبول لبحث الأزمة البلقانية، أُعلن أول دستور عثماني بطلقات المدافع؛ وأُنشئ برلمان من مجلسين بالقانون الأساسي الذي هو من عمل حركة «العثمانيين الجدد» بقيادة مدحت باشا. وافتُتح مجلس المبعوثان في مارس 1877؛ لكن عبد الحميد الثاني، متذرعًا بحرب 93، علّق المجلس إلى أجل غير مسمى في فبراير 1878، وظل الدستور معلقًا ثلاثين سنة.", "c0f01a41"]},
"OLAYLAR:1877-04:0":{"b": ["حرب 93 (الحرب العثمانية الروسية 1877–1878)", "5bd96af7"], "d": ["في الحرب التي سُميت «حرب 93» لأنها وافقت سنة 1293 الرومية، هاجمت الجيوش الروسية من جبهتين؛ ورغم أن دفاع غازي عثمان باشا عن بليفن ومعارك أحمد مختار باشا في القفقاس صارت ملحمة، انهارت الجبهة وتقدم الروس حتى يشيلكوي (آياستفانوس). وأطلقت الحرب موجات هجرة إسلامية كبرى من البلقان والقفقاس نحو إسطنبول، ما زالت آثارها ممتدة حتى اليوم؛ ولم تعد البنية الديموغرافية والمالية للإمبراطورية إلى حالها السابقة.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["معاهدة برلين", "47f76a49"], "d": ["عدّل مؤتمر برلين «بلغاريا الكبرى» التي أوجدتها آياستفانوس باسم توازن القوى الكبرى، لكنه ترك مع ذلك صورة ثقيلة: فاستقلت صربيا والجبل الأسود ورومانيا؛ وأُنشئت إمارة بلغاريا ذاتية الحكم؛ وتُركت البوسنة والهرسك للاحتلال النمساوي، وقبرص للإدارة البريطانية، وقارص وأردهان وباطوم لروسيا. وتفكك إلى حد كبير النظام العثماني الذي دام خمسمائة عام في الروملي؛ وصارت «المسألة الشرقية» بندًا دائمًا على جدول أعمال الدبلوماسية الأوروبية. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: فيليبه، فيدين، ترنوفو، وارنا، شومنو، سيليستر، روسجق، بوخارست، ياش، كوستنجة.", "076697b6"]},
"OLAYLAR:1881-05-12:0":{"b": ["احتلال تونس والديون العمومية", "c7e25598"], "d": ["احتلت فرنسا تونس متذرعة بحوادث على الحدود الجزائرية، ووضعتها تحت حمايتها بمعاهدة باردو؛ وانحسر الوجود العثماني في شمال أفريقيا إلى طرابلس الغرب. وبمرسوم محرم الذي صدر في السنة نفسها أُنشئت إدارة الديون العمومية التي مُثّل فيها الدائنون لإدارة الديون الخارجية التي أفلست: فرُبطت الإيرادات الأساسية كالملح والتبغ والحرير مباشرة بهذه الإدارة الأجنبية، وقُيّدت السيادة المالية تقييدًا شديدًا. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: القيروان، قابس، صفاقس، جربة (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09:0":{"b": ["الاحتلال البريطاني لمصر", "f1269768"], "d": ["سُحقت حركة عرابي باشا التي نهضت ضد الإفلاس المالي والرقابة الأجنبية في مصر بانتصار الجيش البريطاني في التل الكبير، الذي نزل إلى البر بعد قصف الإسكندرية، واحتُلت القاهرة. ورغم أن مصر ظلت قانونيًّا تابعة للعثمانيين، دخلت عمليًّا تحت الإدارة البريطانية؛ وصارت السيطرة على قناة السويس في صلب استراتيجية الإمبراطورية البريطانية.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["إعلان المشروطية الثانية", "95ee2fd2"], "d": ["أعاد عبد الحميد الثاني العمل بالقانون الأساسي أمام الحركة التي كبرت بصعود ضباط جمعية الاتحاد والترقي إلى الجبال في مقدونيا؛ واستُقبل «إعلان الحرية» بحماسة وجرت الانتخابات. غير أن الاستقرار لم يأت: فبعد قمع واقعة 31 مارس (أبريل 1909) خُلع عبد الحميد عن العرش؛ كما جرى في هذه الأشهر المضطربة إعلان استقلال بلغاريا وضم البوسنة وتوجه كريت نحو اليونان.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["حرب طرابلس الغرب", "ed441994"], "d": ["أعلنت إيطاليا، الباحثة عن المستعمرات، الحرب على طرابلس الغرب، آخر أراضي العثمانيين في شمال أفريقيا، واحتلت السواحل؛ ولما لم تستطع الدولة التي لا أسطول لها إرسال جيش نظامي، تسلل ضباط شباب مثل مصطفى كمال وأنور بك سرًّا إلى المنطقة ونظموا مقاومة فعالة مع القبائل السنوسية. وبمعاهدة أوشي (18 أكتوبر 1912) التي وُقّعت إثر اندلاع حرب البلقان تُركت ليبيا لإيطاليا؛ كما احتلت إيطاليا رودس والجزر الاثنتي عشرة.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["معاهدة لندن — فقدان الروملي", "f3f976df"], "d": ["بمعاهدة لندن التي أنهت حرب البلقان الأولى، فُقدت جميع الأراضي غرب خط ميديا – إينوس وجزر بحر إيجه؛ واستقلت ألبانيا. ولم يبقَ من الروملي، التي كانت مركز الثقل الديموغرافي والاقتصادي والثقافي للإمبراطورية منذ أكثر من خمسمائة عام، إلا تراقيا الشرقية (استُردت أدرنة في حرب البلقان الثانية)؛ وقد شدّد هذا الفقدان سياسة الحرب والإسكان لدى الإدارة الاتحادية تشديدًا جذريًّا.", "077da59d"]},
"OLAYLAR:1914-11-01:0":{"b": ["الدخول في الحرب العالمية الأولى", "05a0252e"], "d": ["جرّ السماح للطرادين غويبن وبريسلاو الهاربين من إنجلترا بدخول المضيق، مع إظهارهما كأنهما اشتُريا، الدولةَ خطوة خطوة إلى جانب ألمانيا؛ وبدأت الحرب فعليًّا بقصف الأسطول بقيادة الأميرال سوشون الموانئ الروسية (29 أكتوبر)، وجاءت الإعلانات المتبادلة في مطلع نوفمبر. ورغم إعلان الجهاد الأكبر لم يظهر الأثر المنتظر؛ ودخلت الإمبراطورية، على مدى أربع سنوات، حرب بقاء على خمس جبهات منفصلة من القفقاس إلى فلسطين.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["انتصار جناق قلعة", "95d888e8"], "d": ["ردّ نيران حقول الألغام والطوابي الأسطول الحليف الذي استهدف إسقاط إسطنبول والوصول إلى روسيا عن المضيق في 18 مارس؛ وحسم الخط الذي نصبته كاسحة الألغام نصرت مصير المعركة. وأُوقفت كذلك عملية غاليبولي البرية التي بدأت في أبريل عند أنافارتا وتبة كوجه تشيمن؛ وأخلى الحلفاء شبه الجزيرة تمامًا في يناير 1916. وسُمع اسم المقدم مصطفى كمال على هذه الجبهة؛ ويُعدّ هذا الانتصار، الذي تحقق بنحو ربع مليون شهيد ومفقود، مكان ولادة كوادر حرب الاستقلال وروحها.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["ثورة الشريف حسين", "75f7c58c"], "d": ["ثار أمير مكة الشريف حسين، بعد مراسلات سرية مع الإنجليز، على وعد بمملكة عربية مستقلة؛ واستُهدفت سكة حديد الحجاز بالغارات. ورغم أن دفاع فخري باشا الأسطوري عن المدينة المنورة، الذي استمر إلى ما بعد الهدنة، بقي رمزًا للمقاومة، فإن الثورة، باجتماعها مع التقدم البريطاني على الجبهة الفلسطينية، عجّلت تفكك السيادة العثمانية في الولايات العربية. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: الطائف.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["هدنة مودروس", "9e87c767"], "d": ["انسحبت الدولة العثمانية، التي انقطعت جبهاتها بعضها عن بعض بانهيار بلغاريا، من الحرب بالهدنة الموقعة على متن المدرعة أغاممنون. وسرعان ما صارت المادة السابعة، التي تتيح فتح المضائق واحتلال الأماكن التي يُهدَّد أمنها خاصة، غطاءً قانونيًّا للتقاسم الفعلي: فاحتُلت الموصل والإسكندرون، ثم إزمير وإسطنبول. وتُعدّ الهدنة وثيقة النهاية الفعلية للإمبراطورية. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: حماة، دمشق، حمص.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["مصطفى كمال في سامسون — حرب الاستقلال", "09a8f784"], "d": ["في أجواء السخط التي خلّفها احتلال إزمير، حوّل مصطفى كمال باشا، الذي نزل في سامسون بصفته مفتش الجيش التاسع، مهمته الرسمية إلى تنظيم المقاومة في الأناضول. وتأتي تعميم أماسية ومؤتمرا أرضروم وسيواس امتدادًا لهذا الانطلاق؛ وصار مبدأ «استقلال الأمة يخلّصه عزم الأمة وقرارها» نواة البرنامج السياسي لحرب الاستقلال.", "330e4c51"]},
"OLAYLAR:1920-04:0":{"b": ["افتتاح المجلس الوطني الكبير ومعاهدة سيفر", "2008feec"], "d": ["افتُتح المجلس الوطني الكبير في أنقرة في 23 أبريل 1920 إثر الاحتلال الرسمي لإسطنبول وحلّ مجلس المبعوثان؛ وصار المجلس، الذي جمع في يده صلاحيات استثنائية، نواة الدولة الجديدة القائمة على الإرادة الوطنية. وكانت معاهدة سيفر، التي وقّعتها حكومة إسطنبول في أغسطس، تقسّم الأناضول؛ فأعلن المجلس الوطني الكبير الموقّعين عليها خونة للوطن، ولم تُطبَّق سيفر قط.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["معركة سقاريا", "f2f970a6"], "d": ["انكسر الهجوم اليوناني، الذي اقترب من أنقرة إلى مسافة 50 كيلومترًا، في معركة دامت 22 يومًا و22 ليلة بأمر «لا يوجد خط دفاع بل توجد مساحة دفاع» الذي أصدره مصطفى كمال باشا بعد توليه القيادة العامة. وانتقل الجيش اليوناني لأول مرة إلى الدفاع الاستراتيجي؛ وجلب الانتصار لمصطفى كمال لقب الغازي ورتبة المشير، وفتح الباب أمام اتفاقية أنقرة مع فرنسا والاعتراف الخارجي.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["الهجوم الكبير وتحرير إزمير", "172a50c4"], "d": ["بلغ الهجوم الذي بدأ صباح 26 أغسطس من كوجه تبه إبادةَ القوات اليونانية الرئيسة في معركة القائد العام في طوملو بينار في 30 أغسطس؛ وبالمطاردة التي استمرت بأمر «أيها الجيوش، هدفكم الأول البحر المتوسط، إلى الأمام!» حُررت إزمير في 9 سبتمبر. واستُردت تراقيا الشرقية دون قتال بهدنة مودانيا (11 أكتوبر)؛ وحدد النصر العسكري قوة الدولة الجديدة التي ستقوم في لوزان على الطاولة.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["إلغاء السلطنة", "9f36a9f6"], "d": ["ألغى المجلس الوطني الكبير السلطنة في 1 نوفمبر 1922 بفصلها عن الخلافة إثر دعوة حكومة إسطنبول أيضًا إلى مفاوضات لوزان؛ وانتهى قانونيًّا حكم الأسرة العثمانية الذي دام 623 عامًا. وغادر محمد السادس وحيد الدين البلاد على متن مدرعة إنجليزية في 17 نوفمبر؛ وجيء بعبد المجيد أفندي إلى منصب الخلافة بقرار المجلس الوطني الكبير، وسيُلغى هذا المنصب أيضًا في 3 مارس 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["معاهدة لوزان", "38c27f7d"], "d": ["بمعاهدة لوزان للسلام التي وُقّعت في ختام مفاوضات شاقة دامت ثمانية أشهر، اعتُرف دوليًّا بحدود الدولة التركية الجديدة واستقلالها التام وسيادتها؛ وأُلغيت الامتيازات الأجنبية، وبدأت عملية تصفية الديون العمومية، ونُظّم تبادل السكان. وتُعدّ لوزان، التي أبطلت سيفر عمليًّا، الانتصار الدبلوماسي لحرب الاستقلال والوثيقة الخارجية المؤسسة للجمهورية.", "6d498c3f"]},
"OLAYLAR:1923-10:0":{"b": ["إعلان الجمهورية", "d5bfcdfb"], "d": ["أُعلنت الجمهورية بقبول المجلس الوطني الكبير، بتعديل دستوري، الحكم القائل «شكل حكومة الدولة التركية هو الجمهورية»؛ وانتُخب مصطفى كمال باشا أول رئيس للجمهورية. وهكذا انطوت المغامرة العثمانية التي بدأت عام 1299 إمارةً ثغرية وامتدت 624 عامًا، وأُقيمت الدولة الجديدة، التي تعود فيها السيادة دون قيد أو شرط للأمة، على إرث الإمبراطورية.", "f5cabb8c"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["دخول قراجه ريفه (ڤيريا) في السيادة العثمانية", "b0ece3f3"], "d": ["بتسليم سلانيك عام 1387 دخلت في السنة نفسها قراجه ريفه الواقعة في داخل مقدونيا السفلى في السيادة العثمانية. وكانت المدينة عقدة الطريق بين سلانيك وتساليا.", "4e571f7b"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["فتح قلعتي لوغوج (لوغوي) وكارانشبش — استمرار حملة تيميشوارا", "1af5a2be"], "d": ["استسلمت قلعة تيميشوارا بعد ثلاثة أسابيع من المقاومة في 26 تموز/يوليو 1552. وفي آب/أغسطس أُخذت قلعتا لوغوج وكارانشبش أيضًا؛ وأُخذت خمس عشرة قلعة على امتداد وادي موريش، وأُنشئت بكلربكية جديدة مركزها تيميشوارا.", "ecd1e532"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["وقوع بريشتينا في يد الجيش الصربي", "2ef111c0"], "d": ["أخذ الجيش الصربي الذي دخل كوسوفو في حرب البلقان الأولى بريشتينا، وبدأت في المدينة سياسة التصريب من جديد. ويُعدّ سقوط بريشتينا من أولى حلقات تفكك المقاومة العثمانية في ولاية كوسوفو.", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["احتلال القوات الصربية لمنستير", "db9b3353"], "d": ["وقعت منستير، أحد أهم المراكز الإدارية والعسكرية في مقدونيا، في حرب البلقان الأولى في يد القوات الصربية بعد اشتباكات دامت خمسة أيام. وكان فقدان المدينة يعني الانتهاء الفعلي للوجود العثماني في مقدونيا.", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["إعلان استقلال ألبانيا — إسماعيل قمالي في أفلونية", "2cdbd4d9"], "d": ["بينما دخلت جيوش حرب البلقان الولايات الألبانية أعلن إسماعيل قمالي في أفلونية استقلال ألبانيا. وبذلك خرج من الإدارة العثمانية الساحل والداخل الممتدان من دراج وإلباسان وبيرات وأرغيري وآق حصار إلى آيا ساراندا، وشكّلا نواة الدولة الألبانية الجديدة.", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["انتهاء السيادة العثمانية في أوهريد وديبرا", "5273f1ec"], "d": ["بعد أحد عشر يومًا من سقوط منستير دخل الجيش الصربي منطقة البحيرات في غرب مقدونيا؛ وانتهت في أوهريد سيادة عثمانية دامت خمسة قرون، وخرجت ديبرا الشمالية أيضًا في الحركة نفسها.", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["احتلال الجبل الأسود لإشقودرة", "db704247"], "d": ["شهدت إشقودرة أحد أطول الحصارات في حرب البلقان الأولى؛ وبعد مقاومة دامت أشهرًا سُلّمت المدينة لقوات الجبل الأسود. وكانت إشقودرة من آخر القلاع العثمانية التي صمدت حتى نهاية الحرب.", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["الجبل الأسود يخلي إشقودرة؛ الفيلق الدولي للدول الكبرى يدخل المدينة", "8a6593e9"], "d": ["أخلى الجبل الأسود، بضغط من الدول الكبرى، إشقودرة التي أخذها في 23 نيسان/أبريل 1913 في 14 أيار/مايو 1913؛ ودخل المدينة الفيلق الدولي وصارت جزءًا من الإدارة المؤسسة لألبانيا.", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["ابن سعود يأخذ الأحساء — نهاية السيادة العثمانية على ساحل الخليج", "505f26d5"], "d": ["أخرج أمير نجد عبد العزيز بن سعود الحامية العثمانية واستولى على منطقة الأحساء وأقام مركزه في الهفوف. وانتقل ساحل الخليج الغربي مع ميناءي القطيف والعقير إلى الإدارة السعودية؛ وانتهت إدارة الدولة العثمانية في المنطقة التي دامت خمسين سنة.", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["معاهدة بوخارست — تراقيا الغربية وحوض قوالة تنتقل من بلغاريا إلى اليونان", "56123a58"], "d": ["انتهت حرب البلقان الثانية بمعاهدة بوخارست الموقّعة بين بلغاريا وصربيا واليونان والجبل الأسود. وتُرك لليونان بهذه المعاهدة حوض قوالة ودراما وسيرس الذي آل إلى بلغاريا في الحرب الأولى.", "ca3eb029"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["إنزال شط العرب — سقوط البصرة وفتح جبهة العراق", "c0a87d5d"], "d": ["نزلت القوة الاستكشافية البريطانية القادمة من الهند في مطلع الحرب العالمية الأولى في الفاو عند مصب شط العرب، وأخذت البصرة بسرعة. وكان سقوط المدينة يعني فتح جبهة العراق ودخول الطرف الشمالي للخليج في السيطرة البريطانية.", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["جورجيا تعلن استقلالها — انحلال سايم عبر القوقاز", "6c79a8c7"], "d": ["أعلنت جورجيا، التي خرجت من سايم عبر القوقاز المؤسس بعد بريست-ليتوفسك، استقلالها وقامت جمهورية جورجيا الديمقراطية. وآلت غرب جورجيا مع كوتايسي إلى إدارة هذه الدولة الجديدة.", "7f834f47"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["إعلان جمهورية أذربيجان الديمقراطية", "8baecec3"], "d": ["بعد يومين من انفصال جورجيا أُعلنت جمهورية أذربيجان الديمقراطية؛ وكان المركز الأول كنجة. وفي اليوم نفسه قامت في يريفان جمهورية أرمينيا أيضًا، وانقسمت عبر القوقاز إلى ثلاث دول مستقلة.", "d4eb329a"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["احتلال القوات العربية والبريطانية لحلب", "00efb2da"], "d": ["بعد انهيار الجبهة الفلسطينية دخلت القوات المتقدمة شمالًا حلب؛ وآلت المدينة أولًا إلى القوات العربية ثم إلى القوات البريطانية. وهذا الاحتلال، الذي وقع قبل ثلاثة أيام من هدنة مودروس، أنهى فعليًّا الإدارة العثمانية في سوريا التي دامت أربعة قرون.", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["الجيش الأحمر يحتل أذربيجان — نهاية الجمهورية الديمقراطية", "ebbb4566"], "d": ["دخل الجيش الأحمر أذربيجان وحلّ البرلمان والحكومة؛ وانتهت جمهورية أذربيجان الديمقراطية التي دامت سنتين. وبذلك انتقل حوض نفط باكو وكنجة إلى الإدارة السوفييتية.", "67223904"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["خان ميسلون — نهاية عهد فيصل وانتقال سوريا إلى الانتداب الفرنسي", "80a932b0"], "d": ["ألحق الفرنسيون هزيمة شديدة بالقوات السورية في خان ميسلون على طريق بيروت-دمشق، وانتهت مملكة فيصل العربية في دمشق. وأقامت فرنسا فعليًّا سلطة الانتداب التي مُنحت لها في سان ريمو؛ وارتبطت المنطقة الممتدة من حلب إلى دمشق ومن إسكندرون إلى دير الزور بإدارة الانتداب الفرنسي.", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["تأسيس إمارة شرق الأردن — عبد الله بن الحسين يعلن إمارته", "5ef520c2"], "d": ["جاء عبد الله، ابن الشريف حسين، شمالًا عبر معان وأعلن إمارة شرق الأردن؛ واعترفت بريطانيا بعد وقت قصير بهذه الإدارة في إطار الانتداب. وصارت عمّان مركز الإمارة، وارتبطت هضبة الأردن، ومنها الكرك، بهذه الإدارة الجديدة.", "113f01ba"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["آلانيا (علائية) تدخل بعد السلاجقة في سيطرة إمارة محلية", "7b1489b3"], "d": ["مع تفكك دولة سلاجقة الأناضول فعليًّا في عقد 1290 استقلّ ميناء علائية (آلانيا) على ساحل المتوسط عن السلطة المركزية ودخل في سيطرة إمارات المنطقة (في هذه الفترة ضمن مجال نفوذ القرمانيين)؛ والتاريخ الدقيق وأي إمارة سيطرت عليه مباشرة غير واضحين في المصادر.", "78a4ff46"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["سينوب يأخذها غازي جلبي وتدخل في نفوذ الجاندارية", "f107586a"], "d": ["أخذ غازي جلبي، من الأسرة المؤسسة لإمارة الجاندار (إسفنديار أوغلو) التي قويت في منطقة قسطموني وسينوب مع ضعف السيادة الإيلخانية، سينوب نحو عام 1322 وجعل المدينة مركزًا ساحليًّا للإمارة.", "35c2fa9c"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["معاهدة زادار — دوبروفنيك تنتقل من البندقية إلى الحماية المجرية", "57fb81f9"], "d": ["أنهت معاهدة زادار الموقّعة في 18 شباط/فبراير 1358 سيادة البندقية على دلماسيا التي دامت 150 سنة؛ وبذلك خرجت دوبروفنيك (راغوزا) من إدارة البندقية ونالت وضع جمهورية شبه ذاتية الحكم تدخل تحت حماية الملك المجري لايوش الأول.", "e207c893"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["أرضروم ومنطقة أشقلة تتبدلان بين القره قويونلو والتيموريين", "ca64775a"], "d": ["في الفراغ الذي نشأ بعد وفاة تيمور عام 1405 تحرك سلطان القره قويونلو قره يوسف بين 1406-1408 ضد الولاة التيموريين في شرق الأناضول؛ وخرجت أرضروم وأشقلة المحيطة بها في هذا الصراع من السيطرة التيمورية ودخلت في نفوذ القره قويونلو.", "10b1b07c"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["أوزون حسن الآق قويونلو يُنهي الفرع الأيوبي في حصن كيفا", "2b464a1f"], "d": ["ضُمّت حصن كيفا (حسنكيف) وسعرد، وهما في دجلة العليا أحد الفرعين الأخيرين الباقيين من الأسرة الأيوبية مع حماة، في 1462 على يد سلطان الآق قويونلو أوزون حسن، فانتهت السيادة الأيوبية.", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["البرتغال تُكمل سيادتها على سواحل مضيق هرمز", "bef031f0"], "d": ["اكتملت في 1515 حملة الخليج العربي التي بدأها أفونسو دي ألبوكيرك عام 1507، فشملت جزيرة هرمز وقِشم المقابلة لها والبريمي؛ ودخلت مملكة هرمز التابعة لإيران فعليًّا في الحماية البرتغالية، واستولت البرتغال على التحكم بتجارة الخليج.", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["اتحاد لوبلين — الأراضي الأوكرانية تنتقل من ليتوانيا إلى بولندا", "1881ceff"], "d": ["وحّد اتحاد لوبلين الموقّع في 1 تموز/يوليو 1569 دوقية ليتوانيا الكبرى ومملكة بولندا في دولة واحدة (ريتش بوسبوليتا). وبحكم شروط الاتفاق نُقلت بودوليا وڤولينيا ومنطقة كييف (ومنها بار وبرديتشيف وبياويستوك وبراسلاف) إداريًّا من ليتوانيا مباشرة إلى مملكة بولندا.", "184b03dd"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["القوات المصرية تنسحب من منطقة الأحساء (لحسا)", "5ea75c8d"], "d": ["كانت قوات محمد علي باشا المصرية قد احتلت نجدًا وشرق الجزيرة العربية (ومنها الأحساء والقطيف والعقير والجبيل) عام 1836؛ وبحمل اتفاقية المضائق في لندن (1840) مصر على التخلي عن فتوحاتها في شبه الجزيرة العربية انسحبت القوات من المنطقة عام 1841، وعادت الإدارة إلى القوى المحلية (نفوذ آل سعود/آل خليفة).", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["القوات الروسية تأخذ قلعة آق مسجد — انهيار خط سير داريا لخانية قوقند", "e9f9a9c7"], "d": ["استولت القوات الروسية بقيادة الجنرال ڤاسيلي بيروفسكي في تموز/يوليو 1853 بعد حصار طويل على قلعة آق مسجد، التابعة لخانية قوقند على ضفة سير داريا؛ وصارت القلعة فيما بعد، باسم بيروفسك، مخفرًا متقدمًا لتركستان الروسية.", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["معركة غوك تبه — تركمان آخال تكه يُهزمون أمام روسيا", "76c7a102"], "d": ["كسرت القوات الروسية بقيادة الجنرال ميخائيل سكوبيليف مقاومة تركمان آخال تكه بإسقاطها قلعة غوك تبه (جيوك تبه) في 24 كانون الثاني/يناير 1881؛ ودخلت منطقة التركمان وراء بحر قزوين، ومنها سهل دهستان وأبيورد ونسا، في طور الانضمام إلى الإمبراطورية الروسية (أُنشئت منطقة ما وراء قزوين عام 1881).", "41bbf179"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["إعلان مملكة رومانيا — الإمارة تتحول إلى مملكة", "4d413f0c"], "d": ["تحولت إمارة رومانيا، التي اعترف مؤتمر برلين باستقلالها بعد الحرب العثمانية الروسية 1877-78، إلى مملكة في 26 آذار/مارس 1881 (14 آذار/مارس بالتقويم اليولياني) بتتويج الملك كارول الأول؛ وصارت البلاد كلها، ومنها بابا داغ وبيرلاد وبوزاو والعاصمة بوخارست، جزءًا إداريًّا من المملكة الجديدة.", "54ed49f3"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["إيطاليا تضم هضبة إريتريا بما فيها أسمرة وكرن", "31308dc8"], "d": ["ضمّت إيطاليا، مستفيدة من الفراغ في القوة الذي نشأ بوفاة إمبراطور الحبشة يوحنس الثاني عام 1889، هضبة إريتريا بما فيها أسمرة وكرن ضمًّا فعليًّا إثر معاهدة أوتشيالي (وتشالي) (2 أيار/مايو 1889)؛ وأُعلنت رسميًّا في 1 كانون الثاني/يناير 1890 مستعمرةً باسم «إريتريا».", "66fdfc34"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["المنطقة الشمالية الشرقية من كينيا (خط غاريسا-مارسابيت) تنضم إلى محمية شرق أفريقيا البريطانية", "e45c6d43"], "d": ["اتسعت محمية شرق أفريقيا البريطانية، التي قامت بتنازل شركة شرق أفريقيا البريطانية عن امتيازها للتاج عام 1895، فشملت مناطق الشمال الشرقي مثل غاريسا وكيتوي ومارسابيت وواجير؛ وامتد إخضاع هذه المناطق الداخلية للإدارة الفعلية على النصف الثاني من عقد 1890.", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["إمارة إلورن تقع في أيدي قوات شركة النيجر الملكية", "b111cb7d"], "d": ["وقعت إمارة إلورن، التابعة لخلافة سوكوتو، في أيدي قوات شركة النيجر الملكية بقيادة السير جورج غولدي في حملة شباط/فبراير 1897؛ وكُسرت قوة الإمارة العسكرية ودخلت المنطقة فعليًّا في النفوذ البريطاني (واكتمل الضم الرسمي بإنشاء محمية نيجيريا الشمالية عام 1900).", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["أسر ملك بونيورو كاباريغا وإلحاق المملكة بمحمية أوغندا البريطانية", "62bc7c64"], "d": ["أُسر كاباريغا ملك بونيورو، الذي قاوم القوات البريطانية منذ 1894، في منطقة لانغو (قرب دوكولو) في 9 نيسان/أبريل 1899 ونُفي إلى سيشل؛ وضُمّت أراضي المملكة، ومنها العاصمة هويما ومسيندي، إلى محمية أوغندا البريطانية.", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["معاهدة تورو — مملكة تورو تصبح جزءًا ذاتي الحكم من محمية أوغندا البريطانية", "c55340a2"], "d": ["بعد سقوط بونيورو عام 1899 أضفت مملكة تورو المجاورة طابعًا رسميًّا على الحماية البريطانية القائمة منذ 1896 في إطار معاهدة أوغندا لعام 1900؛ ونالت المملكة، ومنها العاصمة فورت بورتال، وضع إدارة محلية ذاتية الحكم داخل محمية أوغندا البريطانية.", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["إمارة أداماوا تُقسم بين ألمانيا وبريطانيا", "b9230d3d"], "d": ["قُسمت إمارة أداماوا (فومبينا)، التابعة لخلافة سوكوتو، إلى قسمين في ختام حملات القوات الاستعمارية الألمانية والبريطانية في 1899-1901: فانضم القسم الشرقي (ومنه غاروا وبانيو ومارووا ونغاوندر) إلى الكاميرون الألمانية، والقسم الغربي (عاصمته يولا) إلى نيجيريا الشمالية البريطانية؛ ونُفي الأمير زبير.", "671ba3aa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["معركة تيت — طوارق أهجار يُهزمون أمام القوات الفرنسية", "831143d6"], "d": ["في المعركة التي جرت قرب واحة تيت يوم 7 أيار/مايو 1902 في أثناء حملة كوتنست هزمت القوات الفرنسية طوارق كل أهجار هزيمة حاسمة؛ ودخلت هذه المنطقة الداخلية من الصحراء، ومنها أبالسة مركز أهجار وإيديلس، في سيطرة الجزائر الفرنسية.", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["القوات الفرنسية تستولي على المناطق الداخلية من أوبانغي-شاري (خط بامباري-بريا)", "0b9a9f72"], "d": ["أخضعت الحملات الشمالية للكونغو الفرنسي فعليًّا في مطلع عقد 1900 المنطقة الداخلية من أوبانغي-شاري، وهي تشمل بامباري وباتانغافو وبوسانغوا وبريا؛ ونُظمت المنطقة رسميًّا في 29 كانون الأول/ديسمبر 1903 مستعمرةً باسم أوبانغي-شاري (جزءًا من أفريقيا الاستوائية الفرنسية).", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["القوات الفرنسية تقضي على سلطنة دار الكوتي التابعة للسلطان محمد السنوسي", "644b2c3f"], "d": ["قُضي فعليًّا على سلطنة دار الكوتي، القائمة على تجارة الرقيق وعاصمتها ندلي، والتي دخلت الحماية الفرنسية عام 1897، بحملة نُظمت عام 1911 بعدما واصل السلطان محمد السنوسي مقاومة السلطة الفرنسية؛ وقُتل السنوسي في المعركة وأُلغيت السلطنة رسميًّا عام 1912.", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["نظام ليفونيا يتنازل عن أراضي كلايبيدا (ميميل) لفرع بروسيا من النظام التوتوني", "e61e5d50"], "d": ["تركت طريقة ليفونيا قلعة كلايبيدا (ميميل) عند مصب نيمان والأراضي المحيطة بها لفرع بروسيا من النظام التوتوني؛ وتنازل أسقف كورلاند عن حصته أيضًا لهذا الفرع في 1392. وبقيت كلايبيدا في النظام بصلحي تورون 1411 وملنو 1422، وانتقلت عام 1525 إلى دوقية بروسيا.", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["عمر بك يأخذ قلعة ميناء إزمير من الجنوية", "ab92d96e"], "d": ["حاصر الآيديني عمر بك قلعة ميناء إزمير، التي بقيت في يد اللاتين، سنتين ونصف السنة. وسلّم الحاكم الجنوي للقلعة مارتينو زكاريا القلعة وذهب إلى ساقز.", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["السوتايي إبراهيم شاه يسيطر على ديار بكر", "179196cf"], "d": ["بعد تفكك الدولة الإيلخانية سيطر السوتايي إبراهيم شاه على منطقة ديار بكر التي شهدت صراعات بين الجلائريين والجوبانيين؛ واستمرت سيادته حتى 1353.", "6143de93"]},
"OLAYLAR_2S_0919:1343-01-01:1":{"b": ["بيرات تنتقل من البيزنطيين إلى الصرب — فتح ستيفان دوشان لألبانيا", "1eba202e"], "d": ["إن قلعة بيرات، التي كسرت حصار الأنجويين عام 1281 وكانت منذ ذلك التاريخ مركز آخر إقليم بيزنطي على الأدرياتيكي، انتقلت إلى الصرب في أثناء تقدم ستيفان دوشان نحو ألبانيا والحرب الأهلية البيزنطية مستمرة. وبعد استسلام كرويا في أيار/مايو أو حزيران/يونيو 1343 صارت بيرات وقانينا وأفلونية للصرب في غضون سنتين؛ وعُيّن على رأس الإقليم صهر دوشان جون كومنينوس أسين.", "21876887"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["العبد الواديون (الزيانيون) يتحررون في تلمسان من سيادة المرينيين", "a4aa9573"], "d": ["تحرر العبد الواديون في تلمسان من سيادة المرينيين بقيادة عثمان الثاني وأخيه أبي ثابت. وقصر هذا الاستقلال.", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["بيرام خوجه ينال استقلاله — ولادة إمارة القره قويونلو", "37964815"], "d": ["نال بيرام خوجه، الذي يُعدّ أول بك للقره قويونلو، استقلاله بقتل حاكم السوتاي أق ساقال حسين بك. وأخذ الموصل وأعطى إدارتها لأخيه بردي خوجه.", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["بوفاة إبراهيم شاه تدخل ديار بكر في إدارة الجلائريين", "11c338ef"], "d": ["عند وفاة السوتايي إبراهيم شاه، الذي كان مسيطرًا على منطقة ديار بكر منذ 1343، دخلت المنطقة في إدارة الجلائريين.", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["إينوس تنتقل إلى الإدارة الجنوية (أسرة غاتيلوزي)", "5dc12940"], "d": ["انتقلت إينوس، التي كانت مدينة ميناء مهمة في العهد البيزنطي، عام 1355 إلى الإدارة الجنوية وحكمتها أسرة غاتيلوزي.", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["دوق ليتوانيا الأكبر ألغيرداس (أولغيرد) يأخذ بريانسك", "3cad9caf"], "d": ["أخذ جيش دوق ليتوانيا الأكبر ألغيرداس بريانسك. وبقيت المدينة تابعة لدوقية ليتوانيا الكبرى حتى 1500.", "03107c6d"]},
"OLAYLAR_2S_0919:1362-01-01:0":{"b": ["إمارة كييف تنتقل إلى سيادة ليتوانيا", "c4fda115"], "d": ["دخلت إمارة كييف في سيادة ليتوانيا، وصارت في الدولة الليتوانية الروسية إمارة تابعة يحكمها أمراء من سلالة غيديميناس.", "d4a2f5ec"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["الإينانجيون يعترفون بسيادة الجرميانيين", "0679db27"], "d": ["اعترفت إمارة الإينانج، التي حكمت حول دنيزلي، بسيادة الجرميانيين على الأرجح عام 1368.", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["دوق سالونيك مانويل يضع منطقة سيرس ودراما تحت الإدارة البيزنطية", "abb99c3e"], "d": ["بمقتل الملك ڤوكاشين ودوق سيرس أوغليشا في جرمن (26 أيلول/سبتمبر 1371) انتهت الإدارة الصربية في منطقة سيرس. ووضع الأمير البيزنطي مانويل الثاني باليولوغوس، الذي حكم في سالونيك، في تشرين الثاني/نوفمبر 1371 سيرس والمنطقة التي فيها دراما تحت الإدارة البيزنطية. وانتقلت المنطقة إلى العثمانيين في أيلول/سبتمبر 1383.", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["بوفاة بير حسين بك تنتقل أرزنجان وبايبورت إلى مطهرتن", "3269e55d"], "d": ["عند وفاة أمير أرزنجان بير حسين بك آلت أرزنجان وبايبورت إلى مطهرتن، أحد أمراء الإيرتنيين؛ وصار مطهرتن أمير أرزنجان.", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["تاج الدين بك يهزم جيش الإيرتنيين في نيكسار ويتصرف باستقلال", "42982ea7"], "d": ["هزم تاج الدين بك في ربيع 1379 قوات القاضي برهان الدين وبك الإيرتنيين علاء الدين علي اللذين هاجما نيكسار. وقطع دفع الضريبة لإمارة الإيرتنيين وتصرف باستقلال منذ سنة 781 (1379).", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["تيمور يستولي على خوارزم استيلاءً نهائيًّا", "ef76d2c9"], "d": ["نظّم تيمور بعد حملة خوارزم الأولى عام 1371 ثلاث حملات أخرى. وفي حملة 1379 استولى على المنطقة استيلاءً نهائيًّا ونهبها وعاد بغنائم وفيرة.", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["ملك البوسنة تفرتكو الأول يؤسس هرسك نوفي", "1628221a"], "d": ["أسّس ملك البوسنة تفرتكو الأول بلدة جديدة في خليج توبلا لتنافس دوبروفنيك في تجارة الملح؛ وعُرفت البلدة فيما بعد باسم نوڤي (هرسك نوڤي).", "b970dc7f"]},
"OLAYLAR_2S_0919:1383-01-01:0":{"b": ["تيمور يأخذ قندهار من الكرتيين ويعطيها لحفيده بير محمد", "84760f70"], "d": ["أُخذت قندهار، التي كانت منذ 1281 في يد الكرتيين أصحاب هراة التابعين للإيلخانيين، في أثناء حملات تيمور على خراسان، وأُعطيت لحفيده بير محمد؛ وصارت المدينة بعد ذلك يحكمها ولاة تيموريون.", "c2470eb5"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["الدلقادري خليل بك يستعيد الأبلستين من المماليك", "ee3da686"], "d": ["استعاد الدلقادري خليل بك عام 1384 الأبلستين التي آلت إلى المماليك عام 1381.", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["تيمور يستولي على ديار بكر (آمد) وينهبها", "f8d200a8"], "d": ["استولى تيمور على ديار بكر في 25 أو 26 نيسان/أبريل 1394 ونهب المدينة.", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["غيراردو أبياني يترك بيزا لآل ڤيسكونتي ويؤسس سيادة بيومبينو", "ac45a9dd"], "d": ["ترك سيد بيزا غيراردو أبياني المدينة لحاكم ميلانو جان غاليتسو ڤيسكونتي مقابل 200.000 فلورين. وخصّص لنفسه سيادة بيومبينو المؤلفة من بيومبينو وسوڤيريتو وسكارلينو وجزر إلبا وبيانوزا ومونتكريستو.", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["ديار بكر تُعطى لقره يولوق عثمان بك — بدء سيادة الآق قويونلو", "38262401"], "d": ["أُعطيت ديار بكر، التي استولى عليها تيمور عام 1394، لقره يولوق عثمان بك عام 1401، وبذلك بدأت سيادة الآق قويونلو في المنطقة.", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["أرزنجان تدخل في سيادة القره قويونلو", "5729a50b"], "d": ["بعد المطهرتن آلت أرزنجان إلى سلطان القره قويونلو قره يوسف. وعيّن قره يوسف أول الأمر بير عمر، أحد الرجال الذين يثق بهم، واليًا على المدينة.", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["الأسكيا محمد يأخذ زاغة (ديا)", "24561a8c"], "d": ["استولى الأسكيا محمد، الذي اعتلى عرش سونغاي، في نهاية سنة 899 هـ بوساطة أخيه كورمينا-فاري عمر كومزاغو على مدينة زاغة (ديا) في غرب الدلتا الداخلية للنيجر.", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["شيباني خان يأخذ بخارى وسمرقند", "8f8f40eb"], "d": ["استفاد محمد شيباني خان من الفوضى بين التيموريين فأخذ بخارى وسمرقند وأسس أسرة الشيبانيين (الأوزبك). وبين 1500 و1507 استولى على جميع مدن ما وراء النهر وخوارزم وخراسان تقريبًا.", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["الإسبان يحتلون بجاية", "8faa0133"], "d": ["احتل الجيش الإسباني المؤلف من 8000 رجل، الذي جاء بالسفن، بجاية؛ وتملّك الذعر أهل المدينة فتركوا ديارهم.", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["أغاديس تُلحق بسونغاي", "997362b0"], "d": ["ألحق سلطان سونغاي الأسكيا محمد أغاديس، مركز منطقة آير، بغاو؛ وحملت المدينة هذه التبعية حتى انهيار سونغاي في تونديبي عام 1591.", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["قيام سلطنة باغرمي", "03829f94"], "d": ["أسّست قبيلة كنغا بقيادة بيرني بيسي دولة قوية مركزها ماسينيا (ماسينيا) شرق بحيرة تشاد. ويؤرَّخ تأسيس أسرة باغرمي تقليديًّا بعام 1522.", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["وفاة آخر دوق من آل سفورزا وانتقال ميلانو إلى شارل الخامس", "53230b5c"], "d": ["توفي دوق ميلانو فرانشيسكو الثاني سفورزا بلا ولد في ليلة 1-2 تشرين الثاني/نوفمبر 1535. وانتقلت الدوقية إلى الإمبراطور شارل الخامس وبدأت تُدار بحاكم إسباني.", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["الجنوية يستقرون في جزيرة طبرقة", "0cb474f8"], "d": ["بناءً على اتفاقية شارل الخامس مع حاكم تونس التي أذنت ببناء قلعة على الساحل وبصيد المرجان، أُسكنت في جزيرة طبرقة جماعة جنوية من بيغلي. وصارت الجزيرة قاعدة تجارية تديرها أسرة لوميليني.", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["بعد وفاة همايون يأخذ الصفويون قندهار من المغول", "318eabc8"], "d": ["بعد وفاة همايون في دلهي عام 1556 استفاد الشاه طهماسب من الصراع بين الولاة المغول في قندهار وزمين داور؛ فدخلت قندهار قوة صفوية جاءت بدعوة والي زمين داور، وعيّن طهماسب ابن عمه السلطان حسين ميرزا واليًا على المدينة. وبقيت المدينة في يد الصفويين حتى 1595.", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["روسيا تغزو ليفونيا وتسقط دوربات", "dcb46a8a"], "d": ["غزا إيفان الرابع ليفونيا طلبًا للمنفذ إلى بحر البلطيق وبدأ حرب ليفونيا؛ فأخذ ناروا ودوربات (تارتو) وحاصر ريفال.", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["تأسيس قلعة كارلوفاتس", "9b28e6ad"], "d": ["أُسّست قلعة كارلوفاتس في منطقة الفيضان بين كوبا وكورانا لحماية كرواتيا والأراضي الوراثية النمساوية من العثمانيين؛ وبنى القلعة الأرشيدوق كارل الثاني قائد الحدود العسكرية الكرواتية.", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["وثيقة تأسيس (لوكاسيو) زاموشتش", "e1157f3b"], "d": ["منح المستشار الأكبر لبولندا يان زاموسكي وثيقة تأسيس (لوكاسيو) مدينة زاموشتش.", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["هدنة يام زابولسكي — ليفونيا ودوربات تنتقلان إلى بولندا", "7d02d8ad"], "d": ["وُقّعت هدنة يام زابولسكي بين بولندا-ليتوانيا وروسيا؛ وتخلت موسكو عن دعاواها في ليفونيا وأعادت أراضي بولوتسك. وبقيت دوربات (تارتو) في يد بولندا منذ 1582.", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["ذكر قلعة تساريتسين لأول مرة في وثيقة", "ddf65b06"], "d": ["يذكر مرسوم القيصر فيودور إيفانوفيتش المؤرخ في 2 تموز/يوليو 1589 قلعة تساريتسين التي أُنشئت لحماية الحدود الجنوبية لنهر الڤولغا؛ ويُعدّ هذا التاريخ يوم تأسيس المدينة.", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["تأسيس قلعة ساراتوف", "a3ca702c"], "d": ["أسّس الأمير زاسيكين ساراتوف قلعةً ومخفرًا لحماية طريق الڤولغا والحدود الشرقية للدولة من غارات البدو الرحّل.", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["تأسيس قلعة بيليم", "baf3e7eb"], "d": ["أسّس الفويفود بيوتر غورتشاكوف بيليم على ضفة نهر تاڤدا؛ وصارت القلعة إحدى نقاط الارتكاز في التقدم الروسي في غرب سيبيريا.", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["تأسيس قلعة ڤيرخوتوريه", "81be29bb"], "d": ["أُسّست نقطة ڤيرخوتوريه المحصنة على ضفة نهر تورا، في موضع مستوطنة نيرومكار القديمة؛ ويرتبط تأسيسها بالبحث عن طريق أقصر إلى سيبيريا.", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["تأسيس قلعة تورينسك على ضفة تورا", "c1d8534e"], "d": ["أُسّست في عام 1600 في منطقة تورينسك الحالية قلعة تورينسك (أوستروغ) القوزاقية الروسية لجباية الضريبة؛ وهي من التحصينات التي أقامها التقدم الروسي في غرب سيبيريا على الطريق.", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["الشاه عباس الأول يؤسس مدينة فرح آباد في مازندران", "cab4d0fe"], "d": ["أنشأ الحاكم الصفوي عباس الأول مدينة فرح آباد في مازندران في موضع قريب من ساحل بحر قزوين، وأسكن فيها أناسًا من أنحاء البلاد كلها. وبدأ البناء في 1020/1611.", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["تأسيس قلعة براتسك الروسية على أنغارا", "e7b4be59"], "d": ["في أثناء تقدم روسيا نحو سيبيريا الشرقية أُسّست قلعة براتسك على نهر أنغارا.", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-02-26:0":{"b": ["معاهدة روسكيلده — سكونه وهالاند وبلكينغه وبورنهولم تنتقل إلى السويد", "afcae41b"], "d": ["وُقّعت معاهدة روسكيلده التي أنهت حرب كارل غوستاف الأولى؛ وتركت الدنمارك-النرويج سكونه وهالاند وبلكينغه وبورنهولم للسويد.", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["روسيا تؤسس قلعة بينزا على سورا", "49e8d90b"], "d": ["أُسّست بينزا قلعةً كبيرة عند ملتقى نهري بينزا وسورا؛ وبعد 1684 كوّنت الطرف الغربي لخط دفاع سيزران.", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["ماركيت يؤسس البعثة الفرنسية في سو سانت ماري", "86612bcd"], "d": ["أسّس اليسوعي جاك ماركيت بعثة عند أعلى شلالات سو سانت ماري بين بحيرتي سوبيريور وهورون.", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["تأسيس أول مخفر لشركة خليج هدسون (واسكاغانيش)", "07b32d57"], "d": ["أسّس ميدار شوار دي غروزييه في خليج جيمس عند مصب نهر روبرت المستوطنة التي عُدّت فيما بعد أول مخفر لشركة خليج هدسون.", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["الإدارة الاستعمارية الإسبانية تؤسس بيتيك (هرموسيو)", "11e5cc04"], "d": ["أسّست الإدارة الاستعمارية الإسبانية بلدة في موضع مستوطنة أهلية قديمة؛ وأخذت البلدة عام 1828 اسم خوسيه ماريا غونزاليس دي هرموسيو.", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["تأسيس قلعة أومسك الروسية عند ملتقى إرتيش-أوم", "13dcce5e"], "d": ["أُسّست أومسك قلعةً عند الطرف الشرقي لخط تحصينات إيشيم بين توبول وإرتيش؛ وصارت مدينة عام 1804.", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["الجونغار يهاجمون لاسا — مقتل لاجانغ خان ودخول التبت تحت الاحتلال الجونغاري", "65beea29"], "d": ["هاجم الجيش الجونغاري بقيادة تسيرينغ دوندوب لاسا، التي كان يدافع عنها حاكم الخوشوت لاجانغ خان، من كل الجهات بعد منتصف الليل؛ وبمساندة من الداخل استولى الجونغار على المدينة ونهبوها ونهبوا قصر بوتالا أيضًا. وقُتل لاجانغ خان وهو يفرّ؛ وأقام الجونغار حكومة تبتية صورية برئاسة sTag-rtse-pa.", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["جيش تشينغ يدخل لاسا — نهاية الاحتلال الجونغاري وبدء الحماية التشينغية", "083358c1"], "d": ["من الجيشين اللذين أرسلهما كانغشي إلى التبت وصلت فرقة سيتشوان بقيادة غالبي إلى لاسا بعد مسيرة شاقة وأخذت المدينة بلا مقاومة؛ فقد جمع الجونغار كل قواتهم في دام لمواجهة جيش كوكونور القادم من الشمال. وبانسحاب الجونغار من التبت أقامت التشينغ في لاسا نظام حماية دائمًا.", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["حملة أغويو تؤسس حصن لوس آداس", "2031793a"], "d": ["أسّست حملة المركيز دي أغويو حصنًا (بريسيديو، أي مخفرًا عسكريًّا) في لوس آداس وأعادت إسكان البعثة؛ وصار الحصن نقطة حدود تكساس الشرقية لإسبانيا الجديدة في مواجهة لويزيانا الفرنسية.", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["تأسيس مخفر كاينسك الروسي في سهوب بارابا", "b14552a8"], "d": ["من بين ثلاثة تحصينات روسية دائمة (ممرات) أُقيمت في سهوب بارابا أُسّس ممر كاينسك في الجزء الأوسط من نهر أوم عند ملتقى جدول كاينكا.", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["تأسيس قلعة تروئيتسك الروسية على ضفة أوي", "623d75f2"], "d": ["أُسّست تروئيتسك قلعةً عند ملتقى أوفيلكا بنهر أوي، ونالت براءة المدينة عام 1784.", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["بمرسوم إليزافيتا يؤسس مركز جمرك تيميرنيك عند مصب الدون (نواة روستوف)", "46519168"], "d": ["أصدرت الإمبراطورة إليزافيتا بيتروفنا مرسومًا بإنشاء جمرك على الدون عند مصب نهر تيميرنيك؛ ويُعدّ جمرك تيميرنيك بداية التاريخ المبكر لمدينة روستوف على الدون.", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["الفرنسيون يؤسسون مخفرًا تجاريًّا في تورنتو على نهر هامبر", "18975f4c"], "d": ["أسّس الفرنسيون مخفرًا ثانيًا على نهر هامبر؛ وفي السنة التالية بنوا حصن رويّيه في موضع إكزيبيشن بليس الحالي.", "66aeb450"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["أحمد شاه الدراني يضم بلخ إلى بلاده", "12c6bbf1"], "d": ["ضمّ الحاكم الأفغاني أحمد شاه الدراني بلخ إلى مجال سيادته.", "e3ef9016"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["تأسيس قلعة بتروبافلوفسك الروسية على إيشيم", "5d16ef42"], "d": ["أُسّست بتروبافلوفسك قلعةً روسية، وصارت بسرعة مركزًا مهمًّا للتجارة بين روسيا وآسيا الوسطى والسهوب الكازاخية.", "f0724528"]},
"OLAYLAR_2S_0919:1759-01-01:0":{"b": ["طوارق أغاديس يأخذون مملحة بلما من كانم-برنو", "1a563a74"], "d": ["فقدت كانم-برنو، التي كانت تعاني الانحدار في القرن الثامن عشر، عدة مواضع في الصحراء عام 1759 حين انتزع طوارق أغاديس منها مملحة بلما.", "ebfc53c3"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["جيش الجهاد لعثمان بن فودي يأخذ زاريا", "41279ca7"], "d": ["في أثناء الجهاد الذي بدأه عثمان بن فودي، رغم فشل الهجوم الأول على ألكالاوا عاصمة غوبير، أُخذت زاريا عام 1806.", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["تأسيس مدينة سلطان آباد (أراك)", "674237a0"], "d": ["في العهد القاجاري أسّس الجنرال يوسف خان الكرجي مدينة أراك الحالية وسمّاها سلطان آباد.", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["تأسيس بلدة بوفورت (بوفورت ويست)", "c5cb1776"], "d": ["أُسّست بلدة بوفورت في مستعمرة الرأس البريطانية على مزرعة هويفلاكته في الكارو.", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["بلخ تقع تحت احتلال أمير بخارى", "cd255a5d"], "d": ["وقعت بلخ، التي كانت تحت السيادة الأفغانية الدرانية، تحت احتلال أمير بخارى عام 1826؛ واستعادها الأفغان عام 1841.", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["روسيا تؤسس قلعة أقمولا على إيشيم", "6c727ca9"], "d": ["بنت روسيا قلعة أقمولا في قراوتكول على نهر إيشيم، وجعلتها البلدة المركزية لبلاد قرغيز (قازاق) سيبيريا.", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["تأسيس تحصين كوبال — شمال يديسو يبدأ بالارتباط بروسيا", "8d4c24c6"], "d": ["أسّست روسيا، بطلب من قازاق الجوز الكبير، تحصين كوبال عند سفح ألاتاو يديسو. وبحسب المصدر سهّل هذا انضمام شمال يديسو حتى نهر إيلي إلى روسيا.", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["تجار الساحل يستقرون في كازه (طابورة)", "173223b0"], "d": ["هاجر التجار القادمون من ساحل شرق أفريقيا جنوبًا بعد نزاع مع حاكم محلي؛ وأعطاهم رئيس أونيانيمبي فونديكيرا مكان إقامة قرب مركزه إيتيتيميا. وصارت هذه المستوطنة نواة مركز القوافل في طابورة.", "1261b92f"]},
"OLAYLAR_2S_0919:1861-01-01:0":{"b": ["فولاني الحاج عمر يأخذون جني", "aa4e37f8"], "d": ["وقعت جني، التي كان لدولة ماسينا فيها حامية، عام 1861 في أيدي الفولاني بقيادة الحاج عمر.", "bfbc8ebe"]},
"OLAYLAR_2S_0919:1862-05-16:0":{"b": ["الحاج عمر يأخذ حمد الله — نهاية دولة ماسينا", "542f1c0d"], "d": ["هُزمت القوات المتحالفة لماسينا التي لجأ إليها بينا علي الفار من سيغو؛ وآل مركز ماسينا حمد الله إلى الحاج عمر، وأُعدم بينا علي وأحمدو أحمدو.", "213cc232"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["براززا يؤسس فرانسيفيل", "d28410d7"], "d": ["أسّس بيير سافورنيان دي براززا باسم فرنسا مخفر فرانسيفيل على نتوء صخري مطل على نهر مباسا.", "c23dd54e"]},
"OLAYLAR_2S_0919:1885-02-14:0":{"b": ["اتفاقية الحدود بين دولة الكونغو الحرة والبرتغال — الضفة الجنوبية لمصب الكونغو للبرتغال", "08a16627"], "d": ["رُسمت بموجب الاتفاقية الموقّعة أثناء انعقاد مؤتمر برلين الحدود بين دولة الكونغو الحرة والبرتغال من مصب نهر الكونغو (زائير) إلى جدول أوانغو-أوانغو بالنهر نفسه؛ فكانت الضفة الجنوبية التي فيها سويو للبرتغال، وبقيت كابيندا شمال النهر للبرتغال.", "947cb572"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["ساحل حضرموت (المكلا) يدخل في الحماية البريطانية", "dc824725"], "d": ["وُقّعت معاهدة حماية بين إنجلترا والياقعيين (الكعيتيين) المسيطرين على ساحل حضرموت، ومنه الشحر والمكلا؛ وتولّى الإنجليز بالكامل العلاقات الخارجية للإدارة اليافعية في الساحل.", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["الفرنسيون يسيطرون على الولوف كلها", "c6d28eaa"], "d": ["سيطر الفرنسيون، الذين استعمروا المنطقة باتفاقات مع رؤساء القبائل، عام 1890 على الولوف كلها.", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["الفرنسيون يحتلون جني", "b207bf62"], "d": ["احتلت القوات الفرنسية عام 1893 جني، التي كانت في يد الدولة التي أسسها الحاج عمر، وضمتها إلى السودان الفرنسي.", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["تأسيس غويرو مخفرًا عسكريًّا", "bd37b323"], "d": ["أُسّست مدينة غويرو في وسط زيمبابوي الحالية مخفرًا عسكريًّا؛ وصارت فيما بعد مركزًا زراعيًّا ونالت صفة البلدية عام 1914.", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["سلطنة باغرمي تدخل في الحماية الفرنسية", "59f20c32"], "d": ["عقد حاكم باغرمي غاورانغ مع فرنسا معاهدة حماية اضطرارية أمام تهديد رابح. ولما توجه رابح، ردًّا على ذلك، إلى احتلال باغرمي أحرق غاورانغ العاصمة ماسينيا بيده.", "fcb0958f"]},
"OLAYLAR_2S_0919:1897-10-01:0":{"b": ["مملكة كافا تنضم إلى الحبشة — أسر آخر ملوكها غاكي شيروتشو", "c03c44c5"], "d": ["دخلت قوات منليك الثاني بقيادة راس ولدا جورجيس كافا في آذار/مارس 1897. وبعد اشتباكات شديدة فُتحت كافا؛ وأُسر آخر ملوكها غاكي شيروتشو وسلّم نفسه في تشرين الأول/أكتوبر 1897.", "a434cc44"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["الفرنسيون يحتلون غاو", "01eabb4c"], "d": ["احتل الفرنسيون عام 1898 غاو، عاصمة السونغاي القديمة على ضفة النيجر؛ وبعد الاحتلال نمت المدينة من جديد وصارت مركز المنطقة.", "653ce49b"]},
"OLAYLAR_2S_0919:1899-01-01:0":{"b": ["تأسيس مستودع إمداد نيروبي لسكة حديد أوغندا", "a3ce3389"], "d": ["أقام الإنجليز في الموقع الحالي لنيروبي، وكان حتى ذلك الحين منطقة مستنقعات خالية في معظمها، مستودع الإمداد لسكة حديد أوغندا التي تربط ممباسا بأوغندا.", "467c7577"]},
"OLAYLAR_2S_0919:1901-01-01:0":{"b": ["تقسيم أداماوا — يولا تبقى في نيجيريا الشمالية البريطانية", "11104686"], "d": ["قُسمت أداماوا بين نيجيريا الشمالية التابعة لبريطانيا والكاميرون التابعة لألمانيا؛ وصار بوبو أحمدو، الابن الرابع لأداما، أمير يولا في المنطقة البريطانية.", "aabd087e"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["معركة بورمي — نهاية السيادة السياسية لخلافة سوكوتو", "c7d87e2c"], "d": ["قُتل الخليفة محمد الطاهر، الذي فرّ بعد احتلال الإنجليز سوكوتو، في معركة جديدة مع الإنجليز؛ وانتهت السيادة السياسية لخلافة سوكوتو التي دامت نحو قرن.", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["تأسيس ناكورو رسميًّا بلدةً", "d82a2d76"], "d": ["أُسّست ناكورو رسميًّا بلدةً بفضل موقعها على سكة حديد أوغندا، وصارت مركز المنتجات الزراعية في المنطقة.", "bf30445b"]},
"OLAYLAR_2S_0919:1905-01-01:0":{"b": ["افتتاح محطة بحر آرال على خط أورنبورغ-طشقند — تأسيس مستوطنة آرالسك", "85803dcb"], "d": ["حين مرّ خط سكة حديد الإمبراطورية الروسية الرابط بين أورنبورغ وطشقند بالطرف الشمالي الشرقي لبحر آرال، افتُتحت على الساحل محطة «أرالسكويه مورييه»؛ ونشأت بجوار المحطة مستوطنة صيادين. ونالت المستوطنة عام 1938 صفة المدينة وأخذت اسم آرالسك.", "99e15bce"]},
"OLAYLAR_2S_0919:1909-06-02:0":{"b": ["الفرنسيون يأخذون أبشه — نهاية سلطنة وداي", "3c9b117b"], "d": ["واصل الفرنسيون تقدمهم نحو الشرق فاستولوا على أبشه (أبيشة)، عاصمة وداي، وأنهوا سلطنة وداي؛ وانسحب السلطان الأخير من دون أن يستطيع إنقاذ عاصمته.", "1f305da8"]},
"OLAYLAR_2S_0919:1910-05-31:0":{"b": ["تأسيس اتحاد جنوب أفريقيا", "7434a47f"], "d": ["وفقًا لقانون جنوب أفريقيا لعام 1909 اتحدت مستعمرات الرأس وناتال وترانسفال ونهر أورانج في 31 أيار/مايو 1910 باسم اتحاد جنوب أفريقيا التابع للإمبراطورية البريطانية؛ وصارت بريتوريا مركز السلطة التنفيذية وكيب تاون مركز السلطة التشريعية.", "4fed5a23"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["الفرنسيون يحتلون جانت (جانيت)", "f32997c8"], "d": ["احتل الفرنسيون عام 1911 جانت، وهي ناحية عثمانية تابعة لغات. وقد تقاضى مدير الناحية الشيخ عمود راتبه من الدولة العثمانية حتى هذا التاريخ.", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["تأسيس أنكوريج مركزًا لسكة حديد ألاسكا", "f5014711"], "d": ["بعد أن أقرّ الكونغرس قانون سكة حديد ألاسكا في 12 آذار/مارس 1914 أقامت لجنة هندسة ألاسكا في ربيع 1915 موقع بناء السكة الحديدية في شيب كريك؛ ونشأت على الساحل مدينة خيام، وسمّى مكتب البريد في نيسان/أبريل 1915 البلدة الجديدة أنكوريج. وصارت المدينة مركز سكة حديد ألاسكا الممتدة شمالًا إلى فيربانكس.", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["ربط جغبوب، المركز الصحراوي للسنوسية، بالنظام العثماني — فرمان الإعفاء من عبد المجيد", "039fce6d"], "d": ["بعد أن عاد محمد بن علي السنوسي، الذي أقام في مكة سنوات طويلة، إلى طرابلس الغرب، استقر في واحة جغبوب على الحدود المصرية وبنى زاوية كبيرة على الصخرة المشرفة؛ وتحول المكان، الذي لم يكن سوى بضعة أكواخ، إلى مدينة في وقت قصير. وفي عام 1856 أُعفيت أملاك أتباع الطريقة من الضريبة بفرمان السلطان عبد المجيد، ومُنح المريدون صلاحية جمع الزكاة. وقد جعل هذا الفرمان الواحة الواقعة على طريق القوافل الذي يربط غرب أفريقيا والسودان بالقاهرة جزءًا من النظام المالي والإداري العثماني، وعزز جغبوب مركزًا للتجارة. ويؤكد ولاء أهل المنطقة للخليفة كذلك أدب الرحلة للأميرالاي صادق المؤيد الذي زارها عامي 1884 و1893.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["بدء حفر قناة السويس وتأسيس بورسعيد", "cef0be8d"], "d": ["بدأت أعمال الحفر في مشروع دي لسبس، الذي وافق عليه الباب العالي في 5 يناير 1856، في 25 أبريل 1859؛ وكانت القناة ستكتمل بعد عشر سنوات، في 16 نوفمبر 1869. وشكّلت قرية الأكواخ المؤلفة من خمسة بيوت التي أُقيمت للعمال عند الطرف المتوسطي للحفر، على الشريط الساحلي بين بحيرة المنزلة والبحر، نواة بورسعيد. وأُعطيت المدينة هذا الاسم، بمعنى «ميناء سعيد»، عام 1860 على يد مسؤولي شركة القناة إهداءً إلى والي مصر آنذاك سعيد باشا. وهكذا وُلد على خريطة الدولة العثمانية ميناء جديد على شريط ساحلي لم يكن فيه أي موطن قبل ذلك.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["زيارة السلطان عبد العزيز إلى مصر وتأسيس الإسماعيلية على برزخ السويس", "bcfacf38"], "d": ["ذهب السلطان عبد العزيز إلى مصر في 3 أبريل 1863 بتشجيع من الصدر الأعظم يوسف كامل باشا، واستُقبل باحتفاء كبير؛ وكان الهدف تقوية ولاء الولاية، التي بدأت منذ تمرد محمد علي باشا القوللو تتحول فعليًا إلى دولة مستقلة، للمركز. وفي العام نفسه أُقيم على البرزخ، في تلال الجسر على ضفاف بحيرة التمساح، المركز الإداري لشركة القناة: أُقيمت أولًا قرية التمساح للمهندسين، ثم قرية العرب للعمال. ولما اهتم الخديوي إسماعيل باشا اهتمامًا وثيقًا بقناة المياه العذبة وبنى لنفسه قصرًا على هذا التل، سُمّيت المستوطنة باسمه الإسماعيلية. ويؤرَّخ تأسيس المدينة بعام 1863؛ ولا يُعرف اليوم الدقيق.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["ولاية مدحت باشا على بغداد وتوطين العشائر — تأسيس الرمادي والناصرية", "0fa98f06"], "d": ["أدار مدحت باشا، الذي أُبعد عن إسطنبول بعد إخراجه من رئاسة شورى الدولة، ولاية بغداد، التي شملت الموصل والبصرة أيضًا، بين عامي 1869 و1872 بصلاحيات واسعة، وكانت قيادة الجيش السادس في عهدته كذلك. وطبّق هنا قانون الأراضي وقانون الولايات الجديد، فوزّع الأراضي بالطابو، وربط العشائر البدوية بحياة الاستقرار وبسلطة الدولة. وكان من ثمار سياسة التوطين هذه تأسيس الرمادي على ضفة الفرات لعشيرة الدليم عام 1869، وتأسيس الناصرية في الجنوب على يد متصرف المنتفق ناصر باشا السعدون؛ ونشأت كلتاهما في مواضع لم يكن فيها موطن حتى ذلك اليوم، ودخلتا الخريطة لأول مرة في هذا التاريخ.", "7babb36f"]},
"OLAYLAR_AMERIKA0920:1511-08-15:0":{"b": ["تأسيس باراكوا — أول بلدة في الفتح الإسباني لكوبا", "8c033cf1"], "d": ["بدأ دييغو ڤيلاثكيث دي كوييار فتح كوبا عام 1511 بقوة عبرت من هيسبانيولا، وأسّس نويسترا سينيورا دي لا أسونسيون دي باراكوا، أول بلدة إسبانية في الجزيرة. وصارت باراكوا منطقة القاعدة للحملات التي ستتوجه إلى المكسيك في العقدين التاليين (هرنانديث دي كوردوبا وغريخالبا وكورتيس).", "e3cd5e94"]},
"OLAYLAR_AMERIKA0920:1519-03-25:0":{"b": ["معركة سنتلا — سقوط إمارة بوتونشان المايوية وتأسيس سانتا ماريا دي لا ڤيكتوريا", "8489a7d8"], "d": ["رسا أسطول كورتيس الخارج من كوبا في مدينة بوتونشان، مدينة المايا التشونتالية عند مصب نهر غريخالبا. وفاز الإسبان في معركة سهل سنتلا بتفوقهم في الفرسان والسلاح الناري، فأسسوا مكان المدينة بلدة سانتا ماريا دي لا ڤيكتوريا. وهذه أول مستوطنة إسبانية دائمة في البر المكسيكي؛ وكانت مالينتسين (دونيا مارينا)، التي ستترجم لكورتيس، بين الهدايا المقدمة هنا.", "8bbece52"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["تأسيس بنما — أول مدينة أوروبية على ساحل المحيط الهادئ", "c0d86c22"], "d": ["أسّس والي داريين بيدرارياس دافيلا مدينة بنما على جانب المحيط الهادئ من البرزخ ونقل الإدارة الاستعمارية إليها من الساحل الكاريبي. وصارت المدينة ميناء انطلاق حملات الاستكشاف والفتح نحو الجنوب؛ وجُهّزت منها حملات فرانسيسكو بيثارو إلى بيرو.", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1520-09-04:0":{"b": ["إخضاع تيبياكا — أول فتوحات كورتيس بعد الليلة الحزينة", "a9c27711"], "d": ["بعد أن انسحب كورتيس من تينوتشتيتلان ليلة 30 حزيران/يونيو 1520 (نوتشي ترستي) بخسائر فادحة ولجأ إلى تلاكسكالا، شنّ أول هجوم له على إمارة تيبياكا التابعة للتحالف الثلاثي. وأخذ المدينة وأسّس بلدة إسبانية باسم سيغورا دي لا فرونتيرا؛ فأُمّن الطريق بين ساحل ڤيراكروث وتلاكسكالا وهُيّئت قاعدة الزحف الثاني على العاصمة.", "a7a4b070"]},
"OLAYLAR_AMERIKA0920:1523-07-25:0":{"b": ["تأسيس سان سباستيان دي كوليما — انفتاح إسبانيا الجديدة على ساحل المحيط الهادئ", "30332cab"], "d": ["أخضع غونزالو دي ساندوفال، أحد قادة كورتيس، وادي كوليما في غرب المكسيك وأسّس بلدة سان سباستيان دي كوليما. وصارت البلدة إحدى أولى قواعد إسبانيا الجديدة على ساحل المحيط الهادئ، وغذّت في السنوات التالية أحواض بناء السفن لرحلات استكشاف بحر الجنوب.", "f5225860"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["تأسيس سان فرانسيسكو دي كيتو — النظام الإسباني في عاصمة الإنكا الشمالية", "7bb9f316"], "d": ["أحرق قائد الإنكا رومينيياوي كيتو، عاصمة الشمال، قبل أن يتركها للإسبان. وأسّس سيباستيان دي بنالكاثار سان فرانسيسكو دي كيتو على الأنقاض؛ فارتبط بذلك مركز دولة الإنكا الثاني بعد كوسكو بالإدارة الإسبانية، وأُديرت الحملة في شمال الأنديز من هنا.", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["تأسيس ليما — عاصمة بيرو الإسبانية تُنقل إلى وادي ريماك", "1f15658c"], "d": ["أسّس فرانسيسكو بيثارو، لأن كوسكو الجبلية بعيدة عن الصلة البحرية بإسبانيا، سيوداد دي لوس ريس (ليما) في وادي ريماك على الساحل. وصارت المدينة بسرعة عاصمة نيابة الملك في بيرو ومركز الإدارة الإسبانية في أمريكا الجنوبية.", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["تأسيس بوبايان — الجسر بين كيتو وبلاد المويسكا", "bf451979"], "d": ["أسّس بنالكاثار، الذي زحف من كيتو نحو الشمال، بوبايان في وادي كاوكا. وصارت المدينة الطرف الشمالي للتقدم الإسباني القادم من بيرو، وفتحت في السنة التالية الطريق إلى لقائه بكيسادا في بلاد المويسكا.", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["الاستيلاء على هونزا — هزيمة الزاكي كيموينتشاتوتشا", "e8c1b661"], "d": ["هاجم غونزالو خيمينيث دي كيسادا، الذي صعد إلى الهضبة من نهر ماغدالينا، هونزا، مركز الزاكازغو أحد رأسي اتحاد المويسكا، وأسر الزاكي كيموينتشاتوتشا. وكان الذهب المأخوذ في المدينة الغنيمة الحقيقية التي غذّت شائعة إلدورادو؛ ودخل بذلك النصف الشمالي من بلاد المويسكا في السيادة الإسبانية.", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["تأسيس أسونسيون — القاعدة الإسبانية على نهر باراغواي", "9a6dfa42"], "d": ["حين لم تثبت حملة ريو دي لا بلاتا في بوينس آيرس انسحب الإسبان صعودًا في النهر، وأسّس خوان دي سالازار دي إسبينوسا، استنادًا إلى التحالف الذي أُقيم مع جماعات الغواراني، نويسترا سينيورا دي لا أسونسيون. وبقيت البلدة طوال قرن مركز الإدارة الإسبانية في حوض ريو دي لا بلاتا.", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["تأسيس سانتا فيه دي بوغوتا — العاصمة الإسبانية في بلاد المويسكا", "3ed6c301"], "d": ["أسّس كيسادا سانتا فيه دي بوغوتا بجانب باكاتا، مركز الزيبا. وبعد التأسيس مباشرة التقت على الهضبة نفسها أفواج الفتح القادمة من ثلاث جهات — كيسادا وبنالكاثار والقائد الألماني فيدرمان — واتفقوا على أن تُحل دعاواهم في إسبانيا. وصارت المدينة عاصمة مملكة غرناطة الجديدة.", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["تأسيس سان خوان دي لا فرونتيرا دي واماننغا — قفل طريق ليما-كوسكو", "3f1cfdbf"], "d": ["كانت المقاومة التي قادها مانكو إنكا من فيلكابامبا تقطع الطريق بين ليما وكوسكو. فأسّس فرانسيسكو بيثارو لتأمين هذا الطريق سان خوان دي لا فرونتيرا دي واماننغا في منتصف المسافة بين العاصمتين؛ واسم البلدة «فرونتيرا» (الثغر) يقول غرض التأسيس مباشرة.", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["إعادة تأسيس تونخا مدينةً إسبانية", "c3a12867"], "d": ["بعد عودة كيسادا إلى إسبانيا أعاد غونزالو سواريث رندون تأسيس مدينة تونخا في موضع هونزا، مركز الزاكي، على النظام الإسباني. وبذلك ارتبط النصف الشمالي من بلاد المويسكا، مثل بوغوتا، بنظام بلدي دائم ونظام الإنكوميندا.", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1540-10-04:0":{"b": ["تأسيس سان فرانسيسكو دي كامبيتشي — المحاولة الثالثة والدائمة لفتح يوكاتان", "62af9901"], "d": ["بعد حملتين فاشلتين للاستيلاء على يوكاتان أسّس فرانسيسكو دي مونتيخو (الابن) بلدة سان فرانسيسكو دي كامبيتشي في موضع مدينة المايا كان بيتش. وصار هذا الميناء قاعدة إمداد للقوات التي ستزحف إلى داخل شبه الجزيرة، ونقطة انطلاق الحملة التي انتهت بتأسيس ميريدا بعد سنتين.", "079bb50a"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["تأسيس سانتياغو ديل نويڤو إكستريمو — بدء فتح تشيلي", "04cd7c3b"], "d": ["أسّس بيدرو دي ڤالديڤيا، الذي زحف جنوبًا من بيرو، سانتياغو ديل نويڤو إكستريمو في وادي مابوتشو. وأُحرقت البلدة في أيلول/سبتمبر من السنة نفسها بهجوم السكان الأصليين بقيادة ميتشيمالونكو ثم أُعيد تأسيسها؛ ومع ذلك أُديرت منها الفتح الإسباني لتشيلي.", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1545-01-01:0":{"b": ["إمارة كوكوم في سوتوتا تدخل في السيادة الإسبانية", "db6a6487"], "d": ["قاومت سوتوتا، إحدى أقوى إمارات المايا في داخل يوكاتان، التقدم الإسباني زمنًا طويلًا تحت أسرة كوكوم. وفي السنوات التي تلت تأسيس ميريدا عام 1542 قبلت الإمارة السيادة الإسبانية؛ وبعد قمع التمرد الشرقي الكبير في 1546-47 صارت هذه التبعية دائمة.", "461a3b98"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["تأسيس ڤيّا دي أوروبيسا — استيطان وادي الحبوب الذي سيغذي بوتوسي", "d6821cbf"], "d": ["أُسّست ڤيّا دي أوروبيسا في وادي كوتشابامبا بأمر نائب الملك فرانسيسكو دي توليدو. ونُظمت أرض الوادي الخصبة منطقة حبوب تغذي القوى العاملة الكثيرة في مناجم فضة بوتوسي؛ وصارت البلدة مخزن غلال بيرو العليا الاستعمارية.", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["سقوط فيلكابامبا — نهاية دولة الإنكا المستقلة", "31b5a95d"], "d": ["بعد سقوط كوسكو عام 1533 حافظ مانكو إنكا وخلفاؤه في جبال فيلكابامبا على دولة إنكا مستقلة دامت أربعين سنة. فاستولت الحملة التي نظمها نائب الملك فرانسيسكو دي توليدو على العاصمة المهجورة؛ وأُمسك توباك أمارو، آخر الحكام الفار، وأُحضر إلى كوسكو وأُعدم هناك. وبذلك انتهى الوجود السياسي لأسرة الإنكا ذات القرون الأربعة في عالم الأنديز.", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1596-09-20:0":{"b": ["تأسيس مونتيري — عاصمة نويڤو ليون", "ec6e44bc"], "d": ["أسّس دييغو دي مونتيمايور، بعد محاولتين فاشلتين، سيوداد ميتروبوليتانا دي نويسترا سينيورا دي مونتيري عند نبع سانتا لوسيا. وصارت هذه المستوطنة على الحدود الشمالية نقطة ارتكاز التوسع الدائم لإسبانيا الجديدة نحو الشمال الشرقي (نويڤو ليون).", "6bfa991f"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["تأسيس سان فرانسيسكو دي بورخا — السيادة الإسبانية في مايناس", "7ee32d19"], "d": ["أسّس دييغو باكا دي ڤيغا سان فرانسيسكو دي بورخا أسفل مضيق بونغو دي مانسيريتشي على نهر مارانيون، فربط منطقة مايناس بالإدارة الإسبانية. وصارت البلدة نقطة انطلاق شبكة البعثات اليسوعية التي ستستمر في أعالي الأمازون القرن التالي.", "83ae5281"]},
"OLAYLAR_AMERIKA0920:1718-05-01:0":{"b": ["تأسيس بعثة سان أنطونيو دي ڤاليرو — نواة تكساس الإسبانية", "ca9bd147"], "d": ["ردًّا على تسلل الفرنسيين من لويزيانا نحو الغرب قررت إسبانيا إقامة امتداد دائم في تكساس. فأسّس الأب أوليڤاريس بعثة سان أنطونيو دي ڤاليرو على ضفة نهر سان أنطونيو؛ وبعد بضعة أيام أقام الحاكم ألاركون بجانبها حصن سان أنطونيو دي بيخار. وسيُعرف مبنى البعثة فيما بعد باسم ألامو.", "74e48544"]},
"OLAYLAR_AMERIKA0920:1774-01-01:0":{"b": ["تأسيس ريفوخيو (ماتاموروس الحالية) — استيطان مصب ريو غراندي", "f3b86da7"], "d": ["ملأ برنامج الاستيطان في نويڤو سانتاندير الذي نفّذه خوسيه دي إسكاندون منذ عقد 1740 الحوض الأدنى لريو غراندي بالمزارع والبلدات. وأُسّست نويسترا سينيورا ديل ريفوخيو دي لوس إستيروس على الضفة الجنوبية للنهر إحدى آخر حلقات هذا البرنامج؛ وأخذت اسم ماتاموروس في القرن 19.", "913bb307"]},
"OLAYLAR_AMERIKA0920:1821-09-15:0":{"b": ["إعلان استقلال أمريكا الوسطى — القيادة العامة لغواتيمالا تنفصل عن إسبانيا", "f998089a"], "d": ["بعد خطة إيغوالا في المكسيك أعلن المجلس المنعقد في غواتيمالا استقلال القيادة العامة عن إسبانيا؛ وبقي القائد العام غابينو غاينثا على رأس الإدارة الانتقالية. وبذلك انتهت السيادة الإسبانية في أراضي غواتيمالا والسلفادور وهندوراس ونيكاراغوا وكوستاريكا الحالية. وبعد أن انضمت المنطقة زمنًا قصيرًا إلى الإمبراطورية المكسيكية أسست عام 1823 ولايات أمريكا الوسطى المتحدة.", "c4e39cd1"]},
"OLAYLAR_AMERIKA0920:1839-01-01:0":{"b": ["تأسيس نويڤا هلڤيتيا — المكسيك تفتح وادي ساكرامنتو للاستيطان", "067a1f2a"], "d": ["أسّس المهاجر السويسري جون سوتر، بإذن وامتياز أرض نالهما من السلطات المكسيكية، نويڤا هلڤيتيا عند ملتقى نهري ساكرامنتو وأمريكان. وصارت المزرعة المحصنة أقصى مخفر للمكسيك في داخل ألتا كاليفورنيا؛ وستتحول بالعثور على الذهب عام 1848 إلى مركز الهجرة إلى كاليفورنيا.", "1c5eab3d"]},
"OLAYLAR_EBUKIR0919:1798-08-01:0":{"b": ["معركة أبي قير البحرية (النيل) — تدمير أسطول نابليون", "be4ad8d8"], "d": ["بينما كان الأسطول الفرنسي الذي نقل جيش نابليون إلى مصر راسيًا في خليج أبي قير أدركه أسطول الأميرال الإنجليزي نلسون ودُمّر في معركة دامت ليلة؛ وانفجرت السفينة الرئيسة لوريان. وبذلك حرم نلسون جيش فرنسا البري في مصر من الدعم البحري: فلم يكن الجيش يستطيع أن يتلقى مددًا ولا أن يعود. وبعد خمسة أسابيع أعلنت الدولة العثمانية أيضًا الحرب على فرنسا.", "9f27937f"]},
"OLAYLAR_EBUKIR0919:1799-07-25:0":{"b": ["معركة أبي قير البرية — هزيمة كوسه مصطفى باشا", "35a695f3"], "d": ["هزم نابليون، العائد مهزومًا من أمام عكا، القوات العثمانية بقيادة كوسه مصطفى باشا في أبي قير، وآلت قلعة أبي قير إلى الفرنسيين. وسيكون هذا الساحل، الذي غرق عنده الأسطول الفرنسي قبل سنة، بعد سنتين المكان الذي نزل فيه الجيش البريطاني الجائي لإخراج الفرنسيين من مصر (8 آذار/مارس 1801).", "da0b6c57"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["استعادة أمير الأفلاق ميرتشا دوبروجة بعد هزيمة أنقرة — سيليستره وكوستنجة وبابا داغ وإسحاقجي", "5eaefc68"], "d": ["زعزعت هزيمة يلدرم بايزيد أمام تيمور في أنقرة السيادة العثمانية على ضفاف الدانوب. واستفاد فويفود الأفلاق ميرتشا من هذا الفراغ فدخل دوبروجة من جديد؛ وبقيت سيليستره وكوستنجة ومحيط بابا داغ وإسحاقجي على ضفة الدانوب في يده طوال سنوات الفترة. ودعم ميرتشا موسى جلبي ضد جلبي محمد. وأمسك بسيليستره حتى وفاته عام 1418.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["انتقال بابا داغ ومحيطها إلى العثمانيين — هزيمة ميرتشا وابنه ميخائيل", "bfda2c60"], "d": ["أدخل جلبي محمد بابا داغ ومحيطها في شمال دوبروجة في السيادة العثمانية بعد هزيمة فويفود الأفلاق ميرتشا وابنه ميخائيل. وكانت بابا داغ بلدة تحمل اسم صالتق بابا وأُسست باستيطان تركماني في القرن 13. أما سيليستره وكوستنجة وقلاع دوبروجة الأخرى حولها فبقيت في الأفلاق حتى 1419؛ أي إن بابا داغ تظهر ثلاث سنوات جزيرة (إكسكلاف) منقطعة عن الأراضي العثمانية.", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["استرداد سيليستره ودوبروجة — بعد وفاة ميرتشا", "73eb6ae9"], "d": ["أتاحت الفوضى التي نشبت في الأفلاق بعد وفاة فويفود الأفلاق ميرتشا عام 1418 للسلطان جلبي محمد فرصة استرداد سيليستره ودوبروجة. وفي ربيع 1419 دخلت سيليستره وكوستنجة ومعظم دوبروجة من جديد في الإدارة العثمانية؛ وأُصلحت قلعتا إنيسالا (يني سالا) وإسحاقجي وجُعلتا قلعتي حدود (ثغور)؛ وبقيت دوبروجة في يد العثمانيين بعد ذلك حتى 1878.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["إغلاق الدانوب الأدنى — ضم يركوكي وتورنو وأورشوفا", "331a0b68"], "d": ["أثمرت عام 1420 مبادرة جلبي محمد لضبط خط الدانوب بعد انتهاء عهد الفترة. ففي هذه السنة انتقلت إلى يد العثمانيين قلعة يركوكي التي بناها فويفود الأفلاق قوجه ميرتشا على أرضه وغطى نفقاتها ببيع الملح (وكانت دوبروجة قد استُردت قبل سنة، في ربيع 1419 — TDV سيليستره)، وضُمت تورنو (الكولة/هولوفنيك) وأورشوفا — باسمها اللاحق فتح الإسلام — على الضفة اليمنى للدانوب. وبذلك صار ضفتا النهر معًا تحت السيطرة. وأهمية يركوكي من جغرافيتها: فهي قلعة عثمانية أُقيمت على الضفة اليسرى للدانوب، أي ضفة الأفلاق، وتمسك مع روسجق على الضفة المقابلة بطرفي المعبر نفسه. وتكتب الوثائق العثمانية هذه الثنائية صراحةً — فيقال لروسجق «يركوكي هذه الضفة» ولجورجيو «يركوكي الضفة الأخرى». وستستردها الأفلاق عام 1427، وتدخل من جديد في السيطرة العثمانية عام 1449، وسيُلحق قضاء يركوكي بسنجق نيكوبول فيصير جزيرة تُدار مباشرة داخل الفويفودية. وهنا يبدأ جواب سبب كون ضفة الدانوب من الأفلاق بلون داكن في الخريطة.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["دخول منطقة توبليتسا (كورشونلو، أوركوب) في السيادة العثمانية", "e22e690d"], "d": ["يُرجَّح أن السيادة العثمانية انتقلت إلى منطقة دوبوتشيتسا وتوبليتسا (محيط ليسكوفاتس وكورشونلو وأوركوب) أثناء خطبة مراد الثاني لمارا برانكوفيتش؛ ويُظهر سجل التحرير 1445-1447 أن المنطقة أُعطيت للسباهية العثمانيين تيمارًا. وفي الخريطة تكون كورشونلو وأوركوب في الإدارة العثمانية منذ هذه السنة.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["ضم سهل سراي — إقامة الطرف العثماني داخل البوسنة", "be5c0f00"], "d": ["بعد أن فُرض الخراج على ملوك البوسنة في 1428-1429 بدأ العثمانيون يستقرون استقرارًا دائمًا نحو داخل المملكة. وأُخذت بلدة هوديديد بين 1428 و1435؛ وفي 852 (1448) دخلت ولاية هوديديد مع سهل سراي كليًا في الإدارة العثمانية. وهي منطقة طرفية أُقيمت في وسط المملكة قبل فتح البوسنة بخمس عشرة سنة، وأدارها عيسى بك أمير أسكوب الذي كان يحمل لقب فويفود — وكانت المنطقة تحت رقابة مزدوجة لأن حولها كان لا يزال أمراء بوسنيون تابعون للعثمانيين. وولدت المدينة نفسها في هذه الفترة: فقبل 1462 أسس إسحاق بك أو ابنه عيسى بك أول حي مسلم، وبُني في 862 (1458) جامع هونكار باسم الفاتح، وعُمّرت أراضي قرية برودتس الزراعية فنشأت بلدة سراي. وقضى الفتح في 1463 على مملكة البوسنة؛ أما سهل سراي فكان في ذلك التاريخ أرضًا عثمانية منذ خمس عشرة سنة.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["انضمام بودغوريتسا إلى الأراضي العثمانية — إخضاع سهل زيتا", "46e401c5"], "d": ["تُذكر البلدة، المقامة في السهل الذي تلتقي فيه مياه موراتشا وريبنيتسا على بعد عشرين كيلومترًا شمال بحيرة إشقودرة، في المصادر لأول مرة باسم ريبنيتسا عام 1216 وباسم بودغوريتسا عام 1326. وانضمت إلى الأراضي العثمانية عام 1457، وبذلك خرجت السيطرة على سهل زيتا من يد أسرتي بالشيتش وتشرنوييفيتش. وأقام السلطان محمد الفاتح بين عامي 1474 و1478 قلعة وجامعًا على الصخور الوعرة عند ملتقى النهرين؛ وبعد فتح إشقودرة عام 1479 ارتبطت المنطقة بسنجق إشقودرة المؤسس حديثًا. وبلغت بودغوريتسا، وهي بلدة مسيحية من أربعين بيتًا في تحرير 1485، 800 شخص وحامية من اثنين وثلاثين رجلًا بإمرة دزدار داخل القلعة في 1529-30، و322 بيتًا في 1582. وأحصى أوليا جلبي عام 1662 في قلعة الفاتح ثلاثمئة بيت ومخازن وجبخانات وسبعمئة حارس. وتُظهر هذه السجلات الفرق بين سهل زيتا وجبلها: فالسهل قضاء عثماني معدود ومُخضع للضريبة وذو حامية — بينما ستضطر المدينة في القرن 18 إلى التحصن بست طوابي وأسوار ذات ثلاثة أبواب لدرء غارات العشائر في جبال الجبل الأسود. وانتقلت بودغوريتسا في أواخر حرب 1876-1878 إلى الجبل الأسود وبقيت هناك بمعاهدة برلين.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["أخذ فوتشا — فتح المدخل الأول إلى دوقية الهرسك", "f098a9e6"], "d": ["بعد القضاء على مملكة البوسنة عام 1463 جاء الدور على أراضي ستيفان فوكتشيتش كوساتشا الذي انفصل عن المملكة وأسس دوقيته. ودخلت فوتشا، في وادي درينا عند ملتقى طريق التجارة الذي يربط إسطنبول بدوبروفنيك، في الإدارة العثمانية عام 1465. وأُدركت أهمية المدينة فورًا: ففي 1470 جُعلت مركز سنجق الهرسك المؤسس حديثًا — أي إن النواة الإدارية للهرسك أُقيمت في فوتشا قبل أن تسقط الدوقية نفسها. وسيستمر ضم الدوقية كلها حتى 1483. وتطورت فوتشا بعد ذلك مركزًا للتجارة والإدارة بفضل مناخها المناسب وموقعها عند ملتقى الطرق. وفي الخريطة هذا التاريخ هو اليوم الذي بدأت فيه الموجة الثانية نحو الجنوب بعد فتح البوسنة.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["الضم النهائي لليفنو وغرب البوسنة — إقامة الحدود مع البندقية", "c14d4283"], "d": ["كانت القلعة على الهضبة المشرفة على سهل ليفنو في يد ستيفان فوكتشيتش كوساتشا، مؤسس دوقية الهرسك، بين 1448 و1454. وقد احتلتها القوات العثمانية لفترة قصيرة في حملة البوسنة عام 1463، لكنها استُردت في السنة نفسها؛ وفي 1466 كان حاكم المدينة إيفانيش فلاتكوفيتش. وبحسب تعبير TDV، حدثت السيادة العثمانية النهائية على الأرجح في 1468-1469، ويسجل تحرير 1485 ليفنو أرضًا عثمانية. وهذا إغلاق الطرف الغربي لفتح البوسنة: فقد صارت ليفنو بلدة حدودية خطرة تجاور، عبر السهل المنبسط، أراضي البندقية التي لا تبعد سوى ستة وثلاثين كيلومترًا، وحافظت على هذا الموقع حتى أخذ والي البوسنة غازي خسرو بك قلاع البندقية في 1521-1522.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["فقدان بوغوردلن للمجر — أول ثغرة في خط سافا", "129fe8f2"], "d": ["شُيّد في عام 1471 حصن من الخشب والتراب في الموقع الذي انتقل إلى العثمانيين في عهد السلطان محمد الفاتح والذي كان يُعرف من قبل باسم زاسلون. ولأنه كان في نقطة تهدد بلغراد، ومنها كان يسهل الإغارة على المناطق الجنوبية من المجر والنمسا، فقد أخذت القلعة اسمها من هذه الوظيفة أيضًا — فبوغوردلن تعني «الحصن الضارب من الجنب». وحاصر الملك المجري ماتياس كورفينوس القلعة في أواخر عام 1475 وأخذها في فبراير 1476. والملحمة المجرية «Szabács viadala» التي تروي الحصار هي من أطول نصوص الشعر التاريخي المجري في القرن 15 التي بلغتنا. وأقام المجريون في المنطقة بانية وأعادوا تحصين القلعة بالحجر وجعلوها حلقة في سلسلة حصون الثغور. وحاول العثمانيون استردادها عام 1492 فلم ينجحوا؛ وبقيت القلعة خمسًا وأربعين سنة في يد المجر.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["فتح الجزر الأيونية — نهاية دوقية توكو: آيا مافرا وكيفالونيا وزاكينثوس وإيثاكي", "07b27251"], "d": ["كانت معاهدة إسطنبول الموقعة مع البندقية في يناير من العام نفسه قد تركت إشقودرة والساحل الألباني للعثمانيين؛ أما الجزر الأيونية فلم تكن في إدارة البندقية بل في إدارة أسرة توكو التي تمسك بكونتية كيفالونيا وزاكينثوس، وأُخذت بعملية منفصلة. ووفقًا لمادة آيا مافرا في TDV، كان الدوق الأخير ليوناردو توكو قد حافظ أولًا على ولائه بزواجه من ميليكا برانكوفيتش قريبة الفاتح، ولما ماتت زوجته عام 1464 أغضب السلطان بزواجه عام 1477 من فرانشيسكا مارزانو من أسرة نابولي. وبعد سنتين استولى الأسطول بقيادة بك أفلونيا كدك أحمد باشا على آيا مافرا مع كيفالونيا في الجنوب؛ وفرّ ليوناردو وفرانشيسكا إلى إيطاليا. وتسجل مادة كدك أحمد باشا أن زاكينثوس (زانطة) أُخذت في الحملة نفسها؛ ودخلت إيثاكي التابعة لكونتية كيفالونيا في الإدارة العثمانية في هذا العهد كذلك. وبذلك أُخضع الطريق البحري الممتد من مدخل الأدرياتيك إلى المورة إخضاعًا تامًا. وستُترك زاكينثوس للبندقية بعد ثلاث سنوات، وستُفقد كيفالونيا وإيثاكي عام 1500، ولن تبقى في يد العثمانيين مئتي سنة إلا آيا مافرا.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["تبعية زيتا آل تشرنوييفيتش وجعل تسيتينيه مركزًا", "59d20267"], "d": ["ببقاء إشقودرة في يد العثمانيين عام 1479 سقطت منطقة زيتا الجبلية، حديقتها الخلفية، داخل حدود الإمبراطورية. وقد اعترفت أسرة تشرنوييفيتش، التي تمسك بالمنطقة، بسلطنة بايزيد الثاني الذي تولى العرش بعد وفاة الفاتح، وقُيّدت بالخراج وبقيت حرة في شؤونها الداخلية؛ ونقل إيفان تشرنوييفيتش مركزه من السهل إلى تسيتينيه عند سفح جبل لوفتشن وأسس المدينة. وبعد سنتين صار الدير الذي بناه هناك المركز الديني للمنطقة. وهكذا يظهر الجبل الأسود في الخريطة لا أرضًا عثمانية مباشرة بل منطقة تابعة بلون فاتح. وتذكر مادة الجبل الأسود في TDV الأسرة الحاكمة وأسقفية تسيتينيه، وتكتب أن السيادة تحولت عام 1514 على يد إسكندر بك (من سلالة تشرنوييفيتش، ممن نشأ في القصر العثماني) إلى سنجق منفصل؛ أما سنة 1482 فلا ترد في TDV، وهي التاريخ الذي تعطيه الكتابة التاريخية للجبل الأسود. وبسبب قسوة الجغرافيا لم تعمل الإدارة هنا قط بإحكام كما في السهول.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["فتح قلعة كيليا — قفل مصب الدانوب", "ef4eca73"], "d": ["كانت البغدان منذ سبتمبر 1455 فويفودية تابعة تدفع خراجًا قدره ألفا ذهب سنويًا، لكن ميناءيها المنفتحين على البحر الأسود كانا لا يزالان في يد الفويفود، وكانت التجارة الآتية من الدانوب تمر منهما. وقام بايزيد الثاني بأول حملة كبرى في سلطنته على هذين الميناءين. وأُجبر قائد قلعة كيليا، التي قُصفت بالمدافع عشرة أيام ليلًا ونهارًا، على الاستسلام. وأُخذت القلعة في الإدارة العثمانية المباشرة وجُعلت سنجق بكلك؛ وفي النصف الثاني من القرن 16 أُقيمت قضاءً بسبب خطر القوزاق وربطت بسنجق آق كرمان التابع لبكلربكية الروملي. ومن هنا تظهر البغدان في الخريطة على درجتين: في الداخل تقف الفويفودية أرضًا تابعة بلون فاتح، أما الميناءان على الساحل فسنجق عثماني مباشر بلون داكن. وتسميهما مادة البغدان في TDV «مفاتيح البغدان وأبوابها» وتكتب أن المنطقة ارتبطت بالعثمانيين نهائيًا في زمن بايزيد الثاني.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["فتح آق كرمان — مصب الدنيستر وإغلاق باب البغدان على البحر الأسود", "7cb20feb"], "d": ["بعد عشرين يومًا من تسليم كيليا وصل الجيش أمام آق كرمان عند مصب الدنيستر، وأُخذت القلعة في 4 أغسطس. وكانت المدينة أنشط موانئ البغدان؛ وكان الفويفود بترو الثالث لما اعترف بالسيادة العثمانية عام 1455 في عهد الفاتح قد أُذن لتجار آق كرمان بالتجارة، والآن صار الميناء ملكًا للدولة مباشرة. وجُعلت آق كرمان بعد الفتح سنجقًا تابعًا لبكلربكية الروملي، وضُمت عام 1593 إلى إيالة أوزي المؤسسة حديثًا. وبذلك بدأت القشرة الخارجية للبغدان، المحاطة بخوتين من الشمال وبكيليا وآق كرمان من الجنوب، تدخل في السيطرة العثمانية المباشرة؛ وبقيت الفويفودية حرة في شؤونها الداخلية لكن لم يبق لها منفذ إلى البحر. وليس في الخريطة منطقة فارغة بينهما — فالسناجق المينائية بلون داكن وأرض الفويفودية بلون فاتح تتلامسان؛ وسهوب بوجاق بينهما ظلت حتى عام 1538 جزءًا من الفويفودية.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["تسليم إينه بختي — مدخل خليج كورنثة ينتزع من البندقية", "2cfe0777"], "d": ["كانت إينه بختي في يد البندقية منذ عام 1407 وتمسك بمدخل خليج كورنثة؛ وكانت كل السواحل داخل الخليج مرتبطة بمدى هذه القلعة. وفي حملة 1499 حوصرت القلعة برًا، وساعد الأسطول العثماني، الذي اشتبك مع الأسطول البندقي قبالة إينه بختي، قوات الحصار من البحر. وسلّم البنادقة في القلعة البلدة للعثمانيين في 26 أغسطس. وبقيت المدينة بعد ذلك مئة وثمانيًا وثمانين سنة في يد العثمانيين، وانتقلت من جديد إلى البندقية عام 1687 بفقدان المورة، واستُردت عام 1715. والمعركة البحرية في الصيف نفسه وهذا التسليم حدثان منفصلان: فقد جرى الاشتباك البحري عند الطرف الغربي للمورة في مياه سابينتسا-زونكيو؛ أما إينه بختي فسقطت بحصار بري عند مدخل خليج كورنثة.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["ضم بانية سريبرينيك — أول كسر للخط المجري في شمال البوسنة", "6d98c725"], "d": ["بعد سقوط مملكة البوسنة عام 1463 انتقل ماتياس كورفينوس إلى الهجوم المضاد وأقام في شمال المملكة بانيتين أوقفتا التقدم العثماني: يايتسه في الغرب وسريبرينيك في الشمال الشرقي. وكانتا خط الدفاع المتقدم للمجر في البوسنة، وتسدّان الممر بين سافا والبوسنة. وأُخذت بانية سريبرينيك عام 1512؛ فانهار بذلك الجناح الشرقي للخط وأمكن لسنجق زفورنيك أن يتوسع نحو الشمال. أما يايتسه في الجناح الغربي فستصمد ست عشرة سنة أخرى ولن تؤخذ إلا عام 1528 بعد موهاكس.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["فتح بوغوردلن — أول قلعة أخذها القانوني والمكان الذي اتُّخذ فيه قرار بلغراد", "85177a90"], "d": ["أخذت قوات بكلربك الروملي أحمد باشا، التي أُرسلت إلى المنطقة في حملة القانوني الأولى على المجر، القلعة في 7 يوليو 1521 بعد حصار شديد. وبوغوردلن هي أول قلعة فُتحت في سلطنة القانوني. ودخل السلطان القلعة بنفسه بعد الفتح وأمر بعمارة المدينة؛ واتُّخذت هنا أيضًا القرارات المتعلقة بفتح بلغراد — أي إن خطة بلغراد التي ستسقط في 29 أغسطس 1521 وُضعت في بوغوردلن. وبقيت القلعة بعد ذلك نحو مئتي سنة في يد العثمانيين؛ وتبعت أولًا الروملي، ومنذ 1580 إيالة البوسنة، ثم سمندرة لفترة قصيرة، وأخيرًا سنجق زفورنيك. وفي الخريطة هذا التاريخ هو اليوم الذي أُغلق فيه خط سافا لصالح العثمانيين.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["اندلاع ثورة الفويفوديات الثلاث — ترانسلفانيا تنضم إلى التحالف المقدس واعتقال الأمراء الموالين للعثمانيين", "68a33800"], "d": ["في السنة الثانية من الحرب الطويلة انفرط فجأة حزام التبعية العثماني في وسط أوروبا. فانضمت إلى التحالف المقدس، الذي تأسس برعاية البابا كلمنت الثامن، البغدان وترانسلفانيا في أواخر الصيف: إذ رسّم فويفود البغدان آرون فودا انضمامه إلى الجانب المسيحي بوثيقة في 16 أغسطس 1594، وكسر أمير ترانسلفانيا زيغمونت باتوري كذلك المعارضة في الداخل بتصفية الأمراء الموالين للعثمانيين المعارضين للحرب في 28 أغسطس 1594. وانضم فويفود الأفلاق ميخائيل الشجاع إلى التحالف في خريف العام نفسه. وهكذا انتقلت إلى الجانب المقابل دفعة واحدة، في الخريف نفسه، إماراتُ العثمانيين التابعة الثلاث شمال الدانوب — الفويفوديات الثلاث التي تدفع الخراج منذ مئة وخمسين سنة ويُصدّق على فويفودها في إسطنبول. وتأكد القرار باتفاقية وُقعت في براغ في 28 يناير 1595. وكانت هذه أشد هزة تعرض لها نظام الإدارة غير المباشرة العثماني في شمال البلقان؛ وسيُقمع التمرد لكن ولاء الإمارات الثلاث لن يعود في صلابته بين 1526 و1593.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["ثورة بوخارست والهجوم على قلاع الدانوب", "18971100"], "d": ["نُفّذ قرار التحالف المقدس بعد شهر بالدم: فقد أعمل ميخائيل الشجاع السيف في بوخارست في الحامية العثمانية الحارسة والدائنين الليفانتيين في المدينة. وامتدت الثورة في الشتاء نفسه إلى خط الدانوب؛ وهاجمت القوات الأفلاقية يركوكي وإبراييل وحيرسوفا وسيليستره، وفي جانب البغدان شن آرون فودا الهجوم نفسه على الحراس العثمانيين في بندر. واختيار المواضع المضروبة ليس مصادفة: فجميعها قلاع وأقضية على الدانوب تابعة للإدارة العثمانية المباشرة لا أرض الفويفودية — فقضاء يركوكي تابع لسنجق بكلك نيكوبول، وإبراييل تتبع الدولة مباشرة منذ 1538، وبندر تتبع سنجق بوجاق منذ 1538 أيضًا. أي إن التمرد لم يضرب الداخل التابع بل القشرة العثمانية المباشرة المحيطة به. ولم يكن ممكنًا ربط مثلث ترانسلفانيا-الأفلاق-البغدان بالجبهة الهابسبورغية قبل ثقب هذه القشرة.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["معركة كالوغران — حملة خوجه سنان باشا على الأفلاق", "201210a1"], "d": ["إثر خروج الفويفوديات الثلاث دفعة واحدة من اليد، عبر الصدر الأعظم خوجه سنان باشا الدانوب بجيش كبير وسار لإعادة الأفلاق إلى الطاعة. ولما كان ميخائيل الشجاع يعلم أنه لا يستطيع المقاومة في معركة مكشوفة، انتظر الجيش في كالوغران عند المعبر المستنقعي لنهر نياجلوف، وباغت القوات التي انحشرت في الأرض الضيقة. وبعد المباغتة تراجع، إذ لم يستطع الصمود أمام الجيش العثماني المتفوق عددًا، شمالًا إلى الجبال؛ واحتل سنان باشا بوخارست وترغوفيشته وحاول ربط الأفلاق بالإدارة المباشرة. ولذلك لم تكن كالوغران هزيمة للعثمانيين بل مباغتة أخّرت إتمام الحملة؛ لكن احتفاظ ميخائيل بجيشه مكّنه من الانتقال إلى هجوم مضاد بمساعدة آتية من ترانسلفانيا بعد بضعة أسابيع.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["الانسحاب من الأفلاق وغارة يركوكي — إخفاق حملة القمع", "118806e1"], "d": ["إثر الهجوم المضاد لميخائيل الشجاع المتحد مع قوات أمير ترانسلفانيا، أخلى سنان باشا ترغوفيشته وبوخارست وتراجع إلى الدانوب. وحدثت أغلى لحظة في الانسحاب عند رأس المعبر: ففي أكتوبر 1595 تعرضت الأكنجية التي كانت تتعقب الجيش العائد من الأفلاق لمباغتة ميخائيل في يركوكي. وانتهت الحملة دون أن تبلغ هدف ربط الأفلاق بالإدارة المباشرة، وبقيت الفويفودية خارجة عن اليد فعليًا. ولم يمكن إصلاح السلطة العثمانية في هذا المثلث إلا على مدى سنوات وقطعة قطعة؛ وسينتظر رجوع ترانسلفانيا إلى الطاعة ثورة بوكسكاي عام 1604، وإغلاق الجبهة كليًا معاهدة زيتفاتوروك عام 1606.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["اقتطاع خوتين من البغدان — سنجق عثماني مباشر في وسط الفويفودية", "947517cb"], "d": ["أظهر انحياز فويفود البغدان ديميتري كانتيمير إلى الجانب الروسي في حملة بروت أن الحد الشمالي للفويفودية لم يعد ممكنًا تركه للفويفود. فأُخذت خوتين من البغدان بعد 1711 وأُدخلت في الإدارة العثمانية المباشرة؛ ومُنحت أولًا صفة ناحية ثم صفة سنجق. وبعد الاحتلال الروسي المؤقت عام 1713 رُممت القلعة ووُسّعت تحت إشراف وفد فني عثماني وفرنسي أُرسل من إسطنبول، وصارت أقوى حصن عثماني شمال الدانوب. وخروج خوتين في الخريطة بعد هذا التاريخ من لون الفويفودية التابعة إلى اللون العثماني المباشر، ووقوفها كجزيرة وحيدة في وسط البغدان التابعة، هو مقابل هذا الفصل الإداري — وليس خطأ في الرسم. وكان البناء نفسه موجودًا في بوجاق منذ 1538 وفي كيليا وآق كرمان منذ 1484: فالفويفودية حرة في شؤونها الداخلية وقلاع الحدود للدولة.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["الاحتلال النمساوي الثاني لبوغوردلن — فتح جبهة سافا", "063b3ad0"], "d": ["بعد دخول النمسا الحرب إلى جانب روسيا في 9 فبراير 1788 صار خط سافا من جديد جبهة، وانتقلت بوغوردلن إلى السيادة النمساوية في 24 أبريل 1788. وكانت القلعة قد تُركت للنمسا قبل ذلك دون قتال في 17 أغسطس 1717 وبقيت في يدها حتى معاهدة بلغراد (1739)؛ وفي ذلك العهد تناقص عدد سكانها إلى حد أنه لم يبق في المدينة سوى أربعة وثلاثين بيتًا مسيحيًا ولم يبق أي مسلم. وفي العهد العثماني بين 1739 و1788 ارتفع عدد السكان من جديد إلى 1500-2000. وسينتهي الاحتلال الثاني بمعاهدة سيستوف (4 أغسطس 1791) وستُعاد القلعة إلى العثمانيين.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["تسليم بوغوردلن لقره جورج — أول قلعة في الثورة الصربية الأولى", "5c913eb4"], "d": ["خلال الثورة الصربية الأولى، التي بدأت عام 1804 رد فعل على ضغط الدايات واليماكين في بلغراد ثم اكتسبت طابعًا قوميًا، سُلّمت قلعة بوغوردلن إلى قره جورج في 26 يناير 1806. وهذه القلعة على نهر سافا هي أول حصن عثماني كبير يستولي عليه الثوار، وتنبئ بسقوط بلغراد. ولما قُمع التمرد عام 1813 واستُعيدت بلغراد عادت القلعة إلى الإدارة العثمانية؛ غير أنها عُرّفت، بشرط الحامية في فرمان 1830، مع بلغراد وسمندرة وفتح الإسلام، إحدى القلاع الأربع التي يبقى فيها جنود عثمانيون داخل صربيا ذات الحكم الذاتي، وبقيت على هذه الحال حتى سُحبت حاميتها عام 1867.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["بقاء إزدين (لاميا) داخل حدود اليونان — خط أرتا-فولوس", "930f63b8"], "d": ["رُسم الحد الشمالي للدولة اليونانية المستقلة عام 1832 على الخط الممتد من خليج أرتا إلى خليج فولوس. وإزدين، التي كانت مركز قضاء تابع لسنجق إغريبوز في العهد العثماني (1424-1832)، انتقلت إلى اليونان لأنها بقيت جنوب هذا الخط؛ وبقي سائر تساليا (يني شهر وترحالة) في يد العثمانيين حتى عام 1881.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["إعلان روسيا الحرب — بدء حرب الثلاثة والتسعين", "ac548ab8"], "d": ["كان قمع الثورة البلغارية عام 1876 قد أثار سخطًا كبيرًا في الرأي العام الأوروبي، واستغلته روسيا إلى آخر حد لعزل الباب العالي. ولما رفضت الدولة العثمانية اقتراح مؤتمر إسطنبول (الترسانة) بتقسيم بلغاريا إلى إيالتين ذواتي حكم ذاتي ثم بروتوكول لندن المؤرخ في 31 مارس 1877، أعلنت روسيا الحرب في 24 أبريل 1877 ودخل جيشها أراضي إمارة رومانيا التي كسبتها إلى جانبها (وتُظهر الخريطة الأفلاق-البغدان منذ هذه اللحظة حتى هدنة أدرنة بغطاء مخطط للتقدم الروسي). وسميت الحرب حرب الثلاثة والتسعين لأنها وقعت في السنة 1293 بالتقويم الرومي. وسارت العمليات على جبهتين، الدانوب وشرق الأناضول: ففي الدانوب عدّ الجيش العثماني المؤلف من 180.000 رجل الضفة اليسرى للنهر خط الدفاع الأول وجبال البلقان خط الدفاع الثاني؛ وفي الشرق تمركز 55.000 جندي بقيادة أحمد مختار باشا بين أرداهان ودوغو بايزيد. وهذه الحرب في الخريطة هي الحدث الذي بدأ انهيار الروملي العثماني — فحدود بلغاريا وصربيا والجبل الأسود ورومانيا الحالية كلها نتاج هذه الأشهر الخمسة عشر.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["إعلان رومانيا استقلالها — نهاية تبعية الأفلاق والبغدان", "bdd164b3"], "d": ["بعد أسبوعين من إعلان حرب 93، أعلنت إمارة رومانيا استقلالها ودخلت الحرب إلى جانب روسيا؛ وكان لدورها في حصار بلفن أثر حاسم في الهزيمة العثمانية. وبذلك انتهت فعليًا تبعية الأفلاق والبغدان التي دامت أكثر من أربعمئة سنة؛ ونال الاستقلال اعترافًا دوليًا في مؤتمر برلين (1878). وتعرض الخريطة رومانيا منذ هذا التاريخ دولة مستقلة بلونها الخاص لا تابعة.", "02d51dee"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["عبور الجيش الروسي الدانوب — سقوط سيستوف وترنوفو", "811367b1"], "d": ["تقدم الروس، الذين دخلوا أراضي رومانيا بنشوب الحرب وكسبوا هذه الإمارة إلى جانبهم، على ذراعين، إحداهما نحو دوبروجة والأخرى نحو بوخارست. وعُبر الدانوب بين روسجق ونيكوبول، وأُخذت سيستوف في 27 يونيو وترنوفو، العاصمة البلغارية القديمة، في 1 يوليو. ولما لم يُعتنَ بإخلاء نيكوبول رغم الأمر به، استسلمت بعد مقاومة فترة. وأدى اختراق خط الدفاع الأول في أسبوع إلى ذعر كبير في إسطنبول؛ وانتشرت حتى أخبار عن نقل مركز السلطنة إلى بورصة، وسُلّمت إدارة الحرب إلى مجلس عسكري أُقيم في العاصمة.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["إخلاء ممر شيبكا — اختراق خط البلقان", "1f45e50a"], "d": ["قاومت القوات العثمانية في شيبكا، أكثر ممرات جبال البلقان استراتيجية، الهجمات الروسية بشدة؛ لكنها لما اقتنعت بأنها ستُهزم أخلت الممر سرًا في 19 يوليو. وبذلك انفتح خط الدفاع الثاني أيضًا، وأخذ الجنرال غوركو ستارا زاغورا في 22 يوليو. ومع أن سليمان باشا الذي وصل من جهة الجبل الأسود هزم غوركو واستعاد الأماكن المحتلة جنوب البلقان، فإنه لم يستطع استرداد شيبكا رغم هجمات دامت أشهرًا منذ 21 أغسطس. وفي الخريطة هذا هو عدم إمكان إعادة بناء تكامل الدفاع بين شمال سلسلة البلقان وجنوبها: فالنضال على جبهة الدانوب سيعقد بعد ذلك في بلفن.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["احتلال الجيش الروسي لوفتشا", "70e54611"], "d": ["كانت لوفتشا قد احتلها الروس في 5 يونيو 1877 في حرب 93، وصد الجيش العثماني بقيادة رفعت باشا الروس في 15 يونيو؛ وتركها العثمانيون في 23 أغسطس فدخلت من جديد في الاحتلال الروسي. وتعرض الخريطة لوفتشا من هذا اليوم حتى معاهدة برلين تحت الاحتلال الروسي (مخططة)؛ وتبقى قانونيًا أرضًا عثمانية.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["سقوط قارص — انحلال الجبهة الشرقية وطوابي العزيزية", "53fc3bf5"], "d": ["كان الروس الذين تقدموا في شرق الأناضول من ثلاثة أذرع نحو قارص ودوغو بايزيد وأرداهان قد أخذوا دوغو بايزيد في 30 أبريل ودخلوا أرداهان، لكنهم هُزموا في 15 يوليو وهم يزحفون على أرضروم وطُردوا إلى ما وراء الحدود. وانقلب هذا النجاح الذي أكسب أحمد مختار باشا لقب «الغازي» في أغسطس بعودة الجنرال لازاروف إلى الهجوم، وسقطت قارص في 18 نوفمبر. وأبدت القوات العثمانية، التي انسحبت إلى أرضروم لدفاع أنسب، مقاومة كبيرة في طوابي العزيزية بتشجيع نينه خاتون للأهالي. وستُترك قارص وأرداهان وباطوم لروسيا بعد ثمانية أشهر في برلين مقابل جزء من تعويض الحرب.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["بدء حرب البلقان الأولى — إعلان الجبل الأسود الحرب", "c0c2697e"], "d": ["كانت الدول البلقانية، بعد أن حلّ الاتحاد والترقي مسألة الكنائس بقانون 3 يوليو 1911 ورفع أكبر عقبة بينها، قد وقّعت طوال عام 1912 اتفاقيات تحالف فيما بينها بتحريض من روسيا (في 13 مارس بين بلغاريا واليونان، وفي أغسطس بين الجبل الأسود وبلغاريا، وفي 6 أكتوبر بين الجبل الأسود وصربيا). ولم يفطن الباب العالي لذلك؛ بل سرّح 120 طابورًا مدربًا في الروملي واثقًا بضمان روسيا. وقدمت الدول الأربع مذكرة مشتركة في 3 أكتوبر تطلب الحكم الذاتي لمقدونيا وألبانيا وكريت؛ ولما لم تتلق ردًا بدأت العمليات بإعلان الجبل الأسود الحرب في 8 أكتوبر 1912. وفي 13 أكتوبر سُلّمت جوازات سفر سفيري صربيا وبلغاريا، وفي اليوم التالي أعلنت هاتان الدولتان ثم اليونان الحرب. ولعبت الخلافات السياسية داخل الجيش أثناء الحرب دورًا كبيرًا في الهزيمة.", "f008aef9"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["هزيمة مفرزة كرجالي في رودوب وسقوط كرجالي", "8cf59b7f"], "d": ["بعد إعلان بلغاريا الحرب، هزمت القوات البلغارية النازلة من رودوب مفرزة كرجالي بقيادة محمد ياور باشا ودخلت كرجالي. وتراجعت المفرزة المهزومة نحو كومولجينه؛ وخرج القسم الشرقي من رودوب من اليد في الأسبوع الأول من الحرب.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["هزيمة جيش الشرق والانسحاب إلى خط تشاتالجا — فقدان كومانوفو وسالونيك", "cf95591a"], "d": ["هُزم جيش الشرق العثماني في 23 أكتوبر 1912 أمام الجيش البلغاري الذي يفوقه ثلاث مرات عددًا، وتراجع إلى خط تشاتالجا الذي يبعد ثلاثين كيلومترًا غرب إسطنبول؛ ووقعت العاصمة تحت تهديد مباشر في الشهر الأول من الحرب. وفي الأيام نفسها هُزم جيش الغرب أمام الصرب في كومانوفو في 23-24 أكتوبر، واستسلم تحسين باشا بجيشه المؤلف من 35.000 رجل لليونانيين في سالونيك. وعلى إثر هذه الهزائم استقالت وزارة الغازي أحمد مختار باشا في 29 أكتوبر؛ ونُقل عبد الحميد الثاني الذي كان يعيش حياة المنفى في سالونيك إلى إسطنبول في 1 نوفمبر. وصمد خط تشاتالجا حتى نهاية الحرب — وانكمشت جغرافيا الروملي العثمانية التي دامت خمسمئة سنة إلى هذا الشريط الضيق في بضعة أسابيع.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["دخول الأمير ألكسندر مركز سنجق يني بازار", "326d0616"], "d": ["استولت القوات الصربية على يني بازار في الأسبوع الأول من الحرب والتحقت بقوات الجبل الأسود القادمة من الغرب. وبذلك تحول سنجق يني بازار، الذي فصل بين صربيا والجبل الأسود مئة سنة، إلى جسر بين الحليفين.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["سقوط قرق كليسة عقب معركتها", "eda4c759"], "d": ["إثر هزيمة جيش الشرق في معركة قرق كليسة في تراقيا الشرقية، تُركت المدينة التي كان يدافع عنها كولمن عبد الله باشا للقوات البلغارية. ولم تُحرَّر المدينة من احتلال دام تسعة أشهر إلا في حرب البلقان الثانية، في 21 يوليو 1913.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["ترك أسكوب، مركز ولاية قوصوة، دون مقاومة", "455d9b71"], "d": ["بعد كارثة كومانوفو (23-24 أكتوبر) بقيت أسكوب، مركز ولاية قوصوة، دون دفاع. ولما لم يرد الأهالي قتالًا حول المدينة، دخلت مساء 26 أكتوبر القوات الصربية بقيادة الأمير ألكسندر، المدعوة عبر القناصل، دون مقاومة.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["فقدان كوبريلي (فيليس) على نهر فاردار", "73d20b7d"], "d": ["بعد يومين من سقوط أسكوب أخذ الجيش الصربي النازل جنوبًا على طول فاردار كوبريلي. وبذلك صار باب وادي فاردار المنفتح على سالونيك في يد الصرب.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["حوض بريغالنيتسا: دخول الجنرال ستيفانوفيتش إشتيب", "70a84256"], "d": ["أخذت القوات الصربية بقيادة الجنرال ستيفانوفيتش إشتيب دون أن تواجه مقاومة؛ ودخلت المدينة أولًا عصابات غير نظامية. وبعد كومانوفو انتقل حوض بريغالنيتسا في مقدونيا الشرقية إلى السيطرة الصربية.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["انتقال قرفرية إلى السيادة اليونانية بعد ممر ساراندابورو", "02a68e02"], "d": ["بعد أن تجاوز الجيش اليوناني الزاحف شمالًا من تساليا ممر ساراندابورو (قرق كجيت)، سيطر على قرفرية. وغادر جزء من السكان المسلمين في المدينة المنطقة في هذه الأثناء.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["فقدان فودينا على سكة حديد سالونيك-مناستر", "fc15b917"], "d": ["وقعت فودينا، الواقعة على سكة حديد سالونيك-مناستر، في يد الجيش اليوناني. وبالفصل القسري بين السكان السلافيين والأتراك تراجع عدد سكان المدينة تراجعًا شديدًا في وقت قصير.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["معركة يينجه — انتقال يينجه فاردار إلى اليونانيين", "8f6cb76e"], "d": ["هُزم الفيلق المركّب الثامن بقيادة حسن تحسين باشا أمام الجيش اليوناني في يينجه غرب سالونيك وتراجع إلى منطقة سالونيك. واحترق القسم الأكبر من البلدة أثناء المعركة؛ وانفتح الطريق إلى سالونيك أمام الجيش اليوناني.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["استسلام بريزرين جنوب غرب قوصوة", "bae6b1b9"], "d": ["استسلمت بريزرين، جنوب غرب قوصوة، للقوات الصربية. وسُجّل موقف القوات الداخلة المدينة من الأهالي المسلمين إحدى أقسى صفحات الحرب في قوصوة.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["العقيد ميتوف يعلن الأحكام العرفية في أستروميتسا", "bcad75cc"], "d": ["دخل العقيد البلغاري ميتوف أستروميتسا وأعلن الأحكام العرفية؛ وعند مغادرته في اليوم التالي ترك البلدة لقائمقام بلغاري وقائد صربي. وتبدّلت السيطرة على أستروميتسا بين الحلفاء طوال الحرب وضُمت إلى بلغاريا عام 1913.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["حسن تحسين باشا يترك سالونيك لليونانيين", "1738933c"], "d": ["ترك حسن تحسين باشا، الذي انسحب إلى سالونيك بعد هزيمة يينجه، المدينة لليونانيين بينما كان الجيش البلغاري يقترب من الشمال؛ ودخل الجيش اليوناني المدينة في ظهر 8 نوفمبر. وبذلك خرجت سالونيك، أكبر مدينة ميناء في الروملي العثماني ومهد الاتحاد والترقي، من اليد.", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["انفتاح كومولجينه، مركز تراقيا الغربية، أمام البلغار", "96eec25f"], "d": ["لما تراجعت مفرزة ياور باشا المنسحبة من كرجالي نحو فيرة، استسلمت كومولجينه للقوات البلغارية. وكان مركز تراقيا الغربية في مقدمة الأراضي التي ستُترك لبلغاريا في نهاية الحرب.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["دخول الصرب الواصلين إلى إلباسان دبرة في اليوم نفسه", "16720246"], "d": ["دخلت القوات الصربية الزاحفة غربًا من مناستر دبرة أيضًا في يوم وصولها إلى إلباسان، ونزلت نحو الأدرياتيك. وفي اليوم نفسه كان يُعلن في أفلونيا استقلال ألبانيا.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["احتلال تيمور بغداد للمرة الثانية — هدم أحياء بغداد العباسية", "04b68a24"], "d": ["أخذ تيمور بغداد مرتين بفاصل ثماني سنوات. ولم تتضرر المدينة كثيرًا في الاحتلال الأول عام 1393؛ أما الثاني عام 1401 فيُعدّ الضربة الثقيلة الثانية للحياة الثقافية في بغداد — فقد أُعمل السيف في الأهالي ودُمّر معظم الأحياء والأبنية الباقية من العهد العباسي. وعاد الحاكم الجلائري أحمد إلى المدينة عام 1405 وحاول إصلاح الأسوار والأسواق المهدومة لكنه لم يجد الوقت؛ وانتقلت بغداد عام 1410 إلى أيدي التركمان القره قويونلو. ويُعدّ هذان الاحتلالان من أوضح الخطوات التي تُظهر مبلغ اقتراب تيمور من الحدود العثمانية والمملوكية في الطريق إلى معركة أنقرة.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["عودة جنيد بك إلى رأس آيدين إيلي — الآيدينيون من جديد مستقلون", "63281658"], "d": ["كان جلبي محمد قد أخذ إزمير في 1414-15 وأرسل جنيد بك إلى سنجق بكلك نيكوبول فربط آيدين إيلي بالإدارة العثمانية. وبعد وفاة جلبي محمد ظهر جنيد على المسرح من جديد إلى جانب مصطفى جلبي، الذي قدمه البيزنطيون مدعيًا للعرش، بل شغل منصب الوزارة عنده. وفصله مراد الثاني عن هذا التحالف بوعده بإعادة إمارته القديمة؛ فعاد جنيد إلى إزمير واستولى على آياصولوق وقتل الآيديني مصطفى بك وصار على رأس الإمارة. وهكذا ولدت آيدين إيلي من رحم أزمة مصطفى المزيف خارجةً عن الإدارة العثمانية.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["إعدام جنيد بك وأسرته — نهاية إمارة الآيدينيين", "efa684ba"], "d": ["لما أثار جنيد بك، الذي عاد فسيطر على آيدين إيلي، أمراء الأناضول وسعى إلى الاتصال بالبندقية، أرسل مراد الثاني بكلربك الأناضول حمزة بك عليه. وانسحب جنيد، بعد أن هُزم ابنه قرد حسن قرب أقحصار وأُسر، إلى إبسيلي قبالة جزيرة ساموس، ولما لم تصله المساعدة التي كان ينتظرها من القره مان أوغلو وحاصره الجنويون الذين تحركوا مع العثمانيين من البحر اضطر إلى الاستسلام؛ وأُزيل مع كل ذريته. وهكذا دخلت أراضي الآيدينيين كلها في الإدارة العثمانية.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["انتقال أرضروم وحوض وان إلى الصفويين — انهيار الجناح الشمالي للآق قويونلو", "b418875f"], "d": ["تقدم الشاه إسماعيل، الذي هزم ألوند بك في شرور ودخل تبريز في صيف 1501، في السنة التالية باتجاه الشمال الغربي وأخضع الخط الممتد من أرضروم إلى حوض بحيرة وان. وكانت دولة الآق قويونلو قد انقسمت أصلًا بعد وفاة أوزون حسن بصراعات العرش إلى قسمين: فألوند بك يمسك بأذربيجان وديار بكر، وابن عمه مراد يمسك بالعراق العجمي وفارس. وسهّل هذا الانقسام التقدم الصفوي؛ وتبدلت المنطقة في عشرة سجلات في سنة واحدة. وبقيت أرضروم بعد ذلك ست عشرة سنة في يد الصفويين ولم تدخل في السيادة العثمانية إلا بعد جالديران، في 1518-19.", "9c2345ba"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["هزيمة مراد بك في همدان: انتقال العراق العجمي وفارس إلى الصفويين", "8de07a31"], "d": ["هُزم السلطان مراد، مدعي العرش الثاني للآق قويونلو، هزيمة ثقيلة في المعركة التي جرت قرب همدان أمام الشاه إسماعيل وفرّ إلى بغداد. وبهذه المعركة الواحدة دخلت مناطق العراق العجمي وفارس وكرمان في الإدارة الصفوية؛ وتبدّلت هذه المناطق في الخريطة في آن واحد. وهذه أكبر خطوة منفردة في انحلال دولة الآق قويونلو — فقد أبقى فقدان تبريز الأسرة دون عاصمة، وأبقتها هزيمة همدان دون أرض.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["دخول الشاه إسماعيل يزد: سقوط آخر معاقل بقايا الآق قويونلو في إيران الوسطى", "6f9835df"], "d": ["بعد هزيمة همدان عام 1503 انتقل العراق العجمي وفارس إلى الصفويين، لكن يزد بقيت منفصلة في يد مراد بك البايندري من أسرة الآق قويونلو. وسقطت المدينة بعد حصار دام شهرًا وأُغلقت آخر جزيرة للآق قويونلو في إيران الوسطى. وسجل TDV: «دخل الشاه إسماعيل المدينة في 28 جمادى الآخرة 910 (6 ديسمبر 1504) بعد حصار دام شهرًا.»", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["حملة الشاه إسماعيل على ديار بكر: سقوط آخر مراكز الآق قويونلو", "b6d8504e"], "d": ["توجه الشاه إسماعيل، الذي أخضع أذربيجان والهضبة الإيرانية، عام 1507 غربًا إلى منطقة ديار بكر مهد أسرة الآق قويونلو. ودخل الخط الممتد من آمد إلى ماردين ومن أورفة إلى خربوط في الإدارة الصفوية في خطوتين، وزال الآق قويونلو فعليًا. وأسندت هذه الحملة في الوقت نفسه الحدود الصفوية لأول مرة إلى الحدود العثمانية والمملوكية؛ وهكذا تأسس الأساس الجغرافي للتوتر المؤدي إلى جالديران.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["انتقال بغداد إلى الصفويين — تبدل العراق العربي", "39730186"], "d": ["بعد السلطان مراد من الآق قويونلو الذي لجأ إلى بغداد عقب هزيمة همدان، دخل الشاه إسماعيل العراق العربي عام 1508 وأخذ بغداد. وكان انتقال المراقد في كربلاء والنجف إلى الإدارة الصفوية بأهمية أخذ تبريز نفسها بالنسبة إلى دعوى الحركة المذهبية. ويتبدل العراق العربي في الخريطة في آن واحد؛ وهذه الخطوة الجغرافية الأخيرة والأوسع في الانحلال. وبقيت بغداد في يد الصفويين حتى حملة العراقين للقانوني عام 1534.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["معركة مرو: هزيمة ثقيلة للأوزبك وأخذ مرو وهراة", "f8e45aaf"], "d": ["سار الشاه إسماعيل، الذي أتمّ في الغرب ميراث الآق قويونلو، شرقًا إلى خراسان وألحق بالأوزبك هزيمة ثقيلة أمام مرو؛ وقُتل شيباني خان في ميدان المعركة. ودخلت مرو وهراة في السيادة الصفوية وبلغت الدولة الصفوية حدودها الممتدة من الفرات إلى جيحون. وبذلك اكتملت في تسع سنوات العملية التي بدأت بدخول تبريز في صيف 1501: فانتقل ميراث الآق قويونلو بأكمله إلى الإدارة الصفوية وصارت الدولة العثمانية تجاور في شرقها دولة ثانية بحجمها.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["الدخول النهائي لزبيد في السيادة العثمانية", "ddd971c7"], "d": ["مرّ الأسطول، الذي رفع حصار ديو في 5 نوفمبر 1538، في طريق العودة بساحل اليمن، وارتبطت زبيد نهائيًا بالإدارة العثمانية؛ وغادر خادم سليمان باشا المدينة في 10 مارس 1539 ووصل إلى جدة في 1 أبريل. وكانت المدينة تُدار منذ 1517 باسم العثمانيين على يد أمراء مماليك سابقين؛ وانتقلت بهذا التاريخ إلى الإدارة المباشرة.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["الاتحاد الأيبيري: انتقال التاج البرتغالي إلى ملك إسبانيا", "1cc6dfdc"], "d": ["انتهى الصراع على الوراثة، الذي انفتح بوفاة الملك الكاردينال هنريكي دون وريث، لصالح إسبانيا في معركة ألكانتارا (25 أغسطس 1580)، واعترفت كورتيس البرتغال المنعقدة في تومار بفيليبي الثاني ملكًا على البرتغال في 16 أبريل 1581. ووفقًا لشروط تومار، تحتفظ البرتغال بمؤسساتها وعملتها ولغتها، ولا يُعيَّن في الإدارة إلا البرتغاليون، ويكون في مدريد مجلس برتغالي منفصل — أي إن الاتحاد كان اتحادًا شخصيًا لا ضمًا.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["الاستعادة: البرتغال تستعيد استقلالها", "64ec0738"], "d": ["في الأيام التي كان فيها تمرد كاتالونيا يشغل إسبانيا، داهمت مجموعة من النبلاء في لشبونة القصر وأطاحت بالإدارة الإسبانية وأعلنت دوق براغانزا ملكًا باسم جواو الرابع. وبذلك انتهى الاتحاد الأيبيري الذي دام ستين سنة؛ غير أن سبتة اختارت البقاء في إسبانيا واعترفت بذلك معاهدة لشبونة عام 1668. وهذه النافذة التي ارتبطت فيها البرتغال بحروب الهابسبورغ هي أيضًا إطار خسائرها في آسيا: فقد خرجت هرمز من اليد عام 1622 وملقا عام 1641 وكولومبو عام 1656؛ أما طنجة وبومباي فأُعطيتا لإنجلترا ثمنًا للاستقلال. المصدر: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["تسليم طنجة لإنجلترا", "1f7cad6d"], "d": ["كانت المادة الثانية من معاهدة الزواج (23 يونيو 1661) المعقودة لضمان الدعم الإنجليزي في حرب استقلال البرتغال تترك طنجة لإنجلترا مهرًا لكاثرين براغانزا. وألقى أسطول إيرل ساندويتش مرساه في 29 يناير 1662 وجرى التسليم الرسمي في اليوم التالي بمراسم إيرل بيتربورو. وسيترك الإنجليز المدينة عام 1684.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["مقتل نادر شاه — تفكك السيادة الأفشارية", "19c218c0"], "d": ["قُتل نادر شاه، الذي أنهى العرش الصفوي وأعلن سلطنته باسمه عام 1736، وبلغ دلهي في حملة الهند، وخاض ثلاث حروب مع العثمانيين وصالحهم بمعاهدة كردان عام 1746، على يد حراسه في خيمته. وعقب ذلك تعذر أن تُحكم إيران بيد واحدة: فاقتسم البلاد بقايا الأفشار في خراسان والزند في الجنوب والقاجار الصاعدون في الشمال تسعًا وأربعين سنة. وبقيت الحدود الشرقية العثمانية هادئة زمنًا طويلًا بفضل هذا التشتت.", "76a3f7ee"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["سيطرة أسرة القاجار على إيران", "744b48c5"], "d": ["جمع آغا محمد خان، رئيس عشيرة القاجار، إيران من جديد في يد واحدة بعد أن أطاح بسيادة الزند وكسر آخر مقاومة أفشارية في خراسان، وجعل طهران عاصمة. وبذلك انتهت فترة التفتت التي دامت تسعًا وأربعين سنة؛ وسيكون جار العثمانيين الشرقي منذ ذلك الحين حتى 1923 إيران القاجارية.", "15d0cfa9"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["فرديناند يأخذ بودين — زابوليا يُخرَج من العاصمة", "99f77c29"], "d": ["بعد موهاكس ظهر ملكان على العرش المجري: فقد اختار قسم من النبلاء يانوش زابوليا وقسم فرديناند الهابسبورغي. وأخذ فرديناند بودين عام 1527 وأخرج زابوليا من العاصمة؛ فطلب زابوليا المساعدة من السلطان سليمان. وهذا هو سبب كون بودين الهدف الأول لحملة فيينا عام 1529.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["حملة بربروس على جزر إيجة — دوقية ناكسوس تدخل السيطرة العثمانية", "722b2fea"], "d": ["دخلت دوقية ناكسوس، التي كان يحكمها دوقات لاتين تحت وصاية البندقية منذ 1207، تحت السيطرة العثمانية بحملة بربروس خير الدين باشا على الجزر. ولم يُمسّ وضع الجزيرة؛ واستمرت الدوقية تابعة للعثمانيين، وبمعاهدة 1540 بين العثمانيين والبندقية تنازلت البندقية رسميًا للعثمانيين عن حق السيادة.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["أسطول الصليبيين يحتل جربة — قاعدة طرغد باشا تخرج من اليد", "f41b3f2a"], "d": ["استهدف أسطول الصليبيين، المؤلف من سفن إسبانيا والبابوية ومالطا وجنوة وفلورنسا، جربة التي كان طرغد رئيس يستخدمها قاعدة للإغارة منذ 1551. ولم يستطع بلوغ مياه الجزيرة إلا في أوائل عام 1560 بسبب العواصف والوباء؛ واحتل الجزيرة في 12 مارس 1560 وبنى قلعة. ولما بلغ الخبر بيالة باشا انطلق من إسطنبول في 28 مارس بأسطوله المؤلف من 120 قادسًا. ولم يطل الاحتلال: فقد هزم الأسطول العثماني الحلفاء أمام جربة في مايو، واستُردت القلعة في أواخر يوليو. وهذه الحملة هي بداية ثاني عملية بحرية كبرى رسخت التفوق العثماني في المتوسط بعد بريفيزة.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["سقوط قلعة جربة — انتقال الجزيرة إلى الإدارة العثمانية", "f1efc0df"], "d": ["بعد انتصار بيالة باشا البحري في 14 مايو 1560 تحصنت قوات الصليبيين في القلعة التي بنوها في الجزيرة؛ وحاصرتها قوات بكلربك طرابلس الغرب طرغد باشا برًا. وانتهى الحصار الذي دام شهرين بسقوط القلعة في 30 يوليو 1560، وارتبطت الجزيرة ببكلربكية طرابلس الغرب. وبين الانتصار البحري وفتح القلعة سبعة وسبعون يومًا؛ فقد تبدلت الجزيرة فعليًا في 30 يوليو لا في 14 مايو.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["انتهاء السلطة الروسية البروسية المزدوجة في دانتسيغ — عودة مدينة نابليون الحرة إلى بروسيا", "1ccda4d2"], "d": ["تركت قوات نابليون دانتسيغ، التي فُصلت عن بروسيا بصلح تيلسيت (9 يوليو 1807) وجُعلت مدينة حرة تحت الحماية الفرنسية، بعد حصار 1813. واستمرت بين 2 يناير و4 فبراير 1814 في المدينة سلطة مزدوجة روسية بروسية؛ ولما تخلى القيصر ألكسندر عن خطته لأخذ دانتسيغ ومصب الفيستولا انتقلت المدينة إلى الإدارة البروسية.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["إعلان كراكوف في فيينا مدينة حرة ومستقلة ومحايدة", "19eea839"], "d": ["جعلت روسيا والنمسا وبروسيا في مؤتمر فيينا مدينة كراكوف وما حولها دولة حرة تحت حماية الدول الثلاث؛ وأقرّ القرار الختامي لمؤتمر فيينا هذا الترتيب.", "21a6fe2b"]},
"OLAYLAR_EK12:1846-11-11:0":{"b": ["إلغاء مدينة كراكوف الحرة وضمها إلى النمسا", "15548a14"], "d": ["اتخذت روسيا والنمسا وبروسيا، متذرعة بانتفاضة كراكوف في شباط/فبراير 1846، قرارًا في مؤتمر عُقد في فيينا بإلغاء المدينة الحرة وضمها إلى أراضي النمسا؛ ولم تُجدِ اعتراضات إنجلترا وفرنسا نفعًا.", "bf12c063"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["برنو تدخل تحت سلطان رابح بن الزبير", "8be4ca96"], "d": ["استولى أمير الحرب السوداني رابح بن الزبير، الذي زعزع باغرمي ووداي، على برنو؛ وبسط سلطانه على البلاد كلها حتى عام 1896 واتخذ ديكوا عاصمة له.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["رابح بن الزبير يُهزم ويُقتل على يد الفرنسيين — انهيار سلطانه في برنو", "fb5a3ace"], "d": ["قُتل رابح بعد أن هزمه الجيش الاستعماري الفرنسي؛ وحاول ابنه مواصلة الحكم لكنه لم يستطع الثبات، وقُسّمت برنو سنة 1902 بين فرنسا وإنجلترا وألمانيا.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["إعلان الحكومة المؤقتة لتراقيا الغربية ومركزها كومولجينه", "974b2e28"], "d": ["لما تركت معاهدة بوخارست (10 أغسطس 1913) تراقيا الغربية لبلغاريا، أعلن الأتراك في المنطقة حكومة مؤقتة مركزها كومولجينه؛ وبعد أخذ ديدياغاتش أعلنت الحكومة استقلالها باسم «حكومة تراقيا الغربية المستقلة». وبتدخل الدول الكبرى لم تدعمها الحكومة العثمانية؛ وتركت معاهدة إسطنبول في 29 سبتمبر 1913 تراقيا الغربية للبلغار، وعاشت الحكومة إلى 25 أكتوبر 1913 سبعة وخمسين يومًا فقط.", "86d3bfee"]},
"OLAYLAR_EK12:1920-11-15:0":{"b": ["تأسيس مدينة دانتسيغ الحرة تحت حماية عصبة الأمم", "bd148fe8"], "d": ["بقيت دانتسيغ، التي فُصلت عن ألمانيا بمعاهدة فرساي، منذ 10 يناير 1920 تحت إدارة انتقالية للدول الكبرى الحليفة؛ وفي 15 نوفمبر 1920 أُسست مدينة حرة تحت حماية عصبة الأمم في اتحاد جمركي مع بولندا.", "c74affc1"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["وفاة أورخان غازي — نهاية الأربعين سنة التي انتقلت فيها الدولة من الإمارة إلى الدولة", "62c59cfd"], "d": ["تولى أورخان غازي رأس الإمارة بوفاة عثمان غازي سنة 1324، وحوّل العثمانيين في إدارته التي دامت ثمانيًا وثلاثين سنة من إمارة ثغرية إلى دولة مستقرة على ضفتي بحر مرمرة: فأُخذت بورصة (1326) وإزنيق (1331) وإزميد (1337)، وضُمّت إمارة قره سي، وسُكّ أول أقجة (1327)، وأُسست أول مدرسة في إزنيق (1331)، وصار العبور إلى الروملي دائمًا عبر تشيمبي (1352) وغاليبولي (1354). وفقد ابنه الأكبر سليمان باشا، الذي قاد فتوح الروملي، في حادث صيد سنة 1357؛ وتوفي هو في بورصة في آذار/مارس 1362 وخلفه ابنه مراد الأول.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["انتقال جزر البحرين إلى الجبريين", "6a242b16"], "d": ["تذكر مادة «البحرين» في موسوعة TDV أن الجزيرة بقيت «على التوالي في إدارة العيونيين والسلغريين والتبيين والجبريين، وأن الأغلبية تحولت من الشيعة إلى السنة في عهد الجبريين»؛ ولا تعطي أيَّ تاريخ لأيٍّ منها. وفي الأدبيات العامة قامت الأسرة الجبرية في مطلع القرن الخامس عشر بإسقاط آخر حكام الجروانيين في القطيف، وسيطرت في أوج عهدها (أجود بن زامل، ت. 1496) على الساحل العربي كله للخليج العربي وعلى الأحساء والقطيف وجزر البحرين. وبعد أجود انتقلت جزر أوال إلى مقرن بن زامل — وهو الحاكم الذي سيُهزم أمام البرتغاليين سنة 1521.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["استيلاء البرتغاليين على أصيلة — رأس جسر ثانٍ على الساحل المغربي", "83444a11"], "d": ["نزل ألفونسو الخامس بنفسه على الساحل المغربي بقوة قوامها 30.000 رجل وأسطول من 400 قطعة، وأخذ أصيلة، التي كانت تحت حكم الوطاسيين، في 24 آب/أغسطس 1471. وكان سقوط المدينة كسرًا لمقاومة طنجة، فاستسلمت طنجة بلا قتال بعد أربعة أيام، في 28 آب/أغسطس. وبذلك أقام البرتغال، بعد سبتة (1415) والقصر الصغير (1458)، موقعهم الثالث والرابع على ساحل المغرب الأطلسي؛ وأضاف الملك بعد هذه الحملة إلى ألقابه عبارة «سيد إفريقيا».", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["دخول آسفي في النفوذ البرتغالي", "765e703e"], "d": ["دخلت آسفي، أنشط موانئ الحبوب والصيد على الساحل الأطلسي، في النفوذ البرتغالي سنة 1488؛ وظلت المدينة بعض الوقت تُدار بأيدي حكام محليين تحت الحماية البرتغالية، ثم احتُلت احتلالًا مباشرًا سنة 1508. ولأن المصادر تُرجّح هاتين المرحلتين ترجيحًا مختلفًا، يتراوح تاريخ البداية بين 1488 و1508؛ وكلاهما طرفان لعملية واحدة. وبقيت آسفي ثلاثًا وخمسين سنة في يد البرتغال، وأُخليت سنة 1541 إثر سقوط أكادير.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["تأسيس سانتا كروز دو كابو دي غي — القلعة البرتغالية في أكادير", "cc22c433"], "d": ["أُنشئت قلعة سانتا كروز دو كابو دي غي بمبادرة خاصة على ساحل سوس، في نقطة لم يبلغها البرتغال حتى ذلك الحين، وبُنيت سنة 1505 ثم نُقلت إلى التاج البرتغالي سنة 1513. وكانت القلعة تراقب تجارة السكر والذهب في وادي سوس وتسدّ مخرج مراكش إلى الجنوب الغربي؛ ولذلك صارت أول هدف كبير للحركة السعدية. وصُدّ الحصار سنة 1533، أما حصار سنة 1541 فقد نجح وبدأ به انهيار البرتغال في المغرب.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["الاستيلاء على أزمور — السيطرة على مصب أم الربيع", "232acd4b"], "d": ["دخل الجيش البرتغالي بقيادة دوق براغانسا جايمي أزمور، عند مصب نهر أم الربيع، في 3 أيلول/سبتمبر 1513 دون مقاومة. وأتاح الاستيلاء على المدينة السيطرة على مصب النهر وعلى طريق الحبوب المفتوح نحو الداخل، ومهّد لإنشاء قلعة مازاغان في العام التالي على بعد 12 كم إلى جنوبها الغربي. وبقيت أزمور ثماني وعشرين سنة في يد البرتغال.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["تأسيس قلعة مازاغان — أطول المواقع البرتغالية بقاءً في المغرب", "786cdb40"], "d": ["في العام التالي لاستيلاء البرتغال على أزمور، أي في صيف 1514، شُيّد حصن مازاغان على الساحل. وبعد الانهيار العام سنة 1541، حين تخلّى البرتغال عن جميع مواقعه في المغرب، لم يتخلَّ عن مازاغان؛ بل أعاد بناء القلعة بأبراج على الطراز الإيطالي، وظلت المدينة في يده مئتين وخمسًا وخمسين سنة. كما صُدّ الحصار الكبير سنة 1562. وستُخلى مازاغان سنة 1769 بوصفها آخر مواقع البرتغال في المغرب.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["تسليم قلعة ماردين — نهاية المقاومة الصفوية جنوبي ديار بكر", "e6226de5"], "d": ["حين سار بيقلي محمد باشا إلى منطقة ديار بكر بعد چالديران وحاصر ماردين، انسحبت القوات الصفوية إلى القلعة في تشرين الأول/أكتوبر 1515؛ ومع أن المدينة صارت في يد العثمانيين، فقد صمدت القلعة. وانتهى هجوم الوالي الصفوي قره خان المضاد بالتعزيزات في أيار/مايو 1516 بمعركة كوچ حصار (قزل تبه) — ففي معركة استمرت يومًا كاملًا في صحراء دده كاركين قُطع رأس قره خان وتفرق جيشه. أما القلعة فاستسلمت بحسب عبارة موسوعة TDV «بعد تسعة أشهر فحسب».", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["استيلاء البرتغال على البحرين — نهاية السيادة الجبرية", "315a435a"], "d": ["حين رفض الحاكم الجبري مقرن بن زامل دفع الجزية لهرمز، نزلت إلى الجزيرة قوات الأسطول البرتغالي ومملكة هرمز التابعة للبرتغال؛ فانهزم مقرن في المعركة ودخلت البحرين تحت الإدارة البرتغالية سنة 1521. وأُديرت الجزيرة بعد ذلك ثمانين سنة عن طريق هرمز، على أيدي ولاة إيرانيين أغلبهم من السنة. وكانت لآلئ البحرين وموقعها الاستراتيجي سيجعلان الجزيرة هدفًا مباشرًا للتنافس العثماني البرتغالي في الخليج.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["سقوط أكادير — السعديون يبدؤون اقتلاع البرتغال من المغرب", "bb1568f6"], "d": ["حاصر السلطان السعدي محمد الشيخ قلعة سانتا كروز في 16 شباط/فبراير 1541 وفتحها في 12 آذار/مارس؛ ووقع في الأسر نحو ستمائة برتغالي، بينهم الحاكم غوتيري دي مونروي.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["إخلاء آسفي وأزمور — البرتغال ينسحب من الساحل الأطلسي", "4cb6099a"], "d": ["إثر سقوط أكادير في 12 آذار/مارس 1541 وتعذر عقد التحالف المأمول مع سلطان المغرب، أمر جواو الثالث بإخلاء الموقعين الكبيرين على الساحل الأطلسي؛ وتم إخلاء آسفي وأزمور في خريف 1541، في أيلول/سبتمبر وتشرين الأول/أكتوبر. وبذلك خسر البرتغال ثلاثة مواقع في سنة واحدة، وانعكس اتجاه توسعهم على الساحل المغربي الذي دام خمسين سنة؛ ولم يبقَ سوى سبتة وطنجة وأصيلة والقصر الصغير ومازاغان المحصّنة حديثًا.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["إخلاء أصيلة — البرتغال يقلّص وجوده على الساحل الشمالي", "b5d18373"], "d": ["أخلى جواو الثالث أصيلة، التي كانت في يده منذ 1471، بسبب اجتماع الأزمة المالية وضغط السعديين. وبذلك انحصر وجود البرتغال في المغرب في سبتة وطنجة ومازاغان. وستُحتل أصيلة مجددًا لفترة قصيرة سنة 1577، ثم تُترك نهائيًّا سنة 1589.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["حملة العثمانيين على البحرين — آخر محاولة كبرى ضد البرتغال في الخليج", "14501df3"], "d": ["بعد ضم البصرة سنة 1546 وإنشاء إيالة الأحساء، استقرت الدولة العثمانية على الساحل العربي للخليج، فسارت على البحرين بقيادة بكلربك الأحساء مصطفى باشا، مستهدفة تجارة اللؤلؤ في الجزيرة وخط هرمز البرتغالي. وتتباين المصادر في نتيجة الحملة: فموسوعة TDV الإسلامية تذكر أن العثمانيين «استولوا على البحرين سنة 1559 وأقاموا فيها قاعدة»، وأن الجزر «عادت بعد ذلك إلى إدارة البرتغاليين»؛ أما الأدبيات الغربية فتسجل أن الحصار فشل، وأن التعزيزات البرتغالية القادمة من هرمز بحرًا ردّت القوات العثمانية، وأن العثمانيين طلبوا شروط التسليم بعد وباء حصد الطرفين. وتفترق الروايتان في النتيجة نفسها؛ والمشترك بينهما أن البحرين لم تبقَ في يد العثمانيين.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["استيلاء أولوج علي باشا على تونس — نهاية النظام الحفصي الإسباني", "d4498698"], "d": ["حين استولى شارلكان على تونس سنة 1535 لم يتولّ حكم المدينة بنفسه، بل أعاد السلطان الحفصي مولاي حسن إلى العرش؛ وبحسب عبارة موسوعة TDV بقيت مدينة تونس «تحت حماية الإسبان وفي إدارة مولاي أحمد الثالث حتى التدخل العثماني الثاني سنة 1569». وسار أولوج علي، الذي عُيّن بكلربك الجزائر في 27 حزيران/يونيو 1568، براً نحو تونس، فهزم السلطان الحفصي في باجة ودخل المدينة؛ ولجأ مولاي أحمد إلى الحصن الإسباني في حلق الوادي. وبذلك انقسم الخليج شطرين — المدينة عثمانية وقلعة الميناء إسبانية — واستمر هذا الانقسام أربع سنوات.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["استعادة دون خوان النمساوي لتونس — المقابل البري الوحيد للبنت", "a6f044ee"], "d": ["بعد لبنت (1571)، ومع أن العصبة المقدسة تفككت، تحمّلت إسبانيا وحدها عبء شمال إفريقيا؛ وبحسب عبارة موسوعة TDV: «في 10 تشرين الأول/أكتوبر 1573 شرع الإسبان في حملة جديدة بقصد السيطرة على تونس. واستولوا على تونس وتركوا فيها 8000 جندي». وهذه الحملة بقيادة دون خوان النمساوي هي الموضع الوحيد الذي وجد فيه انتصار لبنت ما يقابله في البر؛ غير أنها لم تدم، وأُعيد أخذ المدينة بعد أحد عشر شهرًا. وما أسقطه الاحتلال إدارة عثمانية قائمة: ففي 2 ذي الحجة 980 (5 نيسان/أبريل 1573) كان قائد تونس قليج علي باشا، وقائم مقامه رمضان باشا، وبكلربكها حيدر باشا.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["استرداد الصفويين البحرين من البرتغال", "c37d982c"], "d": ["اجتمعت القوات التي أرسلها الشاه عباس الأول مع المتمردين في الجزيرة فأخرجت الحامية البرتغالية من القلعة؛ وبحسب عبارة موسوعة TDV انتُزعت الجزر من يد البرتغاليين «سنة 1602 على أيدي قوات تابعة لإيران». وبذلك خرجت البحرين من الإدارة البرتغالية التي دامت إحدى وثمانين سنة ودخلت في السيادة الصفوية، وبقيت تابعة لإيران مئة وخمس عشرة سنة. وهذه أولى حلقات تفكك البرتغال في الخليج؛ وبعد عشرين سنة سقطت هرمز نفسها في عملية إنجليزية إيرانية مشتركة.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["غزو العمانيين للبحرين — نهاية السيادة الصفوية", "c9be5820"], "d": ["في أثناء التفكك الذي أصاب الدولة الصفوية في سنواتها الأخيرة، غزا الأسطول العماني بقيادة أسرة اليعاربة الجزيرة وانتهت السيادة الصفوية. والسنوات الخمس والثلاثون التي تلت هي أشد فترات الخليج اضطرابًا: فقد تبادلت عُمان وإيران والقوى العربية المحلية الجزيرةَ مرات عدة.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["انتقال البحرين إلى إدارة آل مذكور في بوشهر", "610e2f9d"], "d": ["أخضعت أسرة آل مذكور، وهي من أصل عماني استقرت في بوشهر وتُعدّ من الحُوَلة، البحرينَ لإدارتها سنة 1753 انطلاقًا من قواعدها في بوشهر. وكانت الأسرة تتزعم المجتمعات العربية على ساحل إيران الخليجي وتحكم الجزيرة باسم إيران؛ وكان آخر ممثليها نصر آل مذكور قد عيّنته إدارة الزند واليًا على البحرين. وهذه آخر إدارة للجزيرة قبل آل خليفة.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["إخلاء مازاغان — سقوط آخر موقع للبرتغال في المغرب", "f9e9749d"], "d": ["لم تصمد الحامية البالغ عددها 592 رجلًا أمام الحصار الذي بدأه السلطان العلوي محمد الثالث بن عبد الله في مطلع 1769؛ فأقلّع أسطول الإخلاء من لشبونة في 1 شباط/فبراير، وأخذ في 11 آذار/مارس 1769 آخر الجنود على متن السفن، وكان آخر من غادر المدينة الحاكم دينيس غريغوريو. وبذلك انتهى بعد ثلاثة قرون ونصف وجود البرتغال في المغرب الذي بدأ باستيلائه على سبتة سنة 1415. وكانت مازاغان الموقع الوحيد على الساحل الأطلسي الذي بقي بعد الانهيار العام سنة 1541، وبمئتين وخمسين سنة وخمس صارت أطول مكان احتفظ به البرتغال في المغرب.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["فتح آل خليفة للبحرين — تأسيس الأسرة الحاكمة إلى يومنا هذا", "8773b011"], "d": ["حاصر نصر آل مذكور، والي البحرين من قِبل إدارة الزند، الزبارة في شبه جزيرة قطر؛ فكسرت قوات العتوب بقيادة أحمد بن محمد بن خليفة الحصار وانتقلت إلى الهجوم المضاد، وأخذت البحرين في السنة نفسها. وتسجيل موسوعة TDV موجز: «دخلت البحرين سنة 1783 تحت سلطان آل خليفة من قبيلة العتوب». وعُرف أحمد بن محمد بعد هذا النصر بلقب «الفاتح»، ولا تزال الأسرة التي أسسها تحكم الجزيرة حتى اليوم.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["معاهدة البحرين مع إنجلترا — الدخول في نظام الحماية في الخليج", "576796b2"], "d": ["بحسب ما تسجله موسوعة TDV، «وقّع علي، أخو الشيخ محمد ممثلًا البحرين، مع إنجلترا في 21 أيار/مايو 1861 اتفاقًا يمنع تجارة الرقيق والقرصنة في المنطقة»؛ أما في الوثائق الإنجليزية فتحمل المعاهدة نفسها (Perpetual Truce of Friendship and Peace) تاريخ 31 أيار/مايو 1861. والمعاهدة هي الحلقة الأولى في نظام الحماية الذي يربط علاقات البحرين الخارجية بإنجلترا، وبقيت الجزيرة خارج هذا النظام حتى بعد عودة العثمانيين سنة 1871 إلى الأحساء والقطيف.", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["أخي أوران — القطب المؤسس لتنظيم الأخية", "3392e100"], "d": ["يُعدّ أخي أوران من مؤسسي تنظيم الأخية في الأناضول وقطب الدبّاغين (العاملين في الجلود). وقد استمرت زاويته في قيرشهير، في العهد العثماني، المركزَ المعنوي لتنظيم أهل الحرف/الطوائف حتى مطلع القرن العشرين؛ وأقرّت الدولة هذه المكانة رسميًّا في 1780 و1782 و1822-1823 و1842.", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["الشيخ أدب علي — الرابطة المؤسسة بين الأخية والأسرة العثمانية", "c1186059"], "d": ["أسس أدب علي زاوية في بيله جيك وكان في الوقت نفسه شيخًا من شيوخ تنظيم الأخية؛ وبحسب الرواية فسّر رؤيا عثمان غازي المشهورة، ثم تزوج عثمان غازي ابنة أدب علي، مال خاتون. ويُعدّ أدب علي أيضًا أول قاضٍ ومفتٍ عثماني.", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["أورخان غازي يوقف أرضًا لألعاب الجريد بعد فتح بورصة", "da1becbd"], "d": ["بحسب مادة الجريد في TDV، أوقف أورخان غازي بعد فتح بورصة أرضًا في الجوار لسباقات الخيل وألعاب الجريد — وهذا من أولى النماذج المسجلة لتحول لعبة الجريد إلى مؤسسة في الدولة العثمانية.", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["البداية المروية لمصارعات قرق بينار", "2d93fa65"], "d": ["بحسب الرواية بدأ تقليد المصارعة في قرق بينار بمباريات مصارعة جرت بين الغزاة الأربعين الذين عبروا مع فاتح الروملي سليمان باشا. وتنقل مادتا المصارعة وقرق بينار في TDV هذه الرواية لكنهما لا تعطيان تاريخ تأسيس قاطعًا.", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["تأسيس الأوجاق الإنكشاري", "f4206dce"], "d": ["بتوجيه من چندارلي قره خليل وملا رستم، بدأ النظام بتدريب الشباب غير المسلمين المأخوذين من أسرى الحرب بموجب قانون البنجيك، ثم اكتسب هوية مؤسسية في عهد مراد الأول عن طريق أوجاق العجمي الذي أُسس في غاليبولي.", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["بدء بناء الجامع العتيق (الجامع الكبير) في أدرنة", "da7a22ac"], "d": ["بدأ الأمير سليمان چلبي بناء الجامع العتيق، المعروف بين الناس أيضًا بالجامع الكبير (جامع عتيق)، في 1402-1403.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["بدء بناء مجمع الجامع الأخضر في بورصة", "280b8a21"], "d": ["بدأ محمد الأول، الذي أعاد توحيد العرش بعد عهد الفترة، بناء المجمع سنة 1414، وأقامه في نقطة مركزية من بورصة بحيث يتميز عن مجمعات جده وأبيه. ورئيس معماريه هو حاجي إيواز باشا.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["إتمام مجمع الجامع الأخضر في بورصة", "bc82821f"], "d": ["اكتمل مجمع الجامع الأخضر، المعروف ببرنامجه من القيشاني والزخرفة الذي أسهم فيه أيضًا أساتذة من تبريز، في كانون الأول/ديسمبر 1419. ويتألف المجمع من جامع وضريح (الضريح الأخضر) ومدرسة وعمارة وحمام؛ وهو من أغنى نماذج العمارة العثمانية المبكرة.", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["بدء تطبيق نظام الدوشرمة فعليًّا", "fa835172"], "d": ["بدأ أسلوب الدوشرمة، الذي لم يُعرف في الدول الإسلامية السابقة، أولًا بصورة الاستفادة من الشباب غير المسلمين من أسرى الحرب بموجب قانون البنجيك. وبحسب TDV «يُفهم أنه طُبق في زمن چلبي محمد، لكنه صار قانونًا في عهد ابنه مراد الثاني.»", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["استحداث منصب شيخ الإسلام — إفتاء ملا فناري في بورصة", "2a8ee2b9"], "d": ["يُعدّ تعيين العالم ملا فناري، الذي ظل سنوات طويلة قاضيًا في بورصة، مفتيًا لبورصة سنة 1425 «بداية الإفتاء ومشيخة الإسلام عند العثمانيين» بعبارة TDV. غير أن TDV تذكر أن هذا لا يتطابق مع منصب شيخ الإسلام المؤسسي تمامًا الذي مثّل في القرن السادس عشر جهاز العلمية بأكمله.", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["ترسخ نظام التيمار مؤسسيًّا", "dc267780"], "d": ["تعود أولى الإشارات الموثقة إلى التيمار إلى عهد أورخان بك؛ أما التقنين المنهجي فتم في عهد مراد الثاني. وتدل دفاتر إجمال التيمار التي أُعدت في هذا العهد على أن جميع المبادئ الأساسية للنظام قد تشكلت؛ وتثبت وثائق من نحو 1432 أن القوانين كانت نافذة تمامًا.", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["إتمام جامع أوچ شرفلي ومجمعه", "cde6993e"], "d": ["جامع أوچ شرفلي، الذي أمر ببنائه مراد الثاني على يد أستاذين اسمهما مصلح الدين وشهاب الدين خلال عشر سنوات (1437-1447)، يُعدّ أول نموذج للجوامع ذات المخطط المركزي في العمارة العثمانية، وأحد منعطفات عمارة المرحلة الانتقالية السابقة للعصر الكلاسيكي.", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["ترسخ الديوان الهمايوني مؤسسيًّا بقانون الفاتح", "e8443e77"], "d": ["بدأ الديوان يكتسب هوية «الديوان الهمايوني» بخضوعه لقواعد منتظمة في أدرنة في عهد مراد الثاني. وجاء التحول الأساسي بقانون السلطان محمد الفاتح: وكان أكبر تجديد إلغاء رئاسة السلطان للديوان إلغاءً تامًّا وتفويضها إلى الصدر الأعظم.", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["السلطان محمد الفاتح يخصص أوق ميداني للرماة", "342a9fd5"], "d": ["كان السلطان محمد الفاتح، الذي أقام معسكره على تلال قاسم باشا أثناء فتح إسطنبول، قد استخدم هذا الموضع أيضًا ساحة تدريب للرماة؛ وبعد أخذه المدينة خصصه للرماة تخصيصًا دائمًا. وهذا التخصيص هو بداية صيرورة أوق ميداني مركز تقليد الرماية العثماني الذي سيدوم قرونًا.", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["بلوغ بورصة ذروتها في تجارة الحرير الإيراني", "f1324cdf"], "d": ["كانت القوافل القادمة من تبريز تحمل حرير جيلان وأسترآباد وساري إلى بورصة، حيث كان التجار الجنوية والبندقية والفلورنسيون واليهود يتنافسون في شرائه. وبلغت قيمة الحرير المستورد من إيران سنة 1479 مبلغ 150.000 دوكا بندقيًّا؛ وفي سنة 1502 كان يعمل في المدينة أكثر من 1000 نول.", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["بايزيد الثاني يمنح مصارعي قرق بينار جوائز كبيرة", "d745b882"], "d": ["بحسب مادة المصارعة في TDV، منح بايزيد الثاني سنة 1504 المصارعين جوائز قدرها 3.000 و1.500 قرش؛ وهذا من النماذج المبكرة المسجلة لرعاية القصر العثماني لرياضة المصارعة.", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["إتمام جامع بايزيد ومجمعه", "eb9ab65b"], "d": ["بدأ بناء جامع بايزيد ومجمعه، الذي أُقيم للسلطان بايزيد الثاني، بحسب وثيقة أرشيفية سنة 906 (1500)، وانتهى في 14 جمادى الأولى 911 (13 تشرين الأول/أكتوبر 1505). ومعماره موضع خلاف: فقد عُدّ زمنًا طويلًا من أعمال المعمار خير الدين استنادًا إلى ما سجله أيوانسرايي، ثم نُسب إلى المعمار كمال الدين، ويرى بعضهم أنهما عملا معًا؛ أما الوثيقة نفسها فتدل على أن الأستاذ هو يعقوب شاه بن سلطان شاه. ويُعدّ الجامع من الآثار المهمة في الانتقال من العمارة العثمانية السابقة للكلاسيكية إلى العصر الكلاسيكي.", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["نقل ترسانة عامرة إلى إسطنبول (قاسم باشا/القرن الذهبي)", "f36e3675"], "d": ["اكتمل في عهد السلطان ياووز سليم سنة 1515 بناء الترسانة الجديدة، التي بدأ بناؤها في الخليج غربي أسوار غلطة، بـ160 فتحة؛ وبذلك انتقلت أنشطة الترسانة التي كان مركزها غاليبولي إلى إسطنبول. وحملت المؤسسة بعد ذلك رسميًّا اسم «ترسانة عامرة» في عهد باربروس خير الدين باشا.", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["وفاة الشيخ حمد الله وإرث مدرسة الخط", "f5ed4d09"], "d": ["كان الشيخ حمد الله الأماسي، معلم الخط لبايزيد الثاني، مؤسس طراز عثماني في الخط بلغ بمدرسة الأقلام الستة (أنواع الخط الستة) سن النضج وسيطر على العالم الإسلامي كله. وحين توفي سنة 1520 ترك وراءه حلقة واسعة من التلاميذ.", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["بيري ريس يتم النسخة الأولى من كتاب بحرية", "fd6cc1ff"], "d": ["أتم بيري ريس سنة 1521 النسخة الأولى (النثرية) من كتاب بحرية الذي جمع فيه سواحل البحر المتوسط وموانئه ومعارف الملاحة. ولم تكن هذه النسخة الأولى قد قُدمت بعد إلى السلطان، بل كانت مسودة ستُوسَّع في السنوات اللاحقة.", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["بيري ريس يوسّع كتاب بحرية ويقدمه إلى السلطان سليمان القانوني", "d4abf0b7"], "d": ["وسّع بيري ريس كتاب بحرية جزئيًّا بصيغة منظومة وقدمه إلى السلطان سليمان القانوني سنة 1526. وبهذه الصورة شاع الكتاب بوصفه أشمل دليل ملاحي في الملاحة البحرية العثمانية.", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["ماطراقجي نصوح يصوّر طريق حملة العراقين في «بيان منازل»", "aa012278"], "d": ["صوّر ماطراقجي نصوح، الذي شارك في أول حملة إلى إيران (حملة العراقين) التي خرج إليها السلطان سليمان القانوني سنة 1534، كل منزل على طريق الجيش من إسطنبول إلى تبريز ومنها إلى بغداد بتقنية المنمنمة الخريطية. وجُمع هذا العمل في كتاب «بيان منازل سفر العراقين»، وهو أكثر نماذج نوع «منزلنامة» أصالةً في الدولة العثمانية.", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["فضولي يقدم قصيدة إلى القانوني بعد فتح بغداد", "1ef0653f"], "d": ["بعد أن فتح السلطان سليمان القانوني بغداد سنة 1534، قدّم فضولي إلى السلطان العثماني خمس قصائد، منها قصيدته المشهورة التي تبدأ بالمصراع «Geldi burc-ı evliyâya pâdişâh-ı nâmdâr»؛ فخرج بذلك من الرعاية الصفوية وطلب رعاية رجال الدولة العثمانيين.", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["فضولي يتم مثنوي «ليلى والمجنون»", "e3ef4085"], "d": ["أُلّف مثنوي «ليلى والمجنون»، الذي يُعدّ من أجمل المثنويات في الأدب التركي الكلاسيكي، وأتمّه فضولي سنة 1535 بطلب من شعراء إسطنبول الذين شاركوا في حملة القانوني على بغداد.", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["تعيين المعمار سنان رئيسًا لمعماري الخاصة", "7a753f0e"], "d": ["بحسب مادة سنان في موسوعة TDV الإسلامية، لما توفي رئيس معماري الخاصة عجمي علي سنة 1537، عُيّن سنان، الذي لفت الأنظار بالجسر الذي أقامه على نهر بروت في حملة البغدان، في هذا المنصب بتقدير من الصدر الأعظم لطفي باشا. وبذلك بدأ عهد رئاسة سنان للمعماريين الذي سيدوم أكثر من خمسين سنة.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["بدء بناء جامع الشهزاده ومجمعه", "1a70ddfd"], "d": ["أمر السلطان سليمان القانوني ببناء المجمع باسم ابنه الشهزاده محمد الذي فقده في وباء سنة 1543؛ وبدأ البناء في حزيران/يونيو 1543، فأُنجز الضريح أولًا ثم انتقل العمل إلى بناء الجامع. وهذا البناء «أثر تلمذتي» بعبارة المعمار سنان نفسه.", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["إتمام مجمع أسكودار إسكله (مهرماه سلطان)", "3769007f"], "d": ["بدأ بناء المجمع في ميدان إسكله بأسكودار في السنوات الأولى من أربعينيات القرن السادس عشر وانتهى سنة 1547. وهو أول الجامعين الكبيرين اللذين بنتهما مهرماه سلطان على يد المعمار سنان من حيث الترتيب الزمني؛ أما الثاني (أدرنة قابي) فسيُتم بعد نحو عشرين سنة.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["البندقية تفتح قنصلية في حلب", "3aad8b9e"], "d": ["انتقل في القرن السادس عشر مركز الثقل التجاري للأوروبيين من دمشق إلى حلب. وكان من مظاهر هذا التحول الملموسة أن فتحت البندقية قنصلية في حلب سنة 1548، تبعتها فرنسا سنة 1557 ثم إنجلترا سنة 1586. وصارت المدينة السوق الرئيسية التي تُتبادل فيها الأقمشة الصوفية والفضة الأوروبية بالتوابل الهندية، وفي نهاية القرن بالحرير الإيراني.", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["فتح جامع الشهزاده للعبادة", "2bb3f4b2"], "d": ["فُتح جامع الشهزاده للعبادة في آب/أغسطس 1548 بعد بناء دام نحو خمس سنوات. ويُعدّ بمخططه ذي المئذنتين والقبة المركزية بشيرًا بأعمال المعمار سنان الكبرى اللاحقة؛ ويتألف المجمع من جامع وضريح ومدرسة وعمارة وطبخانة وخان.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["بدء بناء خط إسالة المياه «قرق چشمه»", "14124b59"], "d": ["درس المعمار سنان، بأمر القانوني، جلب المياه إلى إسطنبول من غابات بلغراد وأبلغ بإمكان ذلك؛ وبدأ بناء المنشأة المائية الكبيرة سنة 1554 وانتهى قبل 1563. وتصف موسوعة TDV هذا البناء بأنه «أهم أعمال سنان من الناحية الهندسية وأكبرها حجمًا».", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["افتتاح أولى المقاهي في إسطنبول", "85c12f9f"], "d": ["بدأ دخول القهوة إلى الحياة الحضرية العثمانية بمقاهٍ فتحها في تخته قلعة التاجر الحلبي حكم ورجل دمشقي يُدعى شمس. وسرعان ما نشأت فضاء عام جديد يجتمع فيه أناس من كل فئات المجتمع؛ وكان في إسطنبول في أواخر عهد القانوني خمسون مقهى.", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["أبو السعود أفندي يدرس مسألة الكدك (حق احتكار أهل الحرف) فقهيًّا", "5d4e2930"], "d": ["عادت مسألة «الكدك»، وهو حق الاحتكار والامتياز الممنوح لعدد معين من الأشخاص في الحرف، إلى جدول الأعمال في عهد القانوني؛ فدرس شيخ الإسلام أبو السعود أفندي الموضوع دراسة معمقة في 1555-1556 وعرض مشروعية الممارسة على السلطان.", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["سيدي علي ريس يتم «مرآة الممالك» في إسطنبول", "ee8640e1"], "d": ["أتم سيدي علي ريس في إسطنبول، في كانون الثاني/يناير 1557، كتاب الرحلة «مرآة الممالك» الذي كتبه ابتداءً من بغداد وطوال رحلة العودة. والكتاب مصدر مباشر يروي عودة بحّار عثماني إلى وطنه برًّا من المحيط الهندي عبر آسيا الوسطى.", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["بناء مجمع (جامع) رستم باشا", "02e30725"], "d": ["شُيّد المجمع الذي بناه رستم باشا، صهر القانوني وصدره الأعظم، على يد المعمار سنان بين 1555 و1561. ويُعرف البناء بعمارته الأصيلة المقامة على منصة مرتفعة تحتها دكاكين معقودة، وبقيشانيه الإزنيقي الغني.", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["إتمام جسر موستار", "e7f434af"], "d": ["بنى المعمار خير الدين جسر موستار المشهور على نهر نيريتفا نحو سنة 1566-1567؛ وذكر الجسر في وثيقة رسمية مؤرخة سنة 1568 يؤكد أنه كان قد اكتمل. والبناء من أشهر نماذج عمارة الجسور العثمانية الكلاسيكية ذات القوس المدبب الوحيد.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["إتمام جامع أدرنة قابي (مهرماه سلطان)", "f2d21a82"], "d": ["بدأ بناء الجامع بعد إذن بالبناء ثبت سنة 1563 لمهرماه سلطان ابنة القانوني، وانتهى سنة 1566؛ وحُرّر وقفية المجمع في 1570-1571. والبناء من أكبر أعمال المعمار سنان قربًا من أسوار إسطنبول.", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["باقي يكتب مرثية للسلطان سليمان القانوني", "7aa6665f"], "d": ["لما جاء نبأ وفاة السلطان سليمان القانوني في سيكتوار، كتب باقي، «سلطان الشعراء» في ذلك العصر، إحدى أشهر المراثي في الأدب العثماني.", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["باقي يقدم قصيدة جلوس إلى سليم الثاني", "6027f034"], "d": ["قدّم باقي إلى السلطان الجديد «قصيدة جلوس» (شعر الجلوس على العرش) مباشرة بعد اعتلاء سليم الثاني العرش — وبحسب TDV بعد المرثية التي كتبها في وفاة القانوني مباشرة.", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["إتمام جسر بويوك چكمجة", "5f49b3c5"], "d": ["الجسر الذي بدأ بأمر السلطان سليمان القانوني أتمّه ابنه سليم الثاني سنة 1567-1568 إثر وفاة السلطان في أثناء حملة سيكتوار. وأصلح المعمار سنان بنفسه الأجزاء التي أصابها الفيضان من الجسر الذي بناه عند النقطة التي تلتقي فيها بحيرة بويوك چكمجة بالبحر.", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["بدء بناء جامع السليمية (أدرنة)", "07e18c9e"], "d": ["بدأ بناء السليمية، التي سمّاها المعمار سنان «أثر إتقاني»، باسم سليم الثاني سنة 1568 واستمر ست سنوات وانتهى سنة 1574 (وإتمامه مسجّل أصلًا في الكرونولوجيا). أما الدكاكين الغربية للأراستا ومكتب الصبيان فقد أتمهما داود آغا في عهد مراد الثالث بعد وفاة سليم الثاني.", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["وفاة قنالي زاده علي چلبي — مؤلف «أخلاق علائي»، النص الكلاسيكي للفلسفة الأخلاقية العثمانية", "dd921873"], "d": ["توفي قنالي زاده علي چلبي، مؤلف «أخلاق علائي» أشهر النصوص الكلاسيكية في الفلسفة الأخلاقية العثمانية، وهو قاضي عسكر الأناضول، في 22 كانون الثاني/يناير 1572. وتوجد من كتابه أكثر من سبعين نسخة في مكتبات إسطنبول.", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["بناء مجمع پيالة باشا", "75411278"], "d": ["اشترى قبطان البحر پيالة باشا، أحد أصهار سليم الثاني، أرض المجمع سنة 1573 وبناه على يد المعمار سنان. وصُمم المجمع مجمعًا واسعًا يتألف من جامع ومدرسة وتكية وضريح ومقبرة ومكتب صبيان وسبيل وسوق وحمام.", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["إتمام جسر درينا (صوقوللو محمد باشا)", "1d668c73"], "d": ["الجسر الذي بناه المعمار سنان برعاية الصدر الأعظم صوقوللو محمد باشا أُنجز في 1577-1578 بحسب التاريخ المدوَّن في كتابته؛ ويرى بعض الباحثين أن البناء بدأ سنة 1571-1572. والجسر رمز لتعلق صوقوللو بفيشغراد التي وُلد فيها.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["بناء جامع آزاب قابي (صوقوللو محمد باشا)", "f7b57feb"], "d": ["بنى الصدر الأعظم صوقوللو محمد باشا الجامعَ الواقع بجوار قدم جسر أونكاباني من جهة شيشهانة على يد المعمار سنان. وهو أحد جامعين من أعمال سنان أُنشئا باسم صوقوللو (والآخر الجامع في قدرغة).", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["مراد الثالث يصدر فرمانًا لكتابة «هنرنامه»", "b125710d"], "d": ["أمر مراد الثالث، بفرمان مؤرخ في 2 كانون الثاني/يناير 1578، السيد لقمان بكتابة «هنرنامه» الذي يتناول حياة السلاطين من عثمان غازي إلى عصره؛ وأعدّ منمنماته نقاش عثمان وفريقه.", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["إتمام جامع زال محمود باشا", "732f75bc"], "d": ["في بناء المجمع الذي بدأ بعد زواج زال محمود باشا وشاه سلطان سنة 1574، اكتمل بناء الجامع سنة 1580؛ واستمر بناء المدارس حتى 1582، والسبيل حتى 1590. ويلفت المجمع الأنظار بمخططه الأصيل ذي المئذنتين المتماثلتين على سفوح أيوب.", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["إتمام المجلد الثاني من «هنرنامه»", "70a1e741"], "d": ["اكتمل المجلد الثاني من «هنرنامه» في كانون الثاني/يناير 1588؛ وبمنمناته الـ65 صار من أثمن أعمال التأريخ العثماني من الناحية الوثائقية. وقد صُوّر المجلدان كلاهما في مشغل نقاش عثمان.", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["تولّي داود آغا رئاسة معماري الخاصة", "8cdc7f53"], "d": ["بعد فترة قصيرة تلت وفاة المعمار سنان سنة 1588، أخذ داود آغا يُذكر في الوثائق الرسمية ابتداءً من سنة 1592 رئيسًا لمعماري الخاصة. وداود آغا، الذي تولى بعض العناصر المكملة لمجمع السليمية والبناء الأول لجامع يني، من أهم معماريي عصره.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["وضع حجر أساس جامع يني (إمينونو)", "d3cddc01"], "d": ["وُضع أساس الجامع برعاية صفية سلطان والدة محمد الثالث، بعد تثبيت الأرض بالأوتاد ووضع كتل الحجر. وتذكر مادتان مستقلتان في TDV تاريخين مختلفين لهذه الواقعة (مادة مجمع يني جامع: 9 نيسان/أبريل 1598، ومادة داود آغا: 23 آب/أغسطس 1597)؛ واعتُمد هنا التاريخ الوارد في المادة الخاصة بالبناء نفسه.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["وفاة داود آغا بالطاعون وتوقف بناء جامع يني", "81f2cd04"], "d": ["حين توفي داود آغا في وباء الطاعون في أيلول/سبتمبر 1598، وكان لم يرفع جامع يني عن الأرض سوى ذراع واحدة، عُيّن دالغيچ أحمد چاووش رئيسًا للمعماريين مكانه. وتشير TDV إلى أن تاريخ الوفاة يرد أيضًا في رواية بديلة تستند إلى منظومة تاريخية بصيغة 1599-1600، وأن التاريخ القاطع لم يتحدد.", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["التصدير المكثف لصوف أنقرة إلى أوروبا", "3f37018d"], "d": ["كان الصوف والشالي المنسوجان في أنقرة يُصدَّران إلى الأسواق الداخلية مثل إسطنبول وبورصة ودمشق وحلب، وإلى البندقية وبولندا وإنجلترا وفرنسا. وفي المثال الذي تورده TDV اشترى ثمانية عشر تاجرًا سنة 1599 ما قيمته 5.700.000 أقجة من 162 حِملًا من الصوف وأرسلوها إلى حلب والبندقية.", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["توقف بناء جامع يني إثر وفاة محمد الثالث", "5acef053"], "d": ["بعد وفاة محمد الثالث، ابن صفية سلطان صاحبة الوقف، سنة 1603، أُرسلت صفية سلطان إلى القصر القديم وتوقف بناء جامع يني؛ وبقي البناء على هذه الحال نحو ستين سنة دون أن يكتمل.", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["كاتب جلبي يبدأ البحث في حلب من أجل «كشف الظنون»", "094e6870"], "d": ["بدأ كاتب جلبي في حلب سنة 1633 جمع مادة «كشف الظنون» الذي سيصير تحفته الببليوغرافية. وطوال هذا العمل الذي سيدوم عشرين سنة، تفحّص مكتبات المدن التي ذهب إليها ودكاكين كتبييها واحدًا واحدًا.", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["إعدام نفعي بسبب هجائياته", "5e459c60"], "d": ["أُعدم نفعي، الشاعر الديواني المعروف بهجائياته، سنة 1635 بأمر مراد الرابع بسبب مجموعته الهجائية «سهام القضا». وقد سلّمه الصدر الأعظم بيرام باشا؛ فخُنق نفعي في مخزن حطب القصر وأُلقيت جثته في البحر.", "e3b52153"]},
"OLAYLAR_EK14:1640-01-01:0":{"b": ["خروج أوليا چلبي في رحلته الأولى — بداية «سياحتنامه»", "ca3ce3f9"], "d": ["قام أوليا چلبي برحلته الأولى خارج إسطنبول إلى بورصة سنة 1640، فبدأ حياة الترحال التي دامت أربعين سنة وشكّلت أساس «سياحتنامه» ذي المجلدات العشرة. ويتوقف الكتاب فجأة في المجلد العاشر دون أن يكتمل، إذ توفي المؤلف نحو سنة 1684.", "1db7969c"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["وضع دفتر نرخ شامل", "6c1e231b"], "d": ["مع أن تطبيق النرخ (الحد الأقصى للأسعار) قديم جدًّا في الدولة العثمانية، فإن أشمل دفتر نرخ وصل إلينا مؤرخ في 1640؛ وهذا الدفتر الذي يشمل الغذاء والملبس والخدمات والمعايير والظروف الصحية «عمل بمنزلة قانون كامل لتنظيم السوق» بعبارة TDV.", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["كاتب جلبي يشرع أول مرة في تأليف «جهان نما»", "554c6734"], "d": ["شرع كاتب جلبي سنة 1648 في التأليف الأول لكتاب «جهان نما» بقصد سد الفجوة في المعرفة الجغرافية العثمانية أمام الاكتشافات الجغرافية للغرب. وبقيت هذه النسخة الأولى ناقصة لعدم وجود مصادر كافية عن بعض البلدان الأوروبية.", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["نضج نظام الالتزام بدخوله في احتكار الطبقة العسكرية", "2c587934"], "d": ["كان أسلوب الالتزام (إحالة جباية الضرائب إلى أفراد خاصين مقابل بدل) مطبقًا منذ النصف الثاني من القرن الخامس عشر، لكنه أخذ ينتشر سريعًا منذ مطلع القرن السادس عشر. وبحسب TDV اكتملت سنة 1650 عملية دخول القطاع كله في احتكار أفراد الطبقة العسكرية؛ وبذلك صار الالتزام الأسلوب المالي الرئيسي الذي حل محل نظام التيمار.", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["كاتب جلبي يشرع في إعادة كتابة «جهان نما» من جديد", "e9c68110"], "d": ["ترك كاتب جلبي تأليفه الأول ناقصًا، وشرع في أواخر 1654 في إعادة كتابة «جهان نما» من جديد. ولم تكتمل هذه النسخة الثانية أيضًا؛ فقد وقف الكتاب عند وان حين وافت المنية المؤلف سنة 1657، ولم يُطبع بهذه الحال إلا سنة 1732 على يد إبراهيم متفرقة.", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["إتمام جامع يني وفتحه للعبادة", "d6d86c82"], "d": ["أُتمّ بناء جامع يني، الذي ظل ناقصًا أكثر من ستين سنة، تحت إدارة رئيس المعماريين مريمچي مصطفى آغا الذي عيّنته خديجة تورخان والدة السلطان سنة 1661، وفُتح للعبادة بصلاة الجمعة التي أُقيمت فيه في 30 تشرين الأول/أكتوبر 1665.", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["محمد الرابع يقيم ألعاب الجريد أيامًا في حفل الختان في أدرنة", "3638a5b6"], "d": ["نظّم محمد الرابع في حفل ختان أبناء السلطان الذي أقامه في أدرنة سنة 1675 مباريات جريد استمرت أيامًا؛ وتُذكر هذه المباريات خاصة في مادة الجريد من TDV بوصفها من أبهر نماذج دعم القصر العثماني لرياضة الجريد.", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["الحافظ عثمان يطوّر طرازه الخاص في الخط", "93081cb3"], "d": ["طوّر الحافظ عثمان، الذي ينتمي إلى خط الشيخ حمد الله، سنة 1679 في الأقلام الستة طرازًا خاصًّا به سيُعرف لاحقًا باسم «مدرسة الحافظ عثمان». واستمر هذا الطراز حتى يومنا في فرعين منفصلين.", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["تعيين الحافظ عثمان معلم خط لمصطفى الثاني", "d976cda4"], "d": ["عُيّن الحافظ عثمان، الذي عُدّ أمهر خطاطي عصره، معلمَ خط لمصطفى الثاني الذي اعتلى العرش حديثًا سنة 1695. وقد خرّج في حياته نحو خمسين خطاطًا ونسخ 25 مصحفًا شريفًا.", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["وفاة عتري", "62750526"], "d": ["توفي بخورى زاده مصطفى عتري أفندي، أحد أعظم ملحني الموسيقى التركية، سنة 1711 بحسب المصادر القريبة من عصره. وترك بأعماله مثل تكبير سيكاه ونعت راست روائع موسيقى الجوامع والتكايا.", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["نديم يبرز رائدًا لشعر عصر التوليب", "d3c40dbb"], "d": ["طوّر نديم، طوال عصر التوليب (1718-1730)، أسلوبًا شعريًّا جديدًا برز بكمال التعبير والبحث عن البساطة والأسلوب الطريف. ويُعدّ هذا الأسلوب، الذي نما في محيط نوشهرلي داماد إبراهيم باشا، أكبر ممثلي تيار التوطين في الشعر الديواني.", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["لوني يصوّر «سورنامه وهبي»", "8c127866"], "d": ["صوّر لوني، نقاش القصر، «سورنامه وهبي» الذي يروي حفل ختان أبناء أحمد الثالث سنة 1720، بـ137 منمنمة. وخلافًا للنماذج السابقة لم يحصر الاحتفالات في ساحة أت ميداني، بل صوّرها في أركان مختلفة من المدينة، فبدأ بذلك فهمًا جديدًا في فن المنمنمات العثماني.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["استقرار نظام الكدك رسميًّا نظامًا للحرف قائمًا على الاحتكار", "cd0f79a7"], "d": ["بحسب TDV يُتتبع منذ 1727 التحول المنهجي الذي اكتسب فيه حق الكدك معنى «الاحتكار والامتياز ونوع من براءة الاختراع»؛ واستقر هذا النظام، الذي يمنح عددًا معينًا من الأشخاص حق العمل في الحرفة، في الدكاكين الوقفية غالبًا باسم «حق الكدك».", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["تدمير سعد آباد في ثورة باترونا خليل", "8a30f9a0"], "d": ["دُمّرت مئات الأجنحة والمباني في سعد آباد أثناء ثورة باترونا خليل التي اندلعت في 25 أيلول/سبتمبر 1730؛ ولم يستعد هذا المجمع، رمز عصر التوليب، بهاءه القديم بعد ذلك.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["وفاة نديم أثناء ثورة باترونا خليل", "06bf909e"], "d": ["توفي نديم، الذي كان مدرّسًا في مدرسة سكبان علي باشا حين اندلعت ثورة باترونا خليل، في الأيام التالية للثورة. ولا يُعرف يوم وفاته؛ لكن بما أن حجة القسام المتعلقة بتركته نُظمت في 15 ربيع الآخر 1143 (28 تشرين الأول/أكتوبر 1730)، فقد توفي قبل هذا التاريخ. وفي سبب الوفاة روايات مختلفة: فبعض المصادر تذكر أنه مات بمرض الخوف (علة وهمية) أو بداء الارتعاش الذي أصابه من الخمر والأفيون، ويكتب مستقيم زاده أنه صعد من الخوف إلى سطح داره أثناء الاضطراب وسقط منه فمات. وبوفاته انتهى فعليًّا بريق عصر التوليب الثقافي.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["وفاة لوني", "dd48b56e"], "d": ["توفي لوني، الذي يُعدّ آخر ممثلي فن المنمنمات العثماني الكبار، سنة 1732. ويوجد القسم الأكبر من أعماله اليوم في متحف قصر طوب قابي.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["وضع حجر أساس جامع نور عثمانية ومجمعه", "397ec798"], "d": ["وضع محمود الأول أساس مجمع نور عثمانية في 19 كانون الثاني/يناير 1749. ويُعدّ هذا البناء أول تطبيق كبير لطراز الباروك الأوروبي في العمارة العثمانية، ويفترق افتراقًا بيّنًا عن مخطط المجمع الكلاسيكي.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["افتتاح جامع نور عثمانية ومجمعه", "15d83731"], "d": ["جرى افتتاح المجمع، الذي بدأه محمود الأول ولم يُقدَّر له أن يشهد إتمامه، في 5 كانون الأول/ديسمبر 1755 في عهد أخيه عثمان الثالث. وسُمّي الجامع بهذا الاسم نسبةً إلى عثمان الثالث الذي أجرى الافتتاح، بمعنى «نور عثمان».", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["افتتاح المهندسخانة البحرية الهمايونية", "a2fab1cd"], "d": ["افتُتحت المهندسخانة البحرية الهمايونية، أول مدرسة هندسة بحرية حديثة في الدولة العثمانية، في 29 نيسان/أبريل 1775 في عهد عبد الحميد الأول وفي صدارة الصدر الأعظم درويش محمد باشا، بحسب الوثائق الأرشيفية الفرنسية.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["استحداث نظام الأسهم", "eabd8ece"], "d": ["في مواجهة عبء التعويض البالغ 7,5 مليون قرش الذي فرضته معاهدة كوچوك قاينارجه، استُحدث نظام الأسهم سنة 1775. وفي هذه الطريقة التي صُممت لتجاوز حدود المالكانة، يُقسَّم إيراد المقاطعة إلى حصص، وكان يمكن، على خلاف المالكانة، أن يصير النساء وغير المسلمين وعامة الناس أصحاب حصص.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["ولادة حمامي زاده إسماعيل ددة أفندي", "c033f039"], "d": ["وُلد حمامي زاده إسماعيل ددة أفندي، أحد أغزر ملحني الموسيقى التركية إنتاجًا، في 9 كانون الثاني/يناير 1778 في حي شهزاده باشي بإسطنبول. ولحّن في حياته أكثر من 500 عمل، وصل منها إلى يومنا نحو 294.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["بدء بناء المهندسخانة البرية الهمايونية", "4f5d521a"], "d": ["بدأ في 14 تموز/يوليو 1793 بناء المهندسخانة البرية الهمايونية، إحدى أهم مؤسسات إصلاحات النظام الجديد لسليم الثالث. وانتهى بناء المبنى في أيلول/سبتمبر 1795 وفُتح للتعليم؛ وكانت المؤسسة ثاني مدرسة هندسة عسكرية عثمانية، اتُّخذت الأكاديميات العسكرية في أوروبا مثالًا لها.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["سليم الثالث يبدأ إلغاء احتكار بعض طوائف الحرف", "008f4a7d"], "d": ["بحسب مادة الأصناف في TDV، قام في نظام الطوائف العثماني المتداخل مع تنظيم الأخية منذ نشأته مسؤولون مثل «أخي بابا» و«الشيخ» بقيادة الطوائف حتى مطلع القرن التاسع عشر؛ ولما رفعت الطوائف الأسعار فوق النرخ بالاحتكار في القرن الثامن عشر فخلق ذلك ضغطًا اقتصاديًّا، بدأ سليم الثالث ابتداءً من 1794 يلغي احتكار طوائف المواد الغذائية الأساسية.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["ضم ددة أفندي إلى القصر مصاحبًا شهرياريًّا", "0cb99ac3"], "d": ["لفت ددة أفندي انتباه السلطان في عهد سليم الثالث بتلحين من مقام بوسليك، فضمّه محمود الثاني سنة 1812 إلى «مصاحبي شهرياري» (رفقاء مجلس السلطان الخاص)، وارتقى بعد قليل إلى رئاسة المؤذنين.", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["إجراء أول تعداد سكاني منتظم في الدولة العثمانية", "4f004c6c"], "d": ["أجرى محمود الثاني لأول مرة في أواخر 1830 تعدادًا منتظمًا بقصد تحديد السكان الذين سيُجنَّدون؛ وسُجّل الذكور فقط وحُدّد عددهم في الأناضول والروملي بنحو 7,5 مليون نسمة. ولم يتسنَّ إتمام التعداد في بعض المناطق مثل أرضروم ووان إلا سنة 1836.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["تأسيس فسخانة عامرة", "971ab85a"], "d": ["لتلبية حاجة جيش العساكر المنصورة المحمدية، الذي أُسس بعد إلغاء الأوجاق الإنكشاري سنة 1826، إلى الطرابيش، بدأ إنتاج الطرابيش سنة 1833 في ميدان الجُند في قدرغة برأسمال 1,5 مليون قرش. ونُقلت المنشآت سنة 1839 إلى قصر خديجة سلطان في أيوب؛ وشكّلت الفسخانة أساس الصناعة النسيجية العثمانية.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["المدرسة الطبية تتخذ اسم «مكتب الطبية العدلية الشاهانية»", "187d60f3"], "d": ["اتخذت المدرسة الطبية، التي انتقلت إلى مبنى مكتب أغوات الأندرون في غلطة سراي، اسم «مكتب الطبية العدلية الشاهانية» في 14 أيار/مايو 1839 بزيارة محمود الثاني؛ وبذلك سُجّلت المؤسسة رسميًّا بهوية مدرسة عسكرية إدارية.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["وفاة ددة أفندي في منى أثناء الحج", "c3e613a2"], "d": ["توفي حمامي زاده إسماعيل ددة أفندي في 29 تشرين الثاني/نوفمبر 1846 بعد أن أصابه الكوليرا في منى حيث ذهب لأداء فريضة الحج. وبوفاة هذا الفنان الذي لحّن بين 1824 و1839 سبعة آيين مولوية مختلفة، أُغلقت مرحلة من الموسيقى العثمانية الكلاسيكية.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["قبول قانون التجارة لسنة 1850", "8ac085fd"], "d": ["في إطار الإصلاحات القانونية لعهد التنظيمات، أُخذت قوانين جديدة من الدول الغربية بالترجمة والاقتباس: فدخل قانون العقوبات حيز التنفيذ سنة 1840، وقانون التجارة سنة 1850، وقانون الأراضي سنة 1857. وكان قانون التجارة أول تدوين حديث للقانون التجاري العثماني.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["بدء موجة هجرة كبرى لتتار القرم وشعوب القوقاز إلى الأراضي العثمانية", "8832c06d"], "d": ["بعد وقوع الشيخ شامل في أسر الروس سنة 1859، بدأ عدد كبير من المهاجرين الشركس والنوغاي، إلى جانب تتار القرم، يهاجرون من القوقاز إلى الأراضي العثمانية. واستمرت موجة الهجرة هذه بكثافات متفاوتة حتى ما بعد الحرب العثمانية الروسية 1877-1878.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["تأسيس لجنة المهاجرين", "9717e77e"], "d": ["أسست الحكومة العثمانية في 16 كانون الثاني/يناير 1860 لجنة المهاجرين لإدارة موجة الهجرة المتزايدة من القوقاز. ونسقت اللجنة أعمال التوطين في الأناضول والبلقان وسوريا، وظلت تعمل حتى 1875.", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["إعادة هيكلة البنك العثماني ليصبح البنك العثماني الشاهاني (البنك العثماني)", "c3530456"], "d": ["أُسس في 1856، بعد حرب القرم، البنك العثماني، ومقره لندن ورأسماله إنجليزي، لإدارة مدفوعات الدين الخارجي. وفي 1863 أُذن لمجموعة فرنسية إنجليزية مشتركة بإنشاء بنك جديد باسم البنك العثماني الشاهاني (البنك العثماني)؛ وحصلت المؤسسة لاحقًا أيضًا على صلاحية إصدار أوراق النقد.", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["تأسيس جمعية التدريس الإسلامية", "77ad553a"], "d": ["أُسست جمعية التدريس الإسلامية في 30 آذار/مارس 1864 لتتولى تعليم الصبية المتدربين المسلمين الفقراء؛ وهذه المبادرة الأهلية المدنية نموذج رائد لتحول تقليد المؤسسات الخيرية إلى مشروع مدرسة حديثة. وستفتتح الجمعية دار الشفقة بعد تسع سنوات.", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["تنظيم نظام المختارية ومجلس الشيوخ بنظامنامة الولايات لسنة 1864", "1a2e8cf2"], "d": ["أُعيد بنظامنامة الولايات لسنة 1864 تنظيم إدارة القرى؛ وقُبل أن تنتخب كل طائفة مختارها ومجلس شيوخها في القرى التي يعيش فيها المسلمون وغير المسلمين معًا. وبذلك نال مجلس الشيوخ لأول مرة مكانًا رسميًّا في إدارة القرية/المحلة.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["ذروة التهجير الشركسي الكبير", "b2ab1874"], "d": ["في أثناء احتلال روسيا القوقاز بين 1858 و1878، وبأشد صوره في 1861-1864، هُجّر قسرًا من 1,2 إلى 1,5 مليون شركسي إلى الأراضي العثمانية. وبحسب TDV يصف عدد كبير من الباحثين هذه الواقعة بأنها «أول حركة تطهير عرقي في التاريخ الحديث».", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["صدور نظامنامة المعارف العمومية لسنة 1869", "787f6022"], "d": ["كانت نظامنامة المعارف العمومية الصادرة في 1 أيلول/سبتمبر 1869 أول نص شامل ينظم التعليم العام في الأقاليم والمركز. وأُسس بالنظامنامة مجلس المعارف الكبير؛ وبدأ بهذا التنظيم إخراج مكاتب الصبيان من كونها مرحلة تعليم ديني خالص وإعادة هيكلتها لتتجه إلى تعليم القراءة والكتابة.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["بدء التعليم في مدرسة دار الشفقة", "525c457c"], "d": ["بدأت دار الشفقة، التي أسستها جمعية التدريس الإسلامية، التدريس فعليًّا في 28 حزيران/يونيو 1873 لتعليم الأطفال المسلمين الأيتام والفقراء مجانًا بنظام داخلي؛ وحُدّد سن القبول بعشر سنوات كحد أقصى.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["زلزال إسطنبول لسنة 1894", "7ae7f648"], "d": ["ضرب الزلزال الذي وقع قبالة خليج إزميد في 10 تموز/يوليو 1894 إسطنبول ضربة شديدة؛ وتضررت جوامع كثيرة ومبانٍ تاريخية، منها أسوار إسطنبول. وتعدّ مادة الزلزلة في TDV هذا الزلزال مع زلازل 1509 و1719 و1766 من الزلازل التي تسببت في خسائر كبيرة في الأرواح والأموال في منطقة مرمرة.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["افتتاح دار العجزة", "a30baf31"], "d": ["أعدّت دار العجزة بناءً على أوامر أصدرها عبد الحميد الثاني ابتداءً من 1890، وافتتحها الصدر الأعظم خليل رفعت باشا في 2 شباط/فبراير 1896. وكانت المؤسسة التي تؤوي الأطفال المشردين والمسنين والمحتاجين أكبر مجمع للمساعدة الاجتماعية في عصرها، بمستشفى من 200 سرير وورش ودور عبادة منفصلة كالجامع والكنيسة والمعبد اليهودي.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["إعادة تأسيس دار الفنون الشاهانية مؤسسةً دائمة", "7d6d8fc4"], "d": ["أُعيد تأسيس دار الفنون في 31 آب/أغسطس 1900 باسم دار الفنون الشاهانية مؤسسةً دائمة، بعد محاولتين فاشلتين سابقتين (1863 و1870)؛ وتصف TDV هذا التاريخ بأنه الأساس المباشر لنظام الجامعات التركي الحالي.", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["السربداريون يستولون على سبزوار — أول دولة في خراسان بعد الإيلخانيين", "af997fec"], "d": ["لما انهارت السلطة المركزية الإيلخانية بوفاة أبي سعيد (30 تشرين الثاني/نوفمبر 1335)، انفجر في باشتين الغضب المتراكم في خراسان على جباة الضرائب: فثار عبد الرزاق في 13 آذار/مارس 1337، واستولى على سبزوار في 9 أيلول/سبتمبر 1337 (12 صفر 738). واسم «السربدار» — «رأسه على المشنقة» — هو من كلامهم هم، وفيه يعبّرون عن استعدادهم للشنق إن هُزموا.", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["السادة المرعشيون يستولون على آمل — سيادة السادة في مازندران", "c0e03266"], "d": ["سار السيد قوام الدين المرعشي على الطريق الذي فتحه السربداريون في خراسان، فاستولى على آمل سنة 760 (1359) وأسس دولة للسادة على الساحل الجنوبي لبحر قزوين. وامتدت الأسرة إلى ساري وبارفروش وما حولهما؛ وتزعزعت في حملات تيمور، وفُككت في عهد الصفوي الشاه عباس الأول.", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["تأسيس أسرة كاركيا في جيلان — آخر الحكام المستقلين على ساحل بحر قزوين", "6e5f9db7"], "d": ["عاد علي كيا مع أسرته إلى جيلان وأسس سنة 773 (1371-1372) سيادة كاركيا التي مركزها لاهيجان؛ وحكمت الأسرة الساحل الجنوبي الغربي لبحر قزوين أكثر من قرنين، حتى ضم الصفوي الشاه عباس الأول المنطقة سنة 1592.", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["انتقال سيادة الداجو في دارفور إلى التنجر", "6eb22a2a"], "d": ["بحسب مادة دارفور في موسوعة TDV الإسلامية فإن قبيلة الداجو هم أول من استقر في المنطقة وأول من أسس دولة فيها؛ وقد فقد الداجو، الذين سيطروا عليها طوال القرنين الثالث عشر والرابع عشر، السيادة التجارية للتنجر، وفي القرن الخامس عشر انقلب الوضع، وبخاصة في الوسط، لمصلحة التنجر انقلابًا تامًّا.", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["إسبانيا تستعيد صخرة بادس (بينيون دي فيليز)", "0dc52728"], "d": ["تسجل مادة السعديين في TDV أن استيلاء الإسبان على بادس كان ضربة قاسية للملاحة المغربية (1564). وكان هذا الموقع الصخري على الساحل المغربي الشمالي سندًا للقرصنة في غرب المتوسط وللتنافس العثماني الإسباني.", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["التخلي عن العرائش لإسبانيا", "7b8f6e27"], "d": ["في سنوات الحرب الأهلية التي تفتتت فيها الأسرة السعدية، تُرك ميناء العرائش على الساحل الأطلسي لإسبانيا. وتسجل مادة السعديين في TDV أن البلاد انقسمت في هذه الفترة إلى إمارتين: مراكش (الجنوب) وفاس (الشمال)، وأن الأطراف المتنازعة على العرش طلبت العون من الخارج. وسيبقى الميناء في يد الإسبان قرابة ثمانين سنة، ثم يستعيده مولاي إسماعيل سنة 1689.", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["وقوع المعمورة (المهدية) في أيدي الإسبان", "c8fd494e"], "d": ["أخذ الإسبان سنة 1614 ميناء المعمورة (المهدية) عند مصب نهر سبو وحصّنوه باسم سان ميغيل دي ألترامار. وتسجل مادة مولاي إسماعيل في TDV أن الميناء استُعيد من يد الإسبان في سنة 1092 (1681) بهجوم مباغت — أي أن السيطرة الإسبانية دامت سبعًا وستين سنة.", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["نهاية الأسرة السعدية — بداية العهد العلوي (الفيلالي) في المغرب", "b1afa579"], "d": ["تعرّف موسوعة TDV الإسلامية السعديين بأنهم «أسرة إسلامية حكمت في المغرب (1511-1659)». وانتهت الأسرة، التي أنهت سنة 1549 سيادة الوطاسيين ووحدت المغرب كله، وأبادت سنة 1578 الجيش البرتغالي في وادي المخازن، ولم تخضع للعثمانيين في أي عهد، سنة 1659 بعد صراعات طويلة على العرش. وحل محلها الأشراف العلويون (الفيلاليون) القادمون من تافيلالت؛ ودخل مولاي رشيد مدينة فاس سنة 1666 فرسّخ الأسرة الجديدة، وطهّر أخوه مولاي إسماعيل المواقع الأوروبية على الساحل الأطلسي.", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["إسبانيا تحتل جزر الحسيمة", "954ca998"], "d": ["احتل الأسطول الإسباني سنة 1673 جزر الحسيمة على ساحل المتوسط. وهي، مع بادس وسبتة، من المواقع التي احتفظت بها إسبانيا على ساحل المغرب الشمالي وبقيت في يدها حتى اليوم. وفي السنة نفسها دخل مولاي رشيد، أخو مولاي إسماعيل، مراكش ونال البيعة من الناس، وترسخت سيادة الفيلاليين في الجنوب — وهذه الخسارة على الساحل تدل على أن الوحدة الداخلية لم يكن لها بعدُ ما يقابلها على الجبهة الخارجية.", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["مولاي إسماعيل يستعيد العرائش من الإسبان", "a54bc6ee"], "d": ["عبارة مادة مولاي إسماعيل في TDV صريحة: «استعادوا العرائش من الإسبان في 1100 (1689) وغنموا 200 مدفع، وبعد سنتين استعادوا أصيلة». وهذه إحدى حلقات سلسلة تطهير الساحل التي قام بها السلطان الفيلالي — فاستُعيدت طنجة من الإنجليز سنة 1678، والمعمورة سنة 1681، والعرائش سنة 1689، وأصيلة سنة 1691. وهكذا عاد إلى المغرب الميناء الذي تُرك قبل ثمانين سنة في الحرب الأهلية السعدية.", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["تأسيس سلطنة دارفور — الأسرة الكيرا وسليمان سولونج", "0fc1c112"], "d": ["بحسب TDV يقع تأسيس سلطنة دارفور بعد الفوضى التي أعقبت اجتياح بومو القصير للمنطقة في أواخر القرن السابع عشر. وانتزع الفور السيادة من الداجو والتنجر بقيادة سلالة كيرا برئاسة سليمان سولونج، وأقاموا إدارة راسخة. وحكم سليمان سولونج بين 1695 و1715. وراسل سلاطين دارفور الباب العالي في القرون التالية؛ وأقرّ عبد المجيد وعبد العزيز حكمهم.", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["إعلان الجمهورية الأولى في فرنسا — نهاية الملكية", "d53d49b0"], "d": ["أُلغيت الملكية في الجلسة الأولى للمؤتمر الوطني وأُعلنت الجمهورية الأولى في اليوم التالي؛ وبدأت السنة الأولى من التقويم الجديد من هذا اليوم. وبالنسبة إلى العثمانيين لم يتغير المخاطَب لكن تغير جنس المخاطَب: ففي سنوات النظام الجديد لسليم الثالث لم تعد فرنسا أسرة حاكمة بل نظامًا، وكان الذي سينزل إلى مصر سنة 1798 هو جيش ذلك النظام.", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["سقوط القبائل الكبرى — أسر للا فاطمة نسومر", "0f61ff08"], "d": ["تسجل مادة الجزائر في TDV أن احتلال منطقة القبائل الجبلية (بلاد القبائل) بعد حملات 1853 و1854 و1857 أتمّ في الجملة حركة فرنسا لاحتلال الجزائر. وكسرت حملة 1857 خط تيزي وزو وأقبو؛ وأُسرت للا فاطمة نسومر، رمز المقاومة. وبذلك خمد آخر مركز كبير للمقاومة ظل قائمًا بعد استسلام الأمير عبد القادر سنة 1847.", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["احتلال الفرنسيين لعين صالح (تيديكلت)", "1e28d1d0"], "d": ["أخذت القوات الفرنسية في 29 كانون الأول/ديسمبر 1899 عين صالح، مركز مجموعة واحات تيديكلت في وسط الصحراء. وهذه أول خطوة كبيرة في التوسع الفرنسي المتجه جنوبًا من ساحل الجزائر وقد امتد إلى الصحراء؛ وستسلك توات وقورارة الطريق نفسه خلال سنتين.", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["ضم واحات توات وقورارة وتيديكلت إلى فرنسا", "d412838b"], "d": ["ضُمت حزام واحات توات وقورارة وتيديكلت في جنوب غرب الجزائر رسميًّا إلى فرنسا في 21 شباط/فبراير 1901. وبذلك انضمت إلى الجزائر عقدة طرق القوافل هذه — بما فيها أدرار وتيميمون ورقان وبني عباس — التي كان سلطان المغرب يدّعي فيها حقًّا اسميًّا؛ وهذه بداية الخلاف الحدودي بين المغرب والجزائر الفرنسية.", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["إقامة مخفر فرنسي في بشار (كولومب بشار)", "4d44d252"], "d": ["أخذت القوات الفرنسية في 11 تشرين الثاني/نوفمبر 1903 واحة بشار على حدود المغرب وجعلتها مخفرًا متقدمًا باسم كولومب بشار. وهذه الخطوة، التي جاءت بعد سنتين من ضم حزام توات، من آخر حلقات تقدم فرنسا من الجزائر نحو المغرب؛ وتمهد الطريق إلى فرض الحماية على المغرب سنة 1912.", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["تأسيس إمارة موسكو — دانييل الأول", "49549309"], "d": ["بدأ دانييل، أصغر أبناء ألكسندر نيفسكي، يحكم موسكو إمارة مستقلة. وكانت موسكو في ذلك العهد مركزًا صغيرًا لا شأن له في أراضي فلاديمير-سوزدال؛ وتعدّ الكتابة التاريخية الروسية هذا التاريخ نقطة بداية صعودها اللاحق.", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["تأسيس إمارتي قره سي والحميديين", "3905da93"], "d": ["بحسب مادة القره سي أوغلو في TDV، أعلن قره سي بك استقلاله في ثغر السلاجقة الذي تفكك بوفاة أبيه قلم بك، واتخذ بالق أسير مركزًا له ابتداءً من 696 (1296-1297)، وانتزع في وقت قصير من البيزنطيين ميسيا بأكملها، بما فيها أردك وبيغا وأدرميت وبرغاما. وفي السنة نفسها (1297) أسس حميد بك إمارة الحميديين متخذًا أولوبورلو مركزًا لحكمه؛ وضُمت إسبارطة وبوردور وإيردير ويالواج من منطقة الثغر السلجوقي المتفككة إلى حدود الإمارة الأولى. والإمارتان كلتاهما نتاج الانهيار نفسه في غرب الأناضول — تفكك السلطة المركزية السلجوقية.", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["أمير موسكو دانييل يضم كولومنا وسربوخوف إلى موسكو", "6d82dccd"], "d": ["أخذ دانييل كولومنا (تنازل أمير ريازان الأسير عن القلعة ليُفرج عنه) وسربوخوف من إمارة ريازان؛ وبلغت موسكو نهر أوكا، وكان ذلك أول توسع إقليمي لإمارة موسكو.", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["موجايسك تؤخذ من إمارة سمولنسك وتُضم إلى موسكو", "462055a0"], "d": ["أخذت إمارة موسكو موجايسك في أعالي حوض نهر موسكو من سمولنسك، فقرّبت حدودها الغربية من ليتوانيا.", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["إمارة بولوتسك تنتقل إلى دوقية ليتوانيا الكبرى", "04a26a6f"], "d": ["بقيت بولوتسك وفيتبسك وما حولهما حتى 1307 في الأسرة الأميرية الروسية؛ وبهذا الانتقال بان توسع ليتوانيا نحو الشرق قبل غيديميناس (تاريخ هوية الأطلس 1307؛ والانتقال الفعلي لفيتبسك نحو 1320 موضع خلاف).", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["تأسيس إمارة آيدين أوغلو — أخذ إزمير وآياصولوغ وتيره", "69a021ae"], "d": ["بحسب مادة آيدين أوغلو في TDV انتزع مبارز الدين غازي محمد بك هذه المنطقة من ثغر ساسا بك، من أمراء الثغر الجرميانيين، وصار سيدًا على آيدين إيلي سنة 1308؛ وفتح القسم الإسلامي من إزمير مع آياصولوغ (سلجوق) وتيره وبوديميا. واتخذ آياصولوغ قاعدة بحرية، ووزع الأراضي التي أخذها بين أبنائه الخمسة — وستصير الإمارة في العقود التالية، ولا سيما في عهد ابنه عمر بك، قوة حاسمة في الملاحة في بحر إيجه.", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["الانتهاء الفعلي للدولة السلجوقية في الأناضول — الإدارة المباشرة للإيلخانيين", "00f85ecb"], "d": ["بحسب مادة مسعود الثاني في TDV، يُعدّ غياث الدين مسعود الثاني، الذي توفي في قيصرية سنة 708 (1308) بعد مرض طويل، بحسب الرأي المقبول عمومًا آخر سلاطين الدولة السلجوقية في الأناضول — فالمرشحون الذين أُجلسوا على العرش بعد وفاته لم ينالوا اعتراف السلطات الداخلية ولا الإيلخانيين. وكانت المنطقة تُدار فعليًّا بموظفي الإيلخانيين طوال سلطنة مسعود؛ وبوفاته فقدت هذه الإدارة المباشرة غطاءها الشكلي أيضًا في مراكز مثل قونية ونيغدة وآقسراي.", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["امتداد إمارة چاندار أوغلو إلى قسطموني وچانكري وبارتين وصفرانبولو", "64e39ad0"], "d": ["بحسب مادة چاندار أوغلو في TDV، أسس الإمارة في أوائل القرن الرابع عشر في محيط قسطموني وسينوب شمس الدين يمان چاندار، الذي أقطعه الحاكم الإيلخاني كيخاتو أفلاني وما حولها؛ ولا يُعرف تاريخ التأسيس بدقة لقلة المصادر. ويُذكر خلف چاندار، سليمان بك، بوصفه حاكمًا حلّ محل إمارة چوبان أوغلو — أي أن محيط قسطموني وچانكري انتقل من چوبان أوغلو، وخط بارتين-صفرانبولو-أفلاني من الإدارة المباشرة للإيلخانيين، إلى چاندار أوغلو.", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["فتح فرسان القديس يوحنا (الاسبتارية) لرودس والجزر الاثنتي عشرة", "67885b4b"], "d": ["تسجل مادة رودس في TDV أن الجزيرة صارت في يد فرسان القديس يوحنا (الاسبتارية/الإسبيتارية) سنة 1309؛ ويفصّل التاريخ الاسبتاري المعياري (انظر J. Riley-Smith, The Knights Hospitaller) أن الحصار بدأ في صيف 1306، وأن مدينة رودس، التي صمدت طويلًا بتعزيزات بيزنطية، لم تسقط إلا في 15 آب/أغسطس 1310 أمام قوات المعلم الأكبر فولك دي فيلاريه. وستكون الجزيرة منذ هذا التاريخ مركز الفرسان حتى الفتح العثماني سنة 1522، وانتقلت الجزر الاثنتا عشرة المحيطة بها في العملية نفسها من البيزنطيين إلى سيادة الاسبتارية.", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["فرسان ليفونيا يستعيدون قلعة دونابورغ من ليتوانيا", "92119516"], "d": ["كان الليتوانيون قد أخذوا يرسيكا نحو 1281 وبادلوها بقلعة دونابورغ التابعة للأخوية. وعادت القلعة سنة 1313 إلى فرسان ليفونيا وبقيت مركز كومتورية للأخوية.", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["أخذ فرسان القديس يوحنا لإستانكوي (كوس)", "445666f7"], "d": ["بحسب مادة إستانكوي في TDV أخذ فرسان القديس يوحنا بعد استقرارهم في رودس إستانكوي أيضًا (1315) وبنوا قلاعًا جديدة. وبذلك دخلت الجزيرة في سيادة الفرسان التي دامت حتى 1523؛ ولم تفصّل TDV في أي إدارة كانت كوس بعد سقوط مدينة رودس سنة 1310.", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["المطرانية تنتقل إلى موسكو", "d20099f8"], "d": ["نقل المطران بيتر، رأس الكنيسة الأرثوذكسية الروسية، مركزه الديني إلى موسكو. وكانت هذه بداية صعود موسكو لا سياسيًّا فحسب بل مركزًا دينيًّا أيضًا، وقوّت شرعية الإمارة.", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["أخوية ليفونيا تصبح صاحبة السيادة على مدينة ريغا", "21453047"], "d": ["هُزمت سنة 1330 رئاسة أساقفة ريغا والمدينة، اللتان حاربتا الأخوية بدعم من الدوقين الأكبرين الليتوانيين فيتينيس وغيديميناس؛ وصارت أخوية ليفونيا صاحبة السيادة على المدينة. وبمعاهدة ساراسبيلس لسنة 1452 دخلت ريغا في سيادة مشتركة للأخوية ورئيس الأساقفة.", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["تأسيس إمارة إرتنا — وسط الأناضول بعد الإيلخانيين", "a67bacd9"], "d": ["بحسب مادة الإرتنا أوغلو في TDV حوّل علاء الدين إرتنا، وهو موظف إيلخاني من أصل أويغوري، نيابة الإيلخانيين في الأناضول إلى إدارة مستقلة فعليًّا بعد وفاة الحاكم الإيلخاني أبي سعيد بهادر خان سنة 1335؛ فظهر أولًا بصفة نائب السلطان المملوكي، وأسقط اسم المملوك من الخطبة سنة 1340، وأعلن استقلاله التام نحو 1341. وأقامت الإمارة، التي كان مركزها أولًا سيواس ثم قيصرية، حتى وفاته (1352) سيادة واسعة في وسط الأناضول شملت أماسيا وتوقات وچوروم ونيغدة وآقسراي وأرزنجان، وأنهاها القاضي برهان الدين سنة 1381.", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["استيلاء آل هابسبورغ على كارنيولا وكارنتيا (ليوبليانا)", "039918d3"], "d": ["بوفاة دوق كارنتيا وكونت تيرول هاينريش السادس بلا وريث في 2 نيسان/أبريل 1335 في قلعة تيرول، وبموجب اتفاق سري عُقد مع لودفيغ البافاري في 23 تشرين الثاني/نوفمبر 1330، أخذ الأخوان الهابسبورغيان ألبرشت الثاني وأوتو الرابع دوقية كارنتيا وكارنيولا التابعة لها (المنطقة التي تقع ليوبليانا اليوم داخلها) بمرسوم إمبراطوري؛ وبقيت تيرول منفصلة عبر ابنة هاينريش. وكانت هذه من أولى الخطوات الكبرى في توسع آل هابسبورغ في منطقة الألب، وستبقى كارنيولا في يد الهابسبورغ/النمسا حتى 1918 (مع انقطاعات).", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["تأسيس الدولة الجلائرية — أذربيجان بعد الإيلخانيين", "a13ada90"], "d": ["بحسب مادة الجلائريين في TDV استفاد حسن بزرك، حفيد الأمير الإيلخاني نويان، من صراعات العرش التي اندلعت بوفاة الحاكم الإيلخاني أبي سعيد بهادر خان، فأسس سنة 1340 دولة مستقلة مركزها تبريز. وبذلك كان الجلائريون أول أسرة كبرى ملأت الفراغ الذي خلّفه الإيلخانيون في أذربيجان وما حولها؛ وفي عهد خلفه أويس (1356-1374) ستتسع أراضيهم حتى الموصل وديار بكر.", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["تأسيس الإمارة الكبرى نيجني نوفغورود-سوزدال — الخان يمنح قسطنطين فاسيليفيتش ياركليغ (براءة حكم)", "c69f5198"], "d": ["منح خان القبيلة الذهبية أوزبك (جاني بك في الهوية) أمير سوزدال قسطنطين فاسيليفيتش إمارة نيجني نوفغورود-غورودتس؛ وصارت الإمارة منافسة لموسكو، وضمها فاسيلي الأول إلى موسكو سنة 1392.", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["الدنمارك تبيع شمال إستونيا (ريفال ونارفا) لأخوية ليفونيا", "6861ba55"], "d": ["باعت مملكة الدنمارك أراضيها في شمال إستونيا مع ريفال ونارفا إلى أخوية ليفونيا. وبقيت المنطقة في يد الأخوية حتى حرب ليفونيا.", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["معاهدة بولوتوفو — نوفغورود تعترف باستقلال بسكوف", "08eca44d"], "d": ["اعترفت نوفغورود ببسكوف «أخًا أصغر»؛ وعاشت بسكوف جمهورية مدينة مستقلة بفيتشيها وبوساد نيكها حتى ضُمت إلى موسكو سنة 1510.", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["فاسيلي الأول يضم إمارة نيجني نوفغورود-سوزدال إلى موسكو", "5ecf441b"], "d": ["ضم فاسيلي الأول، بالياركليغ الذي نالته من الخان توختاميش، نيجني نوفغورود وغورودتس وسوزدال إلى موسكو؛ وبدأ انفتاح موسكو على حوضي الفولغا وأوكا.", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["فيتاوتاس يأخذ سمولنسك — إمارة سمولنسك تُضم إلى ليتوانيا", "1a68300c"], "d": ["استولى فيتاوتاس على سمولنسك؛ وبقيت المدينة في دوقية ليتوانيا الكبرى حتى انتقلت إلى موسكو سنة 1514.", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["وقوع بغداد في يد قره قويونلو — هزيمة السلطان الجلائري أحمد", "a42ebe92"], "d": ["بحسب مادة قره قويونلو في TDV هزم قرة يوسف السلطان الجلائري أحمد هزيمة ثقيلة قرب تبريز في 28 ربيع الآخر 813 (30 آب/أغسطس 1410)؛ وبعد وفاة السلطان أحمد نصّب ابنه پير بوداق سلطانًا في تبريز سنة 814 (1411)، وفتح ابنه الأكبر شاه محمد بغداد في السنة نفسها. وبذلك دخلت بغداد، التي كانت عاصمة الجلائريين قرابة قرن، مع خط البصرة-الموصل-كركوك المحيط بها، في سيادة قره قويونلو.", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["أرزنجان وكماخ تنتقلان إلى آق قويونلو — قره يولوك عثمان بك", "122460d4"], "d": ["بعد وفاة قرة يوسف صار يار علي، حفيد مطهرتن، واليًا على المدينة بطلب من أهل أرزنجان. وفي زمنه أخذ أمير آق قويونلو قره يولوك عثمان أرزنجان وضمها إلى أراضي آق قويونلو. ومنذ هذا التاريخ صارت أرزنجان مكانًا يتبادله تارة آق قويونلو وقره قويونلو، وتارة أمراء آق قويونلو بعضهم مع بعض.", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["تأسيس خانية قازان — انفصال أولوغ محمد خان عن القبيلة الذهبية", "335a7408"], "d": ["بحسب مادة خانية قازان في TDV، لما فقد أولوغ محمد خان عرشه في ساراي، عاصمة القبيلة الذهبية، انسحب مع أسرته ونحو 3000 جندي أولًا إلى بيليف، وقاتل الأمير الروسي فاسيلي الثاني في 1437-1438، ثم استقر في مدينة قازان؛ وبدعم من الأهالي وضع فيها أسس خانية جديدة. وتذكر TDV أن عملية التأسيس اكتملت بين 1437 و1445، وأن الخانية نالت الاستقلال التام ابتداءً من 1445 — والخريطة تعتمد بداية هذه العملية، أي سنة 1438 التي استقر فيها أولوغ محمد في قازان.", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["تأسيس خانية القرم — استقلال حاجي كراي عن القبيلة الذهبية", "5728223e"], "d": ["بحسب مادة القرم في TDV ظهرت خانية القرم نتيجة تفتت القبيلة الذهبية بصراعاتها على العرش في النصف الثاني من القرن الرابع عشر؛ وأقدم عملة سكّها المؤسس الحقيقي للخانية حاجي كراي تحمل تاريخ 845 (1441-1442)، وهذا يُعدّ التاريخ الرسمي لتأسيس الخانية. وفي السنة نفسها رسّخ حاجي كراي مكانته في القرم بإقامة صداقة مع موسكو، وانضمت إلى صفّه أسر الأمراء المحليين وفي مقدمتها قبيلة شيرين.", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["جهان شاه يأخذ أرزنجان — سيادة قره قويونلو", "0c928cc4"], "d": ["أرسل حاكم قره قويونلو جهان شاه سنة 854 (1450) جيشًا إلى أرزنجان وأخذ المدينة من آق قويونلو. وأدت هذه الخسارة إلى تباعد ما بين أمير آق قويونلو جهانكير ميرزا وأخيه حسن بك (أوزون حسن).", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["استيلاء جهان شاه القره قويونلي على إيران التيمورية (الري وأصفهان وفارس وكرمان)", "c6fbb3f5"], "d": ["بحسب مادة قره قويونلو في TDV وضع حاكم قره قويونلو جهان شاه، مستفيدًا من صراعات العرش بين الأمراء التيموريين، ولايات الري وأصفهان وفارس وكرمان تحت إدارته في سنتي 856-857 (1452-1453)؛ وهذه ذروة عملية التوسع التي بدأت بعد وفاة شاه رخ ميرزا سنة 1447 وافتتحها ضم السلطانية وقزوين. وبذلك انتقلت أراضي التيموريين في جنوب إيران ووسطها إلى قره قويونلو؛ وسيبلغ سلطان جهان شاه سنة 1466 اتساعًا يشمل أذربيجان وأران والعراق العجمي والعراق العربي وفارس وكرمان وشرق الأناضول.", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["استعادة إنجلترا لبوردو — حملة جون تالبوت الأخيرة في غاسكونيا", "01b2b7be"], "d": ["سلّمت بوردو، التي فُقدت لمصلحة الفرنسيين سنة 1451، نفسها في ليلة 22-23 تشرين الأول/أكتوبر 1452 إلى الجيش الإنجليزي بقيادة القائد المسن جون تالبوت، بعد أن ثار أهلها على الحامية الفرنسية وفتحوا الأبواب؛ وكان هذا آخر انتصار لإنجلترا في غاسكونيا في حرب المئة عام، وقصير العمر. وستعود بوردو بعد سنة، إثر معركة كاستيون، إلى فرنسا عودة دائمة.", "f6945d27"]},
"OLAYLAR_EK16:1453-10-19:0":{"b": ["عودة بوردو الدائمة إلى فرنسا — النهاية الفعلية لحرب المئة عام", "b0a86f6c"], "d": ["انهارت المقاومة الإنجليزية في غاسكونيا بوفاة جون تالبوت وفناء جيشه في معركة كاستيون في 17 تموز/يوليو 1453؛ واستسلمت بوردو المحاصَرة للقوات الفرنسية في 19 تشرين الأول/أكتوبر 1453. ويُعدّ هذا الاستسلام اللحظة التي انتهت فيها حرب المئة عام، التي دامت 116 سنة، فعليًّا (لم تُوقَّع معاهدة سلام رسمية قط)، وقلّص سيادة إنجلترا في القارة الأوروبية إلى كاليه.", "1c632d46"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["أوزون حسن يستعيد أرزنجان — آق قويونلو من جديد", "550d010a"], "d": ["هزم أوزون حسن قره قويونلو وأعاد أرزنجان إلى سيادة آق قويونلو. وبقيت المدينة ضمن حدود آق قويونلو بعد معركة أوتلوق بلي سنة 1473 أيضًا.", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["معاهدة تورن الثانية — دانزيغ (غدانسك) وبروسيا الغربية تُضمان إلى بولندا", "e2152dae"], "d": ["وُقعت معاهدة تورن (Toruń) الثانية، التي أنهت حرب الثلاث عشرة سنة التي بدأت بثورة الاتحاد البروسي على حكم الفرسان الألمان (Teutonic Order) سنة 1454، في 19 تشرين الأول/أكتوبر 1466؛ وتخلّى الفرسان لمملكة بولندا عن بوميرانيا الشرقية بما فيها دانزيغ (غدانسك)، وعن مصب الفيستولا بما فيه إلبينغ (Elbląg) ومنطقة كولم — وأخذت هذه الأراضي اسم «بروسيا الملكية». أما بروسيا الشرقية فستبقى لدى الفرسان حتى 1525.", "831685a9"]},
"OLAYLAR_EK16:1474-01-01:0":{"b": ["إيفان الثالث يشتري النصف الباقي من إمارة روستوف", "5203244f"], "d": ["انتقل النصف الذي كان في يد أمراء روستوف إلى موسكو؛ وبالنصف الآخر الذي انتقل إلى موسكو سنة 1332 ارتبطت أرض روستوف كلها بموسكو.", "ab0eeae6"]},
"OLAYLAR_EK16:1485-09-12:0":{"b": ["ضم الإمارة الكبرى تفير إلى موسكو — إيفان الثالث يأخذ المدينة", "fa3f924e"], "d": ["فرّ آخر أمير أكبر لتفير ميخائيل بوريسوفيتش إلى ليتوانيا إثر حصار جيش موسكو، وسلمت تفير نفسها لإيفان الثالث؛ وبذلك زال أقوى منافس لموسكو.", "b9942526"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["الملكة كاترينا كورنارو تتنازل عن قبرص للبندقية — نهاية الدولة الصليبية", "e24d3f3a"], "d": ["تنازلت كاترينا كورنارو البندقية، التي حكمت قبرص نائبةً للملكة بعد وفاة زوجها الملك جاك الثاني سنة 1473، عن العرش في 26 شباط/فبراير 1489 تحت ضغط حكومة البندقية لعدم وجود وريث لها، وتخلّت عن حقوق الحكم في الجزيرة للدوج ولجمهورية البندقية؛ واحتفظت في المقابل بلقب ملكة، ونالت مقاطعة أسولو في تيرافيرما. وبهذا التنازل انتهت سيادة أسرة لوزينيان (Lusignan) القائمة منذ 1192 وآخر دولة صليبية، وبقيت الجزيرة في الإدارة البندقية حتى الفتح العثماني 1570-1571.", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["سقوط غرناطة — نهاية آخر دولة إسلامية في شبه الجزيرة الإيبيرية", "46e5201b"], "d": ["سلّم آخر حكام إمارة غرناطة النصرية، أبو عبد الله (بوعبديل)، الذي أضعفها حصار تدريجي دام عشر سنوات وانقسامات داخلية، مفاتيح المدينة إلى الملكين الكاثوليكيين فرناندو وإيزابيلا في 2 كانون الثاني/يناير 1492 بموجب شروط التسليم السخية (معاهدة تسليم غرناطة) الموقعة في تشرين الثاني/نوفمبر 1491؛ وبمغادرة بوعبديل الحمراء انتهت آخر دولة إسلامية في شبه الجزيرة الإيبيرية واكتملت حرب الاسترداد (Reconquista). وسيتبع ذلك في السنة نفسها طرد اليهود (آذار/مارس) ورحلة كريستوف كولومبوس (آب/أغسطس).", "5dc28ef8"]},
"OLAYLAR_EK16:1500-07-14:0":{"b": ["معركة فيدروشا — موسكو تهزم الجيش الليتواني؛ أراضي بريانسك وسيفيرسك تبقى في موسكو", "d3f61400"], "d": ["في حرب موسكو وليتوانيا 1500-1503 هزم جيش موسكو بقيادة دانييل شتشينيا قرب دوروغوبوج على نهر فيدروشا جيش الهتمان قسطنطين أوستروغسكي وأسر الهتمان. وبقيت مدينتا بريانسك وسيفيرسك، اللتان أُخذتا في ربيع السنة نفسها، في يد موسكو؛ وفي نهاية الحرب كان نحو ثلث أراضي ليتوانيا قد انتقل إلى موسكو.", "e5879803"]},
"OLAYLAR_EK16:1503-04-02:0":{"b": ["هدنة موسكو-ليتوانيا — منطقة تشيرنيغوف-سيفيرسك تنتقل إلى موسكو", "8e4c56f9"], "d": ["انتهت الحرب بين موسكو وليتوانيا 1500-1503، بوساطة ملك المجر-بوهيميا فلاديسلاف الثاني، بهدنة مدتها ست سنوات؛ واضطرت دوقية ليتوانيا الكبرى إلى التخلي لدوقية موسكو الكبرى عن مساحة واسعة تشكل نحو ثلث الدوقية الكبرى، تشمل منطقة تشيرنيغوف-سيفيرسك (محيط تشيرنيغوف ونوفغورود-سيفيرسك وستارودوب وبريانسك) وبعض الأراضي حول سمولنسك وبولوتسك. وكان ذلك من أكبر مكاسب موسكو الفردية في عملية «جمع» الأراضي الروسية.", "4cb77b9b"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["شيباني خان يأخذ هراة وخراسان من التيموريين", "a81d8575"], "d": ["بحسب مادة شيباني خان في TDV، بعد أن أخذ الحاكم الأوزبكي شيباني خان بين 1503 و1505 أنديجان وفرغانة وحصار وقندوز وبلخ، استولى سنة 913 (1507) على هراة أيضًا، عاصمة التيموريين؛ وتعطي مادة خراسان في Encyclopaedia Iranica التاريخ الدقيق لهذا الفتح — فقد سقطت المدينة في 8 محرم 913 (20 أيار/مايو 1507)، وبعد أسبوع، في 15 محرم (27 أيار/مايو)، قُرئت الخطبة باسم شيباني خان فصار الفتح رسميًّا. وانتقلت خراسان كلها، بما فيها مشهد، من التيموريين إلى الشيبانيين في السنة نفسها؛ وكان ذلك يعني أن الأسرة التيمورية فقدت آخر قلاعها الكبرى في إيران بعد ما وراء النهر.", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["سقوط وهران في يد إسبانيا — حملة الكاردينال ثيسنيروس إلى شمال إفريقيا", "86ed8ac1"], "d": ["كانت وهران، التي تسيطر على الطريق البحري في غرب المتوسط وهي ميناء تلمسان، قد نمت بلجوء المسلمين واليهود الأندلسيين الفارين من غرناطة سنة 1492. وفي مطلع القرن السادس عشر احتلت مملكة قشتالة، التي كانت تأخذ مدن الموانئ على ساحل المغرب واحدة بعد أخرى، وهران في 17 أيار/مايو 1509؛ وذُبح القسم الأكبر من الأهالي وأُسر الباقون، ولم يبقَ في المدينة سكان مسلمون ولا يهود. ووسّع الإسبان الأسوار والقلاع؛ وبقيت وهران في يد إسبانيا حتى 1708.", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["استسلام سمولنسك لموسكو — فاسيلي الثالث يدخل المدينة", "46c61446"], "d": ["في الحصار الثالث ضمن حرب موسكو وليتوانيا 1512-1522 استسلمت الحامية الليتوانية في 31 تموز/يوليو؛ ودخل جيش موسكو المدينة في موكب في 1 آب/أغسطس وأدى الأهالي يمين الولاء لفاسيلي الثالث. وسمولنسك هي أكبر مكاسب فاسيلي في الغرب؛ والهزيمة التي لحقت به بعد أسابيع قليلة في أورشا لم تُعد المدينة.", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["ارتباط الأراضي المنخفضة بالتاج الإسباني — وفاة فرديناند واعتلاء شارلكان العرش", "fbe0dbd2"], "d": ["بوفاة ملك أراغون فرديناند الثاني في 23 كانون الثاني/يناير 1516، صار حفيده شارلكان، الذي كان يحكم الأراضي المنخفضة (بلجيكا وهولندا ولوكسمبورغ اليوم وجزءًا من شمال فرنسا) أصلًا بصفته دوق بورغونيا منذ 1506، وريثًا لعرشي قشتالة وأراغون أيضًا، وأُعلن ملكًا لإسبانيا في بروكسل في 14 آذار/مارس 1516. وبذلك صارت هذه الأراضي تُعدّ مرتبطة بالتاج الإسباني مباشرة بالاتحاد الشخصي، لا بفرع ألمانيا/النمسا من أسرة الهابسبورغ — وستجتمع الهويتان (ملك إسبانيا وإمبراطور ألمانيا-روما) في شخص واحد بانتخاب شارلكان إمبراطورًا للإمبراطورية الرومانية المقدسة سنة 1519، وستستمر تبعية المنطقة لإسبانيا حتى تنازل شارلكان عن العرش سنة 1556 وترك إرثه لابنه فيليب الثاني.", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["سلطنة دماك تُسقط ماجاباهيت وتسيطر على ساحل جاوة", "7da602b5"], "d": ["بحسب مادة دماك في TDV، أسس رادن فتاح سلطنة دماك، أول دولة إسلامية مستقلة في جاوة، في الربع الأخير من القرن الخامس عشر؛ وبحسب المصادر الجاوية زالت مملكة ماجاباهيت الهندوسية البوذية المتداعية بهجمات دماك. وفي 1527 فتحت دماك توبان، التي تذكرها المصادر الصينية منذ القرن الحادي عشر ميناءً مهمًّا لحكام ماجاباهيت — وهذه هي السنة التي انضمت فيها آخر بقايا ماجاباهيت إلى دماك أيضًا، وهي نقطة تحول في عملية أسلمة القسم الأكبر من جاوة.", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["اختزال النرويج إلى مقاطعة تابعة للتاج الدنماركي", "8e2f274e"], "d": ["أعلن ملك الدنمارك كريستيان الثالث في ميثاق التتويج لسنة 1536 (håndfæstning) أن النرويج لم تعد تُعدّ مملكة مستقلة وأنها ستُدار بوصفها مقاطعة من مقاطعات الدنمارك، وأن مجلس الدولة النرويجي (riksråd) قد أُلغي؛ وصار هذا القرار واقعًا سنة 1537 بتطبيق نظام الكنيسة الدنماركية في النرويج أيضًا، وكُسرت مقاومة الأسقف الاسكتلندي النرويجي أولاف إنغلبريكتسون. ومع أن النرويج احتفظت عمليًّا بقوانينها ومؤسساتها زمنًا إضافيًّا، فإن وضعها السياسي لم يعد مملكة مستقلة بل مقاطعة تابعة للتاج الدنماركي — وهو وضع سيستمر حتى 1814.", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["الروس يأخذون نارفا — أول مدينة كبيرة في حرب ليفونيا", "c21130d7"], "d": ["أخذت جيوش إيفان الرابع نارفا؛ ووصلت روسيا إلى ساحل البلطيق. وبقيت نارفا في يد الروس حتى انتقلت إلى السويد سنة 1581.", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["الروس يأخذون دوربات (تارتو)", "f941a504"], "d": ["أخذت الجيوش الروسية في حملة صيف 1558 دوربات (تارتو) والقلاع المحيطة؛ وبقيت المدينة تحت الإدارة الروسية حتى هدنة يام زابولسكي لسنة 1582.", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["ريفال (تالين) تدخل في حماية السويد — شمال إستونيا ينتقل إلى السويد", "3c183267"], "d": ["حين كانت كونفدرالية ليفونيا تتفكك، قدّم مجلس مدينة ريفال سنة 1561 الولاء لملك السويد إريك الرابع عشر؛ وبقي شمال إستونيا في يد السويد حتى حرب الشمال الكبرى (1721).", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["معاهدة فيلنيوس — انحلال كونفدرالية ليفونيا وارتباط كورلاند وليفونيا ببولندا-ليتوانيا (باستثناء مدينة ريغا)", "d1ceaad5"], "d": ["دخل غوتهارد كيتلر، آخر أستاذ أكبر لكونفدرالية ليفونيا التي تفككت تحت الضغط الروسي في حرب ليفونيا، في حماية الدوق الأكبر لليتوانيا وملك بولندا سيغيسموند الثاني أوغسطس بمعاهدة (Pacta Subiectionis) وُقعت في فيلنيوس في 28 تشرين الثاني/نوفمبر 1561؛ وارتبط القسم الأكبر من ليفونيا، باستثناء مدينة ريغا، ببولندا-ليتوانيا، وصار كيتلر أول دوق لدوقية كورلاند. وكانت تلك الفصل الأخير في انتقال فرسان ليفونيا من العصور الوسطى إلى العصر الحديث.", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["السويد تأخذ نارفا من روسيا", "5a7f7a6a"], "d": ["في السنوات الأخيرة من حرب ليفونيا أخذت القوات السويدية نارفا التي كانت في يد الروس منذ 1558؛ وبقيت المدينة في يد السويد حتى 1704.", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["مدينة ريغا الحرة ترتبط ببولندا-ليتوانيا", "77dba329"], "d": ["ارتبطت ريغا، التي بقيت مدينة حرة طوال حرب ليفونيا، سنة 1581 باتحاد بولندا-ليتوانيا؛ وبقيت المدينة في الاتحاد حتى انتقلت إلى السويد سنة 1621.", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["إعلان التنازل (Plakkaat van Verlatinghe) — هولندا تعلن استقلالها عن إسبانيا", "a632aaee"], "d": ["في أثناء حروب الثمانين عامًا، أعلن المجلس العام (Staten-Generaal) للمقاطعات الهولندية المنضوية في اتحاد أوترخت، بإعلان التنازل الذي قبله في 26 تموز/يوليو 1581، أن ملك إسبانيا فيليب الثاني «طاغية» ورفض الولاء له؛ ويُعدّ هذا الوثيقة فعليًّا بيان تأسيس المقاطعات المتحدة المستقلة (الجمهورية الهولندية). وكان الاعتراف الإسباني النهائي سينتظر وستفاليا 1648، لكن القطيعة الفعلية تعود إلى هذا اليوم.", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["سقوط سمولنسك في يد بولندا-ليتوانيا — نهاية حصار دام 20 شهرًا", "4e9678e3"], "d": ["في زمن الاضطرابات (Smuta)، أحدث جيش ملك بولندا سيغيسموند الثالث ثغرة في أسوار سمولنسك التي حاصرها منذ أيلول/سبتمبر 1609، بتفجير لغم في 13 حزيران/يونيو 1611، واستولى على المدينة؛ وانتهت مقاومة دامت 20 شهرًا. وبقيت سمولنسك في بولندا-ليتوانيا حتى 1654، وهيأ هذا السقوط الأرضية لهدنة دولينو (1618) التي ستُوقع في السنة نفسها.", "bc44374a"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["الجيش السويدي يأخذ نوفغورود — شمال غرب روسيا يدخل السيطرة السويدية في زمن الاضطرابات", "a8ab28bb"], "d": ["أخذ الجيش السويدي بقيادة ياكوب دي لا غاردي نوفغورود؛ وصارت المدينة حتى 1617 عاصمة «دولة نوفغورود» تحت الحماية السويدية، وقُدّم كارل فيليب مرشحًا للقيصرية.", "281592c2"]},
"OLAYLAR_EK16:1617-02-27:0":{"b": ["معاهدة ستولبوفو — روسيا تفقد ساحل البلطيق (إنغريا) لمصلحة السويد", "175dc175"], "d": ["وُقعت معاهدة ستولبوفو، التي أنهت حرب إنغريا، في 27 شباط/فبراير 1617 في قرية ستولبوفو جنوبي بحيرة لادوغا؛ وبينما استعادت روسيا نوفغورود وأراضيها الأخرى في الشمال، احتفظت السويد بكاريليا وإنغريا (بين إستونيا وفنلندا، بما فيها قلاع إيفانغورود ويام وكوبوريه وأوريشك)، وانقطع ساحل روسيا المباشر على البلطيق. وسيستمر هذا الانقطاع إلى أن أسس بطرس الأكبر سانت بطرسبورغ في المنطقة نفسها سنة 1703.", "7e70e3e6"]},
"OLAYLAR_EK16:1617-02-27:1":{"b": ["معاهدة ستولبوفو — روسيا تتخلى عن إنغرمانلاند للسويد وتُعاد نوفغورود", "e0bcbc7a"], "d": ["تخلّت روسيا للسويد عن ضفاف نيفا وجزء من كاريليا (يام وكوبوريه وإيفانغورود وأوريشك) وانقطعت عن ساحل البلطيق؛ وأعادت السويد نوفغورود. واستمر هذا الوضع إلى حرب الشمال الكبرى لبطرس الأول.", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["هدنة دولينو — سمولنسك وتشيرنيغوف ونوفغورود-سيفيرسك تُترك لبولندا", "6880d2c1"], "d": ["وُقعت هدنة دولينو، التي أنهت الحرب البولندية الروسية 1609-1618، في 11 كانون الأول/ديسمبر 1618 وأتاحت وقف إطلاق نار لمدة 14,5 سنة؛ واضطرت روسيا إلى التخلي لاتحاد بولندا-ليتوانيا عن سمولنسك (باستثناء فيازما) و29 مدينة في منطقتي تشيرنيغوف ونوفغورود-سيفيرسك — وكانت أشد خسارة إقليمية في زمن الاضطرابات (Smuta). وستبقى المنطقة في بولندا حتى هدنة أندروسوفو سنة 1667.", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["السويد تأخذ تارتو (دوربات) من بولندا — المرحلة الثانية من حملة ليفونيا", "46b7c86a"], "d": ["فتح غوستاف الثاني أدولف في حملة 1625 جنوب إستونيا وشمال ليفونيا؛ وصارت تارتو مدينة سويدية سيُؤسس فيها أكاديمية غوستاف أدولف سنة 1632.", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["مجلس بيرياسلاف — القوزاق الزابوروجيون يؤدون يمين الولاء للقيصر الروسي", "bcd8f8ef"], "d": ["أدى بوغدان خميلنيتسكي، هتمان القوزاق الزابوروجيين الذين ثاروا على بولندا-ليتوانيا منذ 1648، يمين الولاء للقيصر ألكسي الأول ميخايلوفيتش في مجلس بيرياسلاف بتاريخ 18 كانون الثاني/يناير 1654 (8 كانون الثاني/يناير بالتقويم اليولياني)، بحضور وفد جاء من موسكو برئاسة فاسيلي بوتورلين؛ ويُعدّ هذا بداية دخول هتمانية القوزاق الأوكرانية في حماية روسيا، ونقل السيطرة الفعلية على منطقة تشيرنيغوف-سيفيرسك من بولندا إلى روسيا — أما الحدود الرسمية فسيرسمها هدنة أندروسوفو سنة 1667.", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["روسيا تستعيد سمولنسك", "bf0eca92"], "d": ["في أثناء الحرب البولندية الروسية التي بدأت سنة 1654، استعاد الجيش الروسي سمولنسك، التي كان يحاصرها منذ تموز/يوليو، في 3 تشرين الأول/أكتوبر 1654 باستسلام الحامية البولندية؛ وعادت المدينة التي فُقدت لمصلحة بولندا سنة 1611 إلى روسيا بعد 43 سنة. وكانت هذه من أهم خطوات عملية عكس روسيا لخسائر زمن الاضطرابات، وصارت دائمة بهدنة أندروسوفو سنة 1667.", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["هدنة أندروسوفو — كييف وأوكرانيا الضفة اليسرى تنتقلان إلى روسيا", "799be067"], "d": ["أتاحت هدنة أندروسوفو، التي أنهت الحرب البولندية الروسية 1654-1667، وقف إطلاق نار لمدة 13,5 سنة؛ وكسبت روسيا سمولنسك ومنطقة تشيرنيغوف-سيفيرسك وأوكرانيا الواقعة على الضفة اليسرى لنهر الدنيبر، ومدينة كييف — في البداية لمدة سنتين، وفعليًّا بصورة دائمة. وأرست هذه المعاهدة الأساس القانوني لتقسيم الأراضي الأوكرانية على طول الدنيبر بين بولندا وروسيا (وبقاء كييف في روسيا).", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["روسيا تأخذ نوتيبورغ (أوريشك) من السويد — أول قلعة على نهر نيفا في حرب الشمال الكبرى", "28d180eb"], "d": ["حاصرت جيوش بطرس الأول نوتيبورغ (أوريشك بالروسية) عند مخرج لادوغا وأخذتها وسمّتها شليسلبورغ («قلعة المفتاح»)؛ وفتح ذلك الطريق إلى نيفا وإلى تأسيس سانت بطرسبورغ سنة 1703.", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["تأسيس سانت بطرسبورغ — نافذة روسيا المفتوحة على الغرب", "ba196be0"], "d": ["في جزيرة الأرنب في دلتا نهر نيفا، التي استُردت حديثًا من السويد في حرب الشمال الكبرى، وضع بطرس الأكبر في 16/27 أيار/مايو 1703 أساس قلعة بتروبافلوفسك (قلعة بطرس وبولس)؛ ويُعدّ هذا اليوم تاريخ تأسيس مدينة سانت بطرسبورغ. وتصوّر بطرس الدلتا المستنقعية «نافذة» مفتوحة على الغرب، وصارت المدينة سنة 1712 عاصمة روسيا الجديدة — وستُضم المنطقة رسميًّا إلى روسيا بمعاهدة نيشتاد سنة 1721.", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["استيلاء القوات الإنجليزية الهولندية على مينوركا", "3ca66a83"], "d": ["نزلت القوات الإنجليزية الهولندية، التي كانت تتحرك حليفةً للأرشيدوق النمساوي شارل السادس في حرب الخلافة الإسبانية، بقيادة الجنرال جيمس ستانهوب في الجزيرة في 14 أيلول/سبتمبر 1708، وأسقطت الدفاع الإسباني في 28-29 أيلول/سبتمبر واستولت على مينوركا (واستغرق التسليم الرسمي للقلعة الرئيسية، حصن سانت فيليب، حتى 24 تشرين الثاني/نوفمبر). وسيكون ميناء ماهون الاستراتيجي في مينوركا محور الصراع الإنجليزي الفرنسي الإسباني طوال قرن تالٍ.", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["معاهدة راشتات — انتهاء حرب الخلافة الإسبانية وانتقال هولندا الإسبانية وميلانو إلى النمسا", "3c0e086f"], "d": ["وُقعت معاهدة راشتات، التي أنهت حرب الخلافة الإسبانية بين فرنسا والنمسا، في 7 آذار/مارس 1714 (وكانت أوترخت قد نظمت سنة 1713 العلاقة بين إنجلترا وفرنسا)؛ وتسلمت أسرة هابسبورغ النمساوية بالمعاهدة هولندا الإسبانية (بلجيكا اليوم) ونابولي وميلانو وسردينيا في إيطاليا. وكان ذلك أوسع توسع إقليمي في تاريخ النمسا، وأضاف إلى ثقل أسرة هابسبورغ في أوروبا الوسطى جبهة جديدة في أوروبا الغربية والجنوبية.", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["معاهدة نيشتاد — انتهاء حرب الشمال الكبرى وانتقال سواحل البلطيق إلى روسيا", "068ffd06"], "d": ["وُقعت معاهدة نيشتاد، التي أنهت حرب الشمال الكبرى التي دامت 21 سنة، في فنلندا في 30 آب/أغسطس 1721؛ وتخلّت السويد لروسيا عن إستونيا وليفونيا (بما فيها ريغا) وإنغرمانلاند وقسم من جنوب شرق فنلندا (كاريليا)، واستعادت في المقابل بقية فنلندا ودُفع لها تعويض. وتُعدّ المعاهدة نهاية لوضع السويد دولةً عظمى وتسجيلًا رسميًّا لصعود روسيا إمبراطورية أوروبية — وقد اتخذ بطرس الأول بعد هذا النصر لقب «الإمبراطور».", "ff69c190"]},
"OLAYLAR_EK16:1772-08-05:0":{"b": ["التقسيم الأول لبولندا — خسارة أراضٍ لروسيا والنمسا", "2c56a0d8"], "d": ["اقتُسم نحو ثلث أراضي الكومنولث البولندي الليتواني بمعاهدة وُقعت في 5 آب/أغسطس 1772 بين روسيا وبروسيا والنمسا: فأخذت روسيا بيلاروسيا الحالية وجزءًا من لاتفيا (بما فيها دونابورغ وبولوتسك وفيتبسك)، وضمت النمسا غاليسيا (بما فيها لفوف وغرب بودوليا ويازلوفيتس)؛ وتسلمت بروسيا منطقة الساحل بروسيا الملكية. ولم يصدّق مجلس السيم البولندي المعاهدة إلا في 30 أيلول/سبتمبر 1773 تحت الضغط. وكان هذا أول التقسيمات الثلاثة التي ستستمر حتى 1795.", "6f2b4118"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["التقسيم الثاني لبولندا — خسارة أراضٍ لروسيا وبروسيا", "31750484"], "d": ["لما أقلقت إصلاحات دستور 1791 روسيا وبروسيا، اقتسمت الدولتان بولندا من جديد بمعاهدة وقّعتاها في سانت بطرسبورغ في 23 كانون الثاني/يناير 1793: فأخذت روسيا القسم الأكبر من ليتوانيا-بيلاروسيا وغرب أوكرانيا (بما فيها كامينيتس وبار ومنسك)، وضمت بروسيا بولندا الكبرى بما فيها غدانسك وبوزنان — بمجموع 307.000 كم². واضطر مجلس السيم البولندي تحت الضغط إلى المصادقة على المعاهدة في السنة نفسها؛ وكان هذا تقسيمًا قصير العمر أخّر الضم الكامل لبولندا سنتين.", "6ff0e18a"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["ضم دوقية كورلاند وسيميغاليا إلى روسيا — آخر الدوقات بيتر فون بيرون يتنازل", "8d0e410f"], "d": ["في سياق التقسيم الثالث لبولندا قدّم نبلاء كورلاند الولاء لكاترين، وتنازل الدوق بيتر فون بيرون عن العرش؛ وصارت كورلاند حكومة (غوبرنيا) روسية (وترد في المصادر أيضًا 24 تشرين الأول/أكتوبر 1795).", "4682774b"]},
"OLAYLAR_EK16:1795-10-24:0":{"b": ["التقسيم الثالث لبولندا — زوال الدولة تمامًا", "e3c02d6b"], "d": ["اقتسمت روسيا وبروسيا والنمسا، باتفاقية ثلاثية وقّعتها في سانت بطرسبورغ في 24 تشرين الأول/أكتوبر 1795، ما بقي من أراضي الكومنولث البولندي الليتواني اقتسامًا تامًّا: فأخذت روسيا ليتوانيا (بما فيها فيلنيوس وكاوناس) وما بقي من بيلاروسيا، وضمت بروسيا بولندا الوسطى بما فيها وارسو، وضمت النمسا المنطقة الجنوبية بما فيها كراكوف. كما ضمنت الدول الثلاث عسكريًّا أراضي بعضها الجديدة، واتخذت احتياطات ضد احتمال إعادة تأسيس بولندا. وهذا هو الزوال التام للدولة البولندية الليتوانية بوصفها بلدًا مستقلًّا؛ ولن تُعاد إلى الوجود حتى القرن العشرين.", "a66df675"]},
"OLAYLAR_EK16:1797-05-12:0":{"b": ["نهاية جمهورية البندقية — المجلس الأعلى يحلّ نفسه", "5efed589"], "d": ["لما احتل جيش حملة نابليون على إيطاليا أراضي البندقية البرية وأنذر الجمهورية، وافق المجلس الأعلى (Maggior Consiglio) في 12 أيار/مايو 1797 بـ512 صوتًا مقابل 20 على حلّ نفسه؛ فاستقال آخر دوج لودوفيكو مانين، وانتهت الإدارة الأرستقراطية لجمهورية البندقية التي استمر وجودها دون انقطاع أكثر من 1.100 سنة. وسُلّمت أراضيها أولًا إلى إدارة ديمقراطية مؤقتة، ثم تُركت رسميًّا للنمسا بمعاهدة كامبو فورميو في تشرين الأول/أكتوبر 1797.", "8852717b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["نهاية جمهورية جنوة — نابليون يؤسس الجمهورية الليغورية", "3d3e59ee"], "d": ["حلّت محل جمهورية جنوة، التي سُلّمت في أوائل حزيران/يونيو 1797 إلى إدارة مؤقتة بضغط من نابليون في حملة إيطاليا، «الجمهورية الليغورية» المعلنة في 14 حزيران/يونيو 1797 بدستور على النموذج الفرنسي؛ وتحولت دوقية جنوة العريقة فعليًّا إلى إحدى الدول التابعة لفرنسا. وستُضم الجمهورية مباشرة إلى فرنسا سنة 1805، وستُترك لمملكة سردينيا-بيدمونت بمؤتمر فيينا 1815.", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["معاهدة كامبو فورميو — اقتسام البندقية بين النمسا وفرنسا", "9f29678c"], "d": ["ألغت معاهدة كامبو فورميو، التي وُقعت في 17 تشرين الأول/أكتوبر 1797 بين نابليون بونابرت وممثل النمسا الكونت كوبنتزل، جمهورية البندقية التي دامت ألف سنة رسميًّا ووزّعت أراضيها: فتُرك للنمسا ما شرقي نهر أديجه وإستريا وساحل دالماتيا (بما فيه سبليت وزادار وشيبينيك وكوتور)، وانتقلت الجزر الاثنتا عشرة والجزر الأيونية (كورفو وكيفالونيا وزاكينثوس وليفكادا وقواعد البندقية على الساحل الألباني-المورة، بما فيها بروزة وبارغا) إلى فرنسا. وتخلّت النمسا كذلك لفرنسا عن أراضيها في الأراضي المنخفضة (بلجيكا اليوم).", "c490738c"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["تسليم مالطة إلى إنجلترا — نهاية حصار فرنسي دام سنتين", "fedc2867"], "d": ["مالطة، التي استولى عليها نابليون سنة 1798 في طريقه إلى حملة مصر، دخلت بعد قليل في الحصار البحري للأسطول الإنجليزي بثورة أهل الجزيرة؛ وبعد حصار وجوع دامَا سنتين سلّم القائد الفرنسي الجنرال فوبوا الجزيرة إلى الجنرال الإنجليزي بيغو في 5 أيلول/سبتمبر 1800. وبذلك انتقلت مالطة من الجمهورية الفرنسية إلى الحماية الإنجليزية، وستُربط رسميًّا بالتاج الإنجليزي بمعاهدة باريس لسنة 1814 — وصارت أهم قاعدة بحرية إنجليزية في البحر المتوسط.", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["معاهدة أميان — إعادة مينوركا إلى إسبانيا", "f341e4b8"], "d": ["أنهت معاهدة أميان (25 آذار/مارس 1802)، الموقعة بين فرنسا وإسبانيا وهولندا وإنجلترا، حرب التحالف الثاني إنهاءً مؤقتًا؛ وأعادت إنجلترا تقريبًا جميع الأراضي التي استولت عليها أثناء الحرب (باستثناء سيلان وترينيداد) — ومنها مينوركا التي أخذتها من إسبانيا سنة 1798. ودام السلام سنة واحدة فحسب، واندلعت الحرب من جديد في أيار/مايو 1803، لكن مينوركا لم تقع بعد هذه المعاهدة في يد الإنجليز مرة أخرى.", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["معاهدة فريدريكشامن (هامينا) — تخلي السويد عن فنلندا لروسيا", "c0d407bc"], "d": ["وُقعت معاهدة فريدريكشامن (هامينا اليوم)، التي أنهت الحرب الروسية السويدية 1808-1809، في 17 أيلول/سبتمبر 1809؛ وتخلّت السويد عن فنلندا كلها، بما فيها جزر آلاند، لروسيا. ونالت فنلندا وضع دوقية كبرى تتمتع بحكم ذاتي واسع تابعة للإمبراطورية الروسية واحتفظت بالمذهب اللوثري والقانون السويدي. وكان ذلك يعني الانتهاء الفعلي لوضع السويد قوةً عظمى في البلطيق.", "4362e6c6"]},
"OLAYLAR_EK16:1810-02-20:0":{"b": ["ضم مملكة إيميريتي — خلع الملك سليمان الثاني", "5ad36bff"], "d": ["كان سليمان الثاني آخر ملوك مملكة إيميريتي في غرب جورجيا، التي اضطرت سنة 1804 إلى قبول التبعية لروسيا باتفاقية إيلازناوري؛ فلما واصل مقاومة الضغط الروسي المتزايد، استولت القوات الروسية في 20 شباط/فبراير 1810 على العاصمة كوتايسي، وخلعت سليمان عن العرش، وأجبرت النبلاء المحليين على أداء يمين الولاء للقيصر ألكسندر الأول؛ وبذلك انتهت مملكة إيميريتي فعليًّا وارتبطت بالإدارة الروسية المباشرة. وهرب سليمان إلى الأراضي العثمانية ومات في المنفى (1815).", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["معاهدة كيل — تخلي الدنمارك عن النرويج للسويد", "59ab1601"], "d": ["تسلمت السويد، التي هاجمت الدنمارك من الجنوب بعد هزيمة نابليون في لايبزيغ، النرويج (باستثناء آيسلندا وجزر فارو وغرينلاند) بمعاهدة كيل الموقعة في 14 كانون الثاني/يناير 1814 — وبذلك انتهى رسميًّا الاتحاد الدنماركي النرويجي القائم منذ 1380. وفي المقابل تخلّت السويد للدنمارك عن أراضيها في بوميرانيا؛ وتنازلت الدنمارك كذلك لإنجلترا عن هيليغولاند. وقاومت النرويج المعاهدة بالسلاح وأعلنت دستورها الخاص، واضطرت السويد إلى الاعتراف به — وكانت النتيجة اتحادًا شخصيًّا (real union) سيستمر حتى 1905.", "382397ad"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["القرار الختامي لمؤتمر فيينا — إعادة رسم خريطة أوروبا بعد نابليون", "fca1c676"], "d": ["أُقرّ القرار الختامي لمؤتمر فيينا، الذي وقعته الدول الكبرى (النمسا وروسيا وبروسيا وإنجلترا وفرنسا) التي أنهت الحروب النابليونية، في 9 حزيران/يونيو 1815 (قبل واترلو بتسعة أيام)، وأعاد رسم خريطة القارة جماعيًّا: فاتحدت هولندا الإسبانية/النمساوية القديمة مع المقاطعات المتحدة تحت «مملكة هولندا المتحدة»، وانضمت جمهورية جنوة إلى مملكة سردينيا-بيدمونت، وارتبط القسم الأكبر من دوقية وارسو بروسيا باسم «بولندا المؤتمر»، وانتقلت بوميرانيا السويدية (شترالزوند) إلى بروسيا. ويُعدّ هذا اليوم وحده البداية الرسمية لتوازن أوروبا بعد الحرب (Concert of Europe).", "39c08302"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["المعاهدة البحرية العامة — القواسم وسائر مشيخات الخليج تُربط بمعاهدة مع إنجلترا", "fc499e19"], "d": ["بعد أن قصفت إنجلترا رأس الخيمة سنة 1819 وشتتت أسطول القواسم «القراصنة»، فرضت المعاهدة البحرية العامة التي بدأت في 8 كانون الثاني/يناير 1820 ووُقعت مع المشيخات في المنطقة واحدة واحدة حتى اكتملت في آذار/مارس؛ وحظرت المعاهدة القرصنة والرق، وألزمت السفن برفع علم أحمر وأبيض يشبه العلم الإنجليزي. وبهذه المعاهدة تحوّل «ساحل القراصنة» مع الزمن إلى «الساحل المتصالح» (Trucial Coast)؛ وكانت بداية علاقة ستستمر حتى 1971 تعمّق فيها الهيمنة الإنجليزية بالهدنة البحرية الدائمة لسنة 1853 والمعاهدات الحصرية لسنة 1892.", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["نهاية حصار غايتا — انهيار مملكة الصقليتين", "121ae580"], "d": ["بعد الانهيار الذي بدأ بنزول غاريبالدي في صقلية في أيار/مايو 1860، حوصر الملك البوربوني فرانشيسكو الثاني، الذي فرّ من نابولي، في آخر قلاعه غايتا ابتداءً من 3 تشرين الثاني/نوفمبر 1860؛ وبانسحاب الأسطول الفرنسي من المنطقة في كانون الثاني/يناير 1861 اشتد الحصار البحري الإيطالي، واستسلمت غايتا في 13 شباط/فبراير 1861. وترك فرانشيسكو الثاني عرشه وذهب إلى المنفى؛ ولن تسقط تشيفيتيلا ديل ترونتو، آخر نقطة مقاومة في مملكة الصقليتين، إلا في 20 آذار/مارس 1861.", "ad1202f1"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["إعلان مملكة إيطاليا — توحد سردينيا وتوسكانا وجنوب إيطاليا", "12e52f70"], "d": ["أُعلنت مملكة إيطاليا رسميًّا في 17 آذار/مارس 1861 في الجلسة الأولى التي عقدها البرلمان الإيطالي في تورينو، وصار ملك سردينيا-بيدمونت فيتوريو إيمانويل الثاني أول ملك لإيطاليا الموحدة. وكانت المملكة الجديدة تجمع مع مملكة سردينيا أراضي توسكانا وإميليا-رومانيا ونابولي وصقلية (الصقليتين) التي انضمت في العام السابق باستفتاءات شعبية؛ وبقيت روما (الدولة البابوية) والبندقية (النمسا) خارجها بعد — وستنضمان في 1870 و1866 على التوالي.", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["سقوط جيزاخ (Jizzakh) في يد روسيا — آخر قلاع إمارة بخارى على خط سيردريا", "21205a6e"], "d": ["في أثناء تقدم روسيا في آسيا الوسطى، وبعد محاولة الجنرال تشيرنيايف الفاشلة في شباط/فبراير 1866، استولت القوات الروسية بقيادة الجنرال ديمتري رومانوفسكي، الذي عُيّن بدلًا منه، في تشرين الأول/أكتوبر 1866 بعد حصار دام سبعة أيام وهجوم عنيف على جيزاخ، آخر قلاع إمارة بخارى الكبرى في وادي سيردريا؛ وأنهى هذا السقوط مقاومة بخارى فعليًّا في المنطقة وفتح أمام الجيش الروسي الطريق إلى سمرقند.", "b95ba993"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["انتقال عصب إلى ملكية الدولة الإيطالية — أساس أول مستعمرة لإيطاليا", "15ab8732"], "d": ["كان ميناء عصب على ساحل البحر الأحمر قد اشترته شركة ملاحة إيطالية خاصة (Rubattino) من زعماء العفر المحليين سنة 1869؛ وتولت الحكومة الإيطالية، بموافقة إنجلترا، الملكية المباشرة للدولة للميناء في 10 آذار/مارس 1882، وأعلنت عصب رسميًّا أول مستعمرة لإيطاليا بقانون أصدرته في تموز/يوليو. وكانت هذه نقطة بداية توسع إيطاليا على ساحل البحر الأحمر الذي سيتحول لاحقًا إلى المستعمرة الإريترية (1890).", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["إبادة حامية سنكات — سنكات تنتقل إلى قوات المهدي", "e175a94e"], "d": ["حاولت حامية سنكات، التي حاصرتها قوات عثمان دقنة أشهرًا ونفد زادها، أن تخرق الحصار مع قائدها توفيق بك وتصل إلى سواكن؛ فأُبيدت خارج القلعة في 8 شباط/فبراير 1884، وصارت سنكات في يد قوات المهدي. ووصل الخبر إلى سواكن في 12 شباط/فبراير.", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["الأحكام العرفية في سواكن — المدينة تنتقل إلى القيادة الإنجليزية", "801f6a81"], "d": ["بعد هزيمة قوة بيكر لإنقاذ طوكر في التيب في 4 شباط/فبراير، أنزل الأميرال هيويت المشاة البحرية في سواكن في 6 شباط/فبراير. وفي 9 شباط/فبراير 1884 أُعلنت الأحكام العرفية في المدينة ومُنح الضباط الإنجليز سلطة عسكرية ومدنية كاملة عليها؛ وفي اليوم التالي نُقلت مسؤولية المدينة رسميًّا من بيكر إلى هيويت.", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["تسليم طوكر إلى قوات المهدي", "0e21fd24"], "d": ["دخلت حامية طوكر المحاصَرة في مفاوضات مع قوات المهدي في 19 شباط/فبراير 1884، وسلّمت المدينة في اليوم التالي، 20 شباط/فبراير. ووصل الخبر إلى القوة الإنجليزية في ترنكيتات في 24 شباط/فبراير؛ وكانت عملية الإنقاذ التي قام بها غراهام قد تأخرت.", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["بريطانيا تقيم حمايتها على ساحل الصومال الشمالي — بداية صوماليلاند", "f301ea94"], "d": ["بحسب مادة الصومال في TDV استعمر الإنجليز زيلع وبربرة وتاجورة سنة 1884 باسم صوماليلاند؛ وبحسب المصدر الأكاديمي المعياري بدأت هذه العملية في بربرة بمعاهدة وُقّعت مع قبيلة حبر أول في 21 رمضان 1301 (14 تموز/يوليو 1884)، واتسعت في 1884-1886 بتوقيع معاهدات مماثلة مع قبائل الجدبورسي وحبر تولجعلى وحبر جرحجيس والعيسى والورسنجلي؛ ووعدت إنجلترا بالحماية العسكرية في المقابل. وهيأت سلسلة المعاهدات هذه الأرضية لإعلان محمية صوماليلاند البريطانية الرسمية سنة 1887.", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["معركة المليدا — نهاية الدولة السعودية الثانية وانتقال نجد إلى الرشيديين", "1cd3b213"], "d": ["بعد أن تدهورت العلاقات بسبب خلاف على الزكاة واعتقال مبعوث رشيدي، هزم جيش أمير جبل شمر محمد بن رشيد في 21 كانون الثاني/يناير 1891 في المليدا بمنطقة القصيم القوات السعودية بقيادة عبد الرحمن بن فيصل وحلفاءها هزيمة ثقيلة؛ وكان هذا النهاية الفعلية للدولة السعودية الثانية، ونُفيت أسرة آل سعود إلى الكويت ودخلت نجد كلها تحت سيادة آل رشيد. وستستمر هذه السيادة إلى أن استعاد عبد العزيز بن سعود الشاب الرياض سنة 1902 (غارة الرياض، 16 كانون الثاني/يناير 1902).", "e496bc0f"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["استعادة القوات الإنجليزية المصرية لطوكر — انسحاب عثمان دقنة", "80a2c26a"], "d": ["استُعيدت طوكر على ساحل البحر الأحمر، التي كانت منذ 1884 في يد القائد المحلي للحركة المهدية عثمان دقنة، بعمليات القوات الإنجليزية المصرية في شباط/فبراير 1891؛ واضطر عثمان دقنة إلى الانسحاب إلى الجبال. وكان ذلك ضربة كبيرة لوجود الدولة المهدية على ساحل البحر الأحمر، ودخلت المنطقة تحت إدارة إنجليزية مصرية مشتركة.", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["مرور عمود غرينفيل بسنكات — سنكات تخرج من إدارة المهدي وتعود إلى الإدارة الإنجليزية المصرية", "b7539a44"], "d": ["بعد استرداد طوكر في شباط/فبراير 1891، انطلق العمود الإنجليزي المصري بقيادة غرينفيل في 3 آذار/مارس 1891 من عفافيت عبر سنكات ووصل إلى سواكن في 7 آذار/مارس؛ فوجد العمود المنطقة التي لم يُدخل إليها منذ 1884 خالية تمامًا من العدو. وفي 8 آذار/مارس أُعلن عفو عام باسم الخديوي على الشيوخ المجتمعين في سواكن، وعادت سنكات إلى الإدارة الإنجليزية المصرية.", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["انتقال الصومال الإيطالي إلى الإدارة المباشرة للدولة — تصفية شركة بنادر", "8c7d085b"], "d": ["بحسب مادة الصومال في TDV، كانت إيطاليا قد أقامت سيادتها على ساحل الصومال الجنوبي (بنادر) في 1889-1891 باتفاقات مع سلطنة زنجبار وإنجلترا، وتركت إدارته في البداية لشركة تجارية ذات امتياز (Benadir Company)؛ وبحسب المصدر الأكاديمي المعياري انتهى امتياز هذه الشركة في 24 كانون الثاني/يناير 1905، واشترت الدولة الإيطالية السيادة المباشرة على ساحل بنادر (بما فيه مقديشو ومركة وبراوة) وأقامت الإدارة الاستعمارية الرسمية. أما التوسع الفعلي للمستعمرة نحو الداخل (بردرة وبيدوا) فسيكتمل بمرسوم التأسيس لسنة 1908 وفي السنوات اللاحقة.", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["فسخ الاتحاد النرويجي السويدي — إعلان الستورتينغ الاستقلال من جانب واحد", "aaba2935"], "d": ["بعد أن استخدم الملك أوسكار الثاني حق النقض ضد مطلب الحكومة النرويجية بإنشاء قنصلية منفصلة وأعلن أنه لا يستطيع تشكيل حكومة جديدة، قرر الستورتينغ (البرلمان) النرويجي في 7 حزيران/يونيو 1905 بالإجماع أن الملك لم يعد يؤدي مهامه فعليًّا ملكًا للنرويج وأن الاتحاد القائم منذ معاهدة كيل لسنة 1814 قد فُسخ. وفي الاستفتاء الشعبي في 13 آب/أغسطس 1905 أيّد الناخبون الفسخ بنسبة تكاد تكون كاملة (371.000 صوت مقابل 184)؛ واعترفت السويد رسميًّا بالاستقلال في 26 تشرين الأول/أكتوبر 1905 بعد مفاوضات كارلستاد.", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["القوات الألمانية تأخذ ليباو (ليباجا) — بدء احتلال كورلاند", "fdb10548"], "d": ["دخل الألمان كورلاند في هجوم صيف 1915؛ وكانت ليباو القاعدة البحرية الروسية على ساحل البلطيق. ودخل معظم كورلاند في قيادة أوبر أوست (حتى نهاية 1918).", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["القوات الألمانية تأخذ ميتاو (يلغافا)", "eb491281"], "d": ["دخلت ميتاو، عاصمة دوقية كورلاند القديمة، في السيطرة الألمانية؛ وتجمدت جبهة ريغا على خط داوغافا وبقيت كذلك حتى 1917.", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["الألمان يأخذون قلعة كوفنو (كاوناس) — ليتوانيا تقع تحت الاحتلال", "9849405b"], "d": ["أخذ الجيش الألماني العاشر أكبر قلاع روسيا على نهر نيمان؛ ودخلت منطقة ليتوانيا في إدارة أوبر أوست، وأعلنت التاريبا استقلالها في 1918 تحت هذا الاحتلال.", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["القوات الألمانية تأخذ فيلنا (فيلنيوس)", "2781858b"], "d": ["انتقلت فيلنا إلى القوات الألمانية في أثناء الانسحاب الكبير وارتبطت بمنطقة ليتوانيا التابعة لأوبر أوست؛ وتبادلت القوات الألمانية والسوفييتية والبولندية المدينة حتى 1919.", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["المعاهدة الإنجليزية القطرية — قطر تدخل في الحماية الإنجليزية", "f61c4e49"], "d": ["في أثناء الحرب العالمية الأولى، وبمعاهدة وُقعت في 3 تشرين الثاني/نوفمبر 1916 بين الممثل السياسي الإنجليزي في الخليج العربي الرائد بيرسي كوكس وشيخ قطر عبد الله بن جاسم آل ثاني، قبلت قطر ربط علاقاتها الخارجية بموافقة إنجلترا، وحصلت في المقابل على ضمان الحماية الإنجليزية ضد الهجمات البحرية؛ وشكّلت هذه المعاهدة الأساس القانوني لعلاقة الحماية الإنجليزية لقطر التي ستستمر حتى 1971، وصودق عليها رسميًّا سنة 1918.", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["الجيش الألماني الثامن يأخذ ريغا", "df95df19"], "d": ["عبرت القوات الألمانية نهر داوغافا وأخذت ريغا؛ وبقيت المدينة تحت السيطرة الألمانية حتى تشرين الثاني/نوفمبر 1918، وأُعلن استقلال لاتفيا تحت هذا الاحتلال (18 تشرين الثاني/نوفمبر 1918).", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["مجلس الشعب اللاتفي يعلن استقلاله", "fc72a7f7"], "d": ["أعلن مجلس الشعب اللاتفي، الذي اجتمع في المسرح الوطني في ريغا، جمهورية لاتفيا المستقلة عن الإمبراطورية الروسية؛ وتشكلت حكومة مؤقتة برئاسة كارليس أولمانيس. وبعد أسابيع قليلة (كانون الأول/ديسمبر 1918) هاجمت روسيا السوفييتية وبدأت حرب الاستقلال.", "2858d946"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["الجيش الأحمر يدخل فيلنيوس — الحكومة الليتوانية تخلي المدينة", "889a97b3"], "d": ["أخلت الحكومة الليتوانية فيلنيوس مع اقتراب الجيش الأحمر؛ ودخلت القوات السوفييتية المدينة، وأُعلنت منها في شباط/فبراير 1919 جمهورية ليتوانيا-بيلاروسيا السوفييتية (ليتبيل). وستأخذ القوات البولندية المدينة في نيسان/أبريل 1919.", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["القوات البولندية تأخذ فيلنيوس (فيلنو) من السوفييت", "32d36c4a"], "d": ["أخذت قوات يوزف بيلسودسكي فيلنو من الجيش الأحمر في نيسان/أبريل 1919؛ وظلت ليتوانيا تدّعي المدينة، وسمّمت مسألة فيلنيوس العلاقات الليتوانية البولندية بين الحربين.", "85e7c434"]},
"OLAYLAR_EK16:1920-10-12:0":{"b": ["جيليغوفسكي يعلن ليتوانيا الوسطى — فيلنيوس عاصمة دولة دمية بدعم بولندي", "11400510"], "d": ["أخذ الجنرال لوسيان جيليغوفسكي فيلنيوس بـ«تمرده» وأعلن جمهورية ليتوانيا الوسطى؛ وبقيت الدولة حتى 24 آذار/مارس 1922.", "d8050fe5"]},
"OLAYLAR_EK16:1922-03-24:0":{"b": ["ضم ليتوانيا الوسطى إلى بولندا — فيلنيوس تصبح بولندية", "e929fa20"], "d": ["صوّت سيم فيلنو على الانضمام في 20 شباط/فبراير 1922؛ وصادق عليه السيم البولندي في 24 آذار/مارس 1922. واعترف مؤتمر السفراء بالحدود سنة 1923، ولم تعترف بها ليتوانيا.", "4a067568"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["ليتوانيا تقبل الإنذار الألماني — منطقة ميميل تُسلَّم إلى ألمانيا", "149fb0b2"], "d": ["تخلّت ليتوانيا إثر إنذار ريبنتروب عن منطقة كلايبيدا (ميميل) لألمانيا؛ ودخل هتلر ميميل في 23 آذار/مارس. وأخذ الجيش الأحمر المنطقة في 28 كانون الثاني/يناير 1945.", "75afd979"]},
"OLAYLAR_EK16:1939-09-19:0":{"b": ["الجيش الأحمر يحتل فيلنيوس", "5b25d037"], "d": ["دخل الجيش الأحمر، الذي دخل شرق بولندا في 17 أيلول/سبتمبر، في ليلة 18-19 أيلول/سبتمبر فيلنيوس التي كانت في يد بولندا. وستُترك المدينة لليتوانيا بحلف المساعدة المتبادلة السوفييتي الليتواني في 10 تشرين الأول/أكتوبر، وسيدخلها الجيش الليتواني في 28 تشرين الأول/أكتوبر.", "285aa71c"]},
"OLAYLAR_EK16:1939-10-28:0":{"b": ["ليتوانيا تتسلم فيلنيوس — ثمن حلف المساعدة المتبادلة السوفييتي الليتواني", "37ba5976"], "d": ["فيلنيوس، التي أخذها الجيش الأحمر في 19 أيلول/سبتمبر 1939، تُركت لليتوانيا بحلف المساعدة المتبادلة في 10 تشرين الأول/أكتوبر 1939؛ ودخل الجيش الليتواني المدينة في 28 تشرين الأول/أكتوبر. وفي المقابل استقرت حاميات سوفييتية في ليتوانيا، وتبعها الضم سنة 1940.", "60d2f2bf"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["ألمانيا تحتل غرودنو", "b7ca9378"], "d": ["الجبهة الشرقية: بارباروسا 1941 وباغراتيون 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["ألمانيا تحتل بريست-ليتوفسك", "25898c65"], "d": ["الجبهة الشرقية: بارباروسا 1941 وباغراتيون 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["الجيش الألماني يستولي على بسكوف — بدء احتلال الأراضي الروسية", "d9822e30"], "d": ["دخل الفيرماخت بسكوف في الأسبوع الثالث من عملية بارباروسا؛ وبقيت المدينة حتى 23 تموز/يوليو 1944 تحت الإدارة العسكرية الألمانية. المصدر: التسلسل الزمني لمدينة بسكوف، memorialmuseums.org «Memorials in Pskov» — ملخص بحث [ملخص].", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["الجيش الألماني يستولي على فيتبسك", "e1e4d7d0"], "d": ["أخذت مجموعة جيوش الوسط فيتبسك في الأسابيع الأولى من بارباروسا؛ وبقيت المدينة حتى حزيران/يونيو 1944 تحت الإدارة العسكرية الألمانية، وفني القسم الأكبر من سكانها.", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["الجيش الألماني يستولي على سمولنسك", "5a7f4e2a"], "d": ["أخذت مجموعة جيوش الوسط سمولنسك؛ وبقيت هذه المدينة الواقعة على طريق موسكو محتلة 26 شهرًا حتى 25 أيلول/سبتمبر 1943 ولحق بها دمار كبير.", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["الجيش الألماني يستولي على موغيليف", "4362b7a1"], "d": ["صارت موغيليف في يد الفيرماخت بعد دفاع دام 23 يومًا؛ وبقيت المدينة محتلة حتى 28 حزيران/يونيو 1944.", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["تأسيس المفوضية الألمانية أوستلاند — دول البلطيق وبيلاروسيا تدخل الإدارة المدنية الألمانية", "052d4c08"], "d": ["سُلمت الأراضي المحتلة من الشرق إلى الإدارة المدنية بقرار هتلر في 17 تموز/يوليو 1941؛ وشملت أوستلاند، برئاسة هينريش لوزه، إستونيا ولاتفيا وليتوانيا وبيلاروسيا (المركز ريغا). وبدأت الإدارة المدنية في إستونيا في 5 كانون الأول/ديسمبر 1941، وبقي شرق بيلاروسيا في الإدارة العسكرية.", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["القوات الألمانية-الإستونية تستولي على نارفا", "60fc2b6a"], "d": ["أخذ المتطوعون الإستونيون والفيرماخت نارفا في حرب الصيف؛ وضُمت المدينة إلى أوستلاند وبقيت تحت الإدارة الألمانية حتى 26 تموز/يوليو 1944.", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["الجيش الألماني يستولي على نوفغورود", "4f599b62"], "d": ["أخذت مجموعة جيوش الشمال نوفغورود؛ وبقيت إحدى أقدم مدن روسيا محتلة حتى كانون الثاني/يناير 1944 وتعرضت لدمار واسع.", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["الجيش الألماني يستولي على غوميل", "9d78eb92"], "d": ["بعد ثلاثة أيام من هجوم الفيرماخت على غوميل انسحب الجيش الأحمر من المدينة انسحابًا تامًّا؛ وبقيت المدينة محتلة حتى 26 تشرين الثاني/نوفمبر 1943.", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["الجيش الألماني الثامن عشر يستولي على تالين", "a855ad0d"], "d": ["سقطت تالين بعد الإخلاء الدموي لأسطول البلطيق السوفييتي إلى كرونشتات؛ وصارت إستونيا Generalbezirk Estland داخل أوستلاند (الإدارة المدنية في 5 كانون الأول/ديسمبر 1941).", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["الجيش الألماني يستولي على أوريل", "3127f454"], "d": ["أخذ الجيش الألماني الثاني للدبابات أوريل في عملية بريانسك-فيازما؛ وبقيت المدينة محتلة حتى 5 آب/أغسطس 1943.", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["الجيش الألماني يستولي على بريانسك", "20fa93f8"], "d": ["دخلت القوات الألمانية المدينة في نهاية معركة بريانسك؛ وبقيت المدينة محتلة حتى 17 أيلول/سبتمبر 1943.", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["الجيش الألماني يستولي على كورسك", "a723a00a"], "d": ["أُخليت كورسك بأمر من القيادة السوفييتية، ودخل الجيش الألماني الثاني المدينة؛ وبقيت محتلة حتى 8 شباط/فبراير 1943.", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["الجيش الأحمر يحرر كورسك", "1ac03fba"], "d": ["استُعيدت كورسك في نهاية الهجوم الشتوي السوفييتي (اتجاه كورسك-خاركوف الذي تلا عملية فورونيج-كاستورنويه)؛ وفي تموز/يوليو من السنة نفسها أُطلق اسم المدينة على معركة كورسك.", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["الجيش الأحمر يستعيد أوريل — أول تحية سوفييتية بعد كورسك", "80bfc68d"], "d": ["الاستيلاء على جيب أوريل وإطلاق أول تحية مدفعية في موسكو مع بيلغورود.", "5714054b"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["الجيش الأحمر يستعيد بريانسك", "d0f2a35f"], "d": ["استُعيدت المدينة في 17 أيلول/سبتمبر 1943 بعملية بريانسك.", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["الجيش الأحمر يحرر سمولنسك", "6516d85a"], "d": ["استُعيدت المدينة في ذروة عملية سمولنسك في 7 آب/أغسطس-2 تشرين الأول/أكتوبر 1943؛ ونالت سمولنسك سنة 1985 لقب «المدينة البطلة».", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["الجيش الأحمر يحرر غوميل", "280268c2"], "d": ["استعادت الجبهة البيلاروسية المدينة في عملية غوميل-ريشيتسا؛ وهي من أوائل تحريرات المدن الكبرى في بيلاروسيا.", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["الجيش الأحمر يحرر نوفغورود", "52962012"], "d": ["استُعيدت فيليكي نوفغورود في 20 كانون الثاني/يناير 1944 في أثناء عملية لينينغراد-نوفغورود.", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["الجيش الأحمر يحرر فيتبسك — عملية باغراتيون", "b06be69c"], "d": ["حاصرت الجبهتان البلطيقية الأولى والبيلاروسية الثالثة فيتبسك وأخذتاها؛ وكان ذلك أول تحرير لمدينة كبيرة في عملية باغراتيون.", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["الجيش الأحمر يحرر موغيليف — عملية باغراتيون", "52fa985d"], "d": ["أخذت الجبهة البيلاروسية الثانية موغيليف وعبرت خط الدنيبر.", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["الجيش الأحمر يستعيد مينسك — عملية باغراتيون", "87dc1fb5"], "d": ["في عملية باغراتيون التي بدأت في 22 حزيران/يونيو شقّت الجبهات البيلاروسية مجموعة جيوش الوسط وحاصرت مينسك؛ واستُعيدت المدينة في 3 تموز/يوليو وبقي في الشرق نحو 50 ألف جندي ألماني في الطوق. وانهارت الإدارة المدنية الألمانية في بيلاروسيا (Generalbezirk Weißruthenien).", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["الجيش الأحمر يأخذ فيلنيوس", "0172450e"], "d": ["في عملية فيلنيوس في 5-13 تموز/يوليو حاصرت الجبهة البيلاروسية الثالثة الحامية الألمانية وأخذت المدينة (وكانت عملية «أوسترا براما» للجيش الداخلي البولندي متزامنة). وصارت فيلنيوس عاصمة جمهورية ليتوانيا الاشتراكية السوفييتية.", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["الجيش الأحمر يحرر غرودنو من الاحتلال الألماني", "1d134151"], "d": ["الجبهة الشرقية: بارباروسا 1941 وباغراتيون 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["الجيش الأحمر يستعيد بسكوف", "f18103aa"], "d": ["استعاد الجيش الأحمر بسكوف بعد احتلال ألماني دام أكثر من ثلاث سنوات.", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["الجيش الأحمر يأخذ نارفا", "64854ae3"], "d": ["أخذت القوات السوفييتية نارفا، التي ظلت مدمرة على خط الجبهة منذ شباط/فبراير 1944، في عملية نارفا في تموز/يوليو 1944؛ وخرج شمال شرق إستونيا من يد الإدارة المدنية الألمانية (Generalbezirk Estland).", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["الجيش الأحمر يأخذ ريزكنه — شرق لاتفيا يتحرر", "e9efd12d"], "d": ["أخذت الجبهة البلطيقية الثانية ريزكنه؛ وخرج إقليم لاتغاله في لاتفيا من الإدارة الألمانية.", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["الجيش الأحمر يحرر داوغافبلس", "b4ee6622"], "d": ["أخذت الفرقة المشاة 360 من الجبهة البلطيقية الثانية داوغافبلس (دونابورغ)؛ وخرجت ثاني أكبر مدن لاتغاله من الإدارة الألمانية.", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["الجيش الأحمر يأخذ شياولياي — عملية شياولياي", "ccb20729"], "d": ["أخذت الجبهة البلطيقية الأولى شياولياي، العقدة الحديدية في شمال ليتوانيا؛ واستمرت العملية من 5 تموز/يوليو إلى 29 آب/أغسطس 1944 وبلغت خليج ريغا.", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["الجيش الأحمر يحرر بريست-ليتوفسك من الاحتلال الألماني", "6d5a837a"], "d": ["الجبهة الشرقية: بارباروسا 1941 وباغراتيون 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["الجيش الأحمر يأخذ كاوناس — العاصمة المؤقتة لليتوانيا تخرج من الإدارة الألمانية", "5c2b2c16"], "d": ["أخذت الجبهة البيلاروسية الثالثة كاوناس؛ وأعلن أمر ستالين اليومي في 1 آب/أغسطس خبر أخذها. وكانت المدينة العاصمة المؤقتة لليتوانيا في 1919-1939.", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["الجيش الأحمر يأخذ تارتو — عملية تارتو", "cc8069ab"], "d": ["كسرت الجبهة البلطيقية الثالثة دفاع الجيش الألماني الثامن عشر وأخذت تارتو؛ وبقيت المدينة أسابيع قليلة على خط الجبهة، وانتهت عملية تارتو في 6 أيلول/سبتمبر 1944.", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["الجيش الأحمر يدخل تالين — القوات الألمانية تترك المدينة", "41ae1ec5"], "d": ["ترك الألمان المدينة في أثناء عملية تالين؛ ولم تستطع حكومة اللجنة الوطنية الإستونية، التي استولت على مباني الحكومة في 18 أيلول/سبتمبر، الحفاظ على الإدارة حين دخل الجيش الأحمر. وعادت إستونيا إلى الإدارة السوفييتية.", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["الجيش الأحمر يأخذ ميميل (كلايبيدا)", "d01ad3dc"], "d": ["في العملية السوفييتية المتجهة إلى بروسيا الشرقية وساحل البلطيق، أُخذ ميناء ميميل (كلايبيدا) من ألمانيا وضُم إلى جمهورية ليتوانيا الاشتراكية السوفييتية. وبذلك خرجت المنطقة التي تنازلت عنها ليتوانيا لألمانيا سنة 1939 من الإدارة الألمانية.", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["استسلام جيب كورلاند — مجموعة جيوش كورلاند توقع الاستسلام لغوفوروف", "3c88889b"], "d": ["استسلمت مجموعة جيوش كورلاند الألمانية، التي كانت محاصَرة حول ليباجا-فنتسبيلس منذ تشرين الأول/أكتوبر 1944؛ وانتقل غرب لاتفيا إلى السيطرة السوفييتية.", "a7bfcc52"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["قلاع إستراندجا: فتح پينارحصار وقرق كليسة (قرقلار إيلي) ووزة", "c6b1a9c1"], "d": ["قضى مراد الأول شتاء 1369 في قصر أدرنة، وتحرك في الربيع من جديد ضد البيزنطيين، فأخذ قلاع پينارحصار وقرق كليسة ووزة عند سفوح جبال إستراندجا. وأثارت هذه الفتوح ذعرًا في القسطنطينية، وقرر الإمبراطور يوحنا الخامس أن يذهب إلى البابا طلبًا للعون.", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["انتقال طشقند إلى إدارة خان المغولستان يونس خان", "a37ee010"], "d": ["في أثناء الصراع على العرش بين الأمراء التيموريين آلت طشقند وما حولها إلى يونس خان، خان جغتاي الشرقية (المغولستان). وبعد وفاة يونس خان بعد سنتين خلفه ابنه محمود خان؛ وبقيت المدينة لدى الخانات المغول حتى استولى عليها أوزبك شيباني خان عام 1503.", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["بابر يترك فرغانة للأوزبك ويتوجه إلى كابل", "69df593c"], "d": ["ترك بابر التيموري، ابن عمر شيخ ميرزا، فرغانة التي حكمها منذ عام 1494 للأوزبك بعد حروبه مع محمد شيباني خان، وعبر الهندكوش واستقر في كابل.", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["بيري ريس يرسم أقدم خريطة للعالم وصلت إلينا", "6ef941f5"], "d": ["رسم بيري ريس في غاليبولي خريطة العالم المؤرخة 919 (1513)؛ وبحسب موسوعة TDV الإسلامية فمن مصادر الخريطة «الخرائط القديمة التي وصلته من العالمين الشرقي والغربي وخريطة كريستوف كولومبوس» — أي يُظن أنها تحمل آثار خريطة كولومبوس الملاحية الأصلية التي عُدّت في ذلك الزمن مفقودة. وقدّم الخريطة إلى السلطان ياووز سليم في القاهرة سنة 923 (1517). ولم يصل إلينا منها سوى قطعة تُظهر السواحل الغربية/الأطلسية فحسب (إسبانيا والبرتغال وغرب إفريقيا والساحل الشرقي لأمريكا الجنوبية)؛ وقد أُعيد اكتشاف هذه القطعة في قصر طوب قابي سنة 1929 وهي مدرجة في سجل ذاكرة العالم لدى اليونسكو.", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["اكتمال منطقة قارص: شورغل وأربا چاي ودكور تدخل الإدارة العثمانية", "10f16b5c"], "d": ["في حملة العراقين وقعت قلاع باسين وشورغل وأولتو في يد العثمانيين؛ ويرجح بقوة أن قلعة قارص أُلحقت أيضًا في هذه الأثناء بالقوة. ودخلت منطقة أربا چاي ودكور، شمال قارص وشرقها، السيطرة العثمانية بالعملية نفسها.", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["نهاية الشروانشاهيين: ألقاس ميرزا يأسر شاهرخ وشيروان تصبح ولاية صفوية", "e6d64114"], "d": ["نهب ألقاس ميرزا، الذي أرسله الشاه طهماسب، شيروان واستولى على قلعة بايكورد، وأسر الشروانشاه شاهرخ، وكان في الخامسة عشرة من عمره، وساقه إلى تبريز. وبذلك انتهت إدارة الشروانشاهيين التي استمر سلطانها في المنطقة زمنًا طويلًا؛ وصارت شيروان ولاية من ولايات الدولة الصفوية.", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["توسع أوجاق الجزائر نحو الصحراء — إخضاع تقرت وورقلة للجزية، والفتح النهائي لتلمسان", "705ec920"], "d": ["بحسب مادة تلمسان في TDV فإن جيشًا كبيرًا أُرسل من الجزائر سنة 960 (1553) بقيادة صالح رايس استولى على المدينة استيلاءً نهائيًّا وأنهى الأسرة الزيانية التي دامت ثلاثة قرون. وفي الفترة نفسها (1552) نظم صالح رايس حملة على سلطنتي تقرت وورقلة المستقلتين؛ فأخذت القوات العثمانية تقرت، وتقدمت إلى ورقلة، وأُخضعت السلطنتان للجزية؛ وتُركت حامية عثمانية دائمة في بسكرة التي تقع على الطريق. وبذلك بلغت حدود أوجاق الجزائر لأول مرة، متجاوزةً الأطلس التلي، ساحل الصحراء. أما المعركة الكبرى أمام مستغانم فلم تقع في هذه السنة بل في 1558: فقد هزم حسن باشا هناك الكونت الإسباني ألكوديت وأنهى الهجمات الإسبانية في شمال إفريقيا.", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["تأسيس إيالة الحبش — ساحل البحر الأحمر يدخل الإدارة العثمانية", "7dd470ec"], "d": ["أُسست رسميًّا الإيالة التي أُنشئت لمنع تسلل البرتغال إلى البحر الأحمر عبر الحبشة، بحسب مادة إيالة الحبش في TDV، في 15 شعبان 962 (5 تموز/يوليو 1555)، وكان مركز السنجق سواكن. وبدأ أوزدمير باشا العمليات في خريف 1555؛ فأخذ جزر دهلك التي تسيطر على ميناء مصوع، وفي 2 نيسان/أبريل 1557 أخذ مدينة مصوع ثم أركيكو. واستمر الفتح بدخول إيالة تيغري سنة 1558 وداربوا سنة 1559 تحت السيادة العثمانية.", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["تعيين صدفكار محمد آغا رئيسًا للمعماريين — معمار جامع السلطان أحمد", "27b66fce"], "d": ["أُخذ محمد آغا إلى القصر دوشرمة سنة 1562-1563 من بلدة إلباسان في ألبانيا، وتربّى عند المعمار سنان، وعُيّن في 11 تشرين الأول/أكتوبر 1606 رئيسًا للمعماريين العثمانيين. وتنقل موسوعة TDV الإسلامية أن مصدرًا معاصرًا وصفه بأنه «لين الطبع متواضع صادق الوعد متدين ذكي». وشرع محمد آغا بعد ثلاث سنوات بأمر من أحمد الأول في بناء جامع السلطان أحمد، وله أعمال واسعة من الإصلاحات في الكعبة إلى عدد كبير من السبل والجوامع في إسطنبول وأدرنة. وثمة رواية شعبية شائعة بأن المآذن الست أثارت جدلًا حول «المساواة» مع الكعبة في مكة؛ والمصادر الموسوعية لا تؤكد ذلك، وتصف الترتيب فحسب بأنه «لم يُجرَّب حتى ذلك الحين».", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["السلطان الجديد مصطفى الأول: سجين «القفص» شاحب الوجه شارد النظرات على العرش", "c487b0d1"], "d": ["كان مصطفى الأول، الذي اعتلى العرش بوفاة أحمد الأول، أول شهزاده تركه أخوه حيًّا، وقد عاش سنوات مغلقًا عليه في القصر تحت رقابة مشددة؛ وتصفه موسوعة TDV الإسلامية بأنه «شاحب الوجه، قليل اللحية، كبير العينين السوداوين، جامد النظرات»، وتسجل أن هذا السجن الطويل زاد حالته النفسية سوءًا. ولم يستطع في سلطنته الأولى هذه التي دامت ستة وتسعين يومًا تسيير أمور الدولة؛ وفي المقابل يُروى أنه كان يخرج كثيرًا للصيد ويتجول في الترسانة بل ويلقي الذهب في الماء ويتفرج على الأسماك. وخلعه الأوجاق الإنكشاري والعلماء في 26 شباط/فبراير 1618 لعدم صلاحيته للحكم، وأجلسوا مكانه ابن أخيه عثمان الثاني ذا الأربعة عشر عامًا.", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["رؤيا أوليا چلبي في السفر — أن يقول «سياحة» وهو يريد «شفاعة»", "2d863e22"], "d": ["بحسب موسوعة TDV الإسلامية يربط أوليا چلبي بداية حياة الترحال التي ستدوم أربعين سنة برؤيا رآها في ليلة عاشوراء من محرم سنة 1040 (19 آب/أغسطس 1630): رأى في منامه النبي ﷺ في جامع أخي چلبي بإسطنبول مع جماعة غفيرة، وقال من شدة اضطرابه «سياحة يا رسول الله» بدلًا من «شفاعة يا رسول الله». وبحسب الرواية ابتسم النبي ﷺ لهذه الزلة وبشّره بالشفاعة والسياحة والزيارة معًا. ولم يتزوج قط، وكرّس حياته لهذا الوعد بـ«السياحة».", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["تناقضات مراد الرابع: تحريم الخمر على سلطان مولع بها، ومعصم المصارع، وأذن الملحن", "3d2ea5e0"], "d": ["كان نفوذ أمه كوسم سلطان حاسمًا في السنوات الأولى لمراد الرابع الذي اعتلى العرش وهو في الحادية عشرة؛ وتنقل موسوعة TDV الإسلامية أن كوسم خافت من ميل ابنها إلى السلطة فـ«ساقته إلى اللهو وألهته بالهدايا والاحتفالات». وحين تولى الحكم فعليًّا في نحو العشرين من عمره كان سلطانًا طويل القامة عريض المنكبين مهيبًا — ويُروى أنه كان يحمل رجلًا قويًّا من حزامه ويدور به عدة مرات في الغرفة الخاصة. أما التناقض اللافت الذي سجلته TDV فهو: أن السلطان الذي قيل إنه كان يمقت التبغ والأفيون كان مولعًا بالخمر ولعًا شديدًا، ومع ذلك حظر قبل الحملة القهوة والتبغ ثم الخمر نفسها فيما بعد؛ وكان في الوقت نفسه واسع المعرفة بالموسيقى بحيث يلحّن وفق تقليد المقام.", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["طيران لاغاري حسن چلبي بالصاروخ — رواية لا مصدر لها إلا أوليا چلبي", "1f02e3f2"], "d": ["بحسب «سياحتنامه» لأوليا چلبي صنع لاغاري حسن چلبي بين يدي مراد الرابع في سراي بورنو جهازًا من سبعة أذرع بخمسين أقة من البارود، وركب الصاروخ قائلًا: «يا مولاي، أستودعك الله، ذاهب لأتحدث مع النبي عيسى». وبحسب الرواية ارتفع حسن چلبي نحو 250 مترًا، ثم انساب إلى البحر بأجهزة تشبه جناحي الصقر وسبح وعاد إلى السلطان، فنال في المقابل سباهيًا براتب يومي سبعين أقجة.", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["قمانكش قره مصطفى باشا يصير صدرًا أعظم — بدء عهد الإصلاح المالي", "583846a4"], "d": ["طبّق قمانكش قره مصطفى باشا، الذي صار وزيرًا أعظم في 17 شعبان 1048 (24 كانون الأول/ديسمبر 1638) بعد استشهاد طيار محمد باشا في حملة بغداد، انضباطًا ماليًّا صارمًا في عهد السلطان إبراهيم: فخفض عدد الإنكشارية والسباهية إلى الثلث، وأصلح عيار النقد، وشدّد نظام النرخ. وبحسب الرقم الذي تورده TDV بلغ هذا التوفير 6000 كيسة في السنة — لكن هذه الرقابة المشددة جلبت له الأعداء في محيط القصر.", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["وفاة مصطفى الأول بعد نسيان دام خمس عشرة سنة", "b4c872cd"], "d": ["عاش مصطفى الأول، الذي خُلع للمرة الثانية في 10 أيلول/سبتمبر 1623، في غرفة مغلقة طوال الخمس عشرة سنة حتى وفاته؛ ولا توجد في المصادر أي معلومة عن هذه السنين. وتوفي في 15 رمضان 1048 (20 كانون الثاني/يناير 1639) — وبعض المصادر تعدّه موتًا طبيعيًّا وبعضها يزعم أن لمراد الرابع يدًا فيه.", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["«إبراهيم المجنون» أم علة متقلبة؟", "2abc230f"], "d": ["ترفض موسوعة TDV الإسلامية رفضًا صريحًا وصف «إبراهيم المجنون» الذي شاع في القرن العشرين؛ وتنقل أن السلطان كان يشكو في رسائله الخاصة من الآلام وفقدان الشهية وضعف الساقين وشعور الضباب في الرأس وضيق الصدر ونوبات الإغماء. وفي المقابل فإن أجوبته المتسقة المعقولة في أثناء عملية الخلع تتناقض مع الزعم باختلال دائم؛ وتصل المادة إلى أن حالته «لم تكن ثابتة بل متغيرة الشدة». وفي هذه الفترة ازدادت مسؤوليات كوسم سلطان تدريجيًّا، وكبّر قدرتها على التدخل في السياسة تقديم جنجي خوجا، الذي دُعي إلى القصر، العزاء المعنوي للسلطان «بأدعية مؤثرة».", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["واقعة السمور — ضريبة الفراء التي فرضها الصدر الأعظم أحمد باشا مهّدت لنهاية إبراهيم", "a2a47d62"], "d": ["في حين كان ولع السلطان إبراهيم بفراء السمور والعنبر يتعاظم في القصر، بدأ الصدر الأعظم أحمد باشا نحو 1647-1648 ممارسة تجمع من رجال الدولة بالإكراه ثمن فراء السمور؛ وتسجل موسوعة TDV الإسلامية أن المسؤولين عدّوا ذلك «خراجًا» صريحًا. ولما رفض ضباط الإنكشارية الدفع جماعةً صارت هذه المقاومة المحرّك المباشر للعملية التي أفضت إلى خلع السلطان — ففي صباح 7 آب/أغسطس 1648 قتل المسؤولون المجتمعون أحمد باشا أولًا، وخلعوا إبراهيم في اليوم التالي.", "596c6d08"]}
});
